INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Babytiann/Piko/piko-frontend-standards', 'community', 'Babytiann', 'Piko', 'Babytiann/Piko', 'piko-frontend-standards', 0, 0, 49, '2026-03-04T13:07:01.908Z', '2026-03-04T14:59:54.275Z', 'd14dd2a1b3e189914858737a4c1470c306217631be2314906fdec15977baab18', '{"id":"Babytiann/Piko/piko-frontend-standards","name":"piko-frontend-standards","description":{"zh":"piko-frontend-standards是一个个人AI助手，支持绑定Telegram和openclaw交互，自动搜集付款信息和记账等功能","ja":"piko-frontend-standardsは個人用AIエージェントで、Telegramとopenclawの連携、自動収集の支払い情報と記帳などの機能をサポート","ko":"piko-frontend-standards는 개인용 AI 에이전트로 텔레그램과 openclaw 연동, 자동 수집의 지불 정보와 기록 등의 기능을 지원","es":"piko-frontend-standards es un agente de IA que ofrece funciones de pago y contabilidad automática para desarrolladores","fr":"piko-frontend-standards est un agent IA qui propose des fonctionnalités de paiement et de comptabilité automatique pour les développeurs","de":"piko-frontend-standards ist ein KI-Agent, der Funktionen für automatische Zahlung und Buchhaltung für Entwickler bietet","pt":"O piko-frontend-standards é um assistente AI que automatiza tarefas e fornece funcionalidades de pagamento e contabilidade para desenvolvedores","ru":"ИИ Агент piko-frontend-standards - это инструмент, который автоматизирует задачи и предоставляет функции оплаты и бухгалтерского учета для разработчиков","ar":"وكيل الذكاء الاصطناعي piko-frontend-standards هو أداة تؤتم tasks وتوفر ميزات الدفع والمتاجرة لمطوري البرمجيات","en":"个人 ai 助手，支持绑定 Telegram 以访问 bot 与 openclaw 交互、支持自动搜集付款信息，自动记账等功能拓展"},"seo":{"title":{"zh":"AI智能助手 piko-frontend-standards","ja":"AIエージェント piko-frontend-standards","ko":"AI 에이전트 piko-frontend-standards","es":"Agentes de IA: piko-frontend-standards","fr":"Agents IA: piko-frontend-standards","de":"KI-Agenten: piko-frontend-standards","pt":"Assistente AI piko-frontend-standards para Desenvolvedores","ru":"ИИ Агент piko-frontend-standards для Разработчиков","ar":"وكيل الذكاء الاصطناعي piko-frontend-standards لمطوري البر...","en":"piko-frontend-standards"},"description":{"zh":"piko-frontend-standards是一个个人AI助手，支持绑定Telegram和openclaw交互，自动搜集付款信息和记账等功能","ja":"piko-frontend-standardsは個人用AIエージェントで、Telegramとopenclawの連携、自動収集の支払い情報と記帳などの機能をサポート","ko":"piko-frontend-standards는 개인용 AI 에이전트로 텔레그램과 openclaw 연동, 자동 수집의 지불 정보와 기록 등의 기능을 지원","es":"piko-frontend-standards es un agente de IA que ofrece funciones de pago y contabilidad automática para desarrolladores","fr":"piko-frontend-standards est un agent IA qui propose des fonctionnalités de paiement et de comptabilité automatique pour les développeurs","de":"piko-frontend-standards ist ein KI-Agent, der Funktionen für automatische Zahlung und Buchhaltung für Entwickler bietet","pt":"O piko-frontend-standards é um assistente AI que automatiza tarefas e fornece funcionalidades de pagamento e contabilidade para desenvolvedores","ru":"ИИ Агент piko-frontend-standards - это инструмент, который автоматизирует задачи и предоставляет функции оплаты и бухгалтерского учета для разработчиков","ar":"وكيل الذكاء الاصطناعي piko-frontend-standards هو أداة تؤتم tasks وتوفر ميزات الدفع والمتاجرة لمطوري البرمجيات","en":"个人 ai 助手，支持绑定 Telegram 以访问 bot 与 openclaw 交互、支持自动搜集付款信息，自动记账等功能拓展"},"definition":{"en":"个人 ai 助手，支持绑定 Telegram 以访问 bot 与 openclaw 交互、支持自动搜集付款信息，自动记账等功能拓展"},"features":{"zh":["支持绑定Telegram","自动搜集付款信息","自动记账","支持openclaw交互","提升开发效率"],"ja":["Telegram連携のサポート","自動収集の支払い情報","自動記帳","openclawの連携","開発効率の向上"],"ko":["텔레그램 연동 지원","자동 수집의 지불 정보","자동 기록","openclaw 연동","개발 효율성 향상"],"es":["Soporte para Telegram","Pago automático","Contabilidad automática","Integración con openclaw","Acceso a bot"],"fr":["Prise en charge de Telegram","Paiement automatique","Comptabilité automatique","Intégration avec openclaw","Accès à bot"],"de":["Unterstützung für Telegram","Automatische Zahlung","Automatische Buchhaltung","Integration mit openclaw","Zugriff auf bot"],"pt":["Integração com Telegram","Automatização de tarefas","Funcionalidades de pagamento","Contabilidade automática","Suporte a openclaw"],"ru":["Интеграция с Telegram","Автоматизация задач","Функции оплаты","Автоматический бухгалтерский учет","Поддержка openclaw"],"ar":["التكامل مع Telegram","الآلية المهام","ميزات الدفع","المتاجرة الآلية","دعم openclaw"]},"keywords":{"zh":["AI智能助手","如何使用piko-frontend-standards","piko-frontend-standards安装","piko-frontend-standards设置指南","AI工具","开发效率","自动记账","Telegram连结"],"ja":["AIエージェント","piko-frontend-standardsの使い方","piko-frontend-standardsのインストール","piko-frontend-standardsの設定ガイド","AIツール","開発効率","自動記帳","Telegram連携"],"ko":["AI 에이전트","piko-frontend-standards 사용법","piko-frontend-standards 설치","piko-frontend-standards 설정 가이드","AI 도구","개발 효율성","자동 기록","텔레그램 연동"],"es":["cómo usar piko-frontend-standards","qué es un agente de IA","piko-frontend-standards alternativa","piko-frontend-standards vs openclaw","instalación de piko-frontend-standards","guía de configuración de piko-frontend-standards","desarrollo de agentes de IA","herramientas de pago automático"],"fr":["comment utiliser piko-frontend-standards","qu''est-ce qu''un agent IA","alternative à piko-frontend-standards","piko-frontend-standards vs openclaw","installation de piko-frontend-standards","guide de configuration de piko-frontend-standards","développement d''agents IA","outils de paiement automatique"],"de":["wie man piko-frontend-standards verwendet","was ist ein KI-Agent","Alternative zu piko-frontend-standards","piko-frontend-standards vs openclaw","Installation von piko-frontend-standards","Konfigurationsanleitung für piko-frontend-standards","Entwicklung von KI-Agents","Tools für automatische Zahlung"],"pt":["assistente AI","ferramentas de desenvolvimento","automatização de tarefas","pagamento online","contabilidade para desenvolvedores","piko-frontend-standards alternative","como usar piko-frontend-standards","instalar piko-frontend-standards","guia de configuração piko-frontend-standards"],"ru":["ИИ Агент","инструменты разработки","автоматизация задач","оплата онлайн","бухгалтерский учет для разработчиков","ИИ Агент piko-frontend-standards alternative","как использовать piko-frontend-standards","установка piko-frontend-standards","руководство по настройке piko-frontend-standards"],"ar":["وكيل الذكاء الاصطناعي","أدوات تطوير البرمجيات","الآلية المهام","دفع عبر الإنترنت","المتاجرة لمطوري البرمجيات","وكيل الذكاء الاصطناعي piko-frontend-standards بديل","كيفية استخدام piko-frontend-standards","تثبيت piko-frontend-standards","دليل إعداد piko-frontend-standards"]}},"owner":"Babytiann","repo":"Piko","repoPath":"Babytiann/Piko","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.908Z","topics":[],"category":"community","skillMd":{"name":"piko-frontend-standards","description":"Enforces strict frontend code standards for the Piko Expo/React Native project. Covers page-autonomous architecture, component design, hook taxonomy, type safety, style system, API layer, error handling, and naming conventions. Use when writing, reviewing, or refactoring any frontend code. Automatically apply when creating new components, hooks, services, or types.","bodyPreview":"# Piko Frontend Code Standards\n\n> 严格派：代码即文档，每一行都有存在的理由。\n\n## Core Philosophy\n\n1. **Code as Documentation** — 代码即文档，命名自解释，拒绝冗余注释\n2. **Page Autonomy** — 每个页面是自包含单元，拥有自己的 components/hooks/types/consts/utils\n3. **Single Responsibility** — 一个函数/组件/hook 只做一件事\n4. **Composition over Complexity** — Slot 组合 > 巨型组件，Hook 组合 > 万能 Hook\n5. **Explicit over Implicit** — 所有返回类型显式标注，所有 Promise 要么 await 要么 void\n6. **Type as Contract** — 类型系统是模块间的契约，用判别联合而非松散可选字段\n7. **Fail Fast, Fail Loud** — 纯函数映射错误类型，不在 hook 里硬编码错误","body":"# Piko Frontend Code Standards\n\n> 严格派：代码即文档，每一行都有存在的理由。\n\n## Core Philosophy\n\n1. **Code as Documentation** — 代码即文档，命名自解释，拒绝冗余注释\n2. **Page Autonomy** — 每个页面是自包含单元，拥有自己的 components/hooks/types/consts/utils\n3. **Single Responsibility** — 一个函数/组件/hook 只做一件事\n4. **Composition over Complexity** — Slot 组合 > 巨型组件，Hook 组合 > 万能 Hook\n5. **Explicit over Implicit** — 所有返回类型显式标注，所有 Promise 要么 await 要么 void\n6. **Type as Contract** — 类型系统是模块间的契约，用判别联合而非松散可选字段\n7. **Fail Fast, Fail Loud** — 纯函数映射错误类型，不在 hook 里硬编码错误逻辑\n\n## Comments: Less is More\n\n```\nMUST:  用清晰的函数名/变量名/类型名替代注释\nMUST:  复杂算法或非直觉的业务规则才需要注释\nMUST:  注释解释 WHY，不解释 WHAT (代码本身说明 what)\nNEVER: 函数签名上方加 JSDoc 复述参数名和类型 — TypeScript 已经表达了\nNEVER: 注释掉的代码 — 直接删除，git 有历史\nNEVER: 分隔线注释 (// ────────) — 用空行和函数拆分表达结构\nNEVER: \"显而易见\"的注释 (// 设置 loading 为 true → setIsLoading(true))\n```\n\n## Architecture: Page-Autonomous Structure\n\n```\nfrontend/\n├── app/                           # Expo Router 路由 (Screen 层)\n│   ├── _layout.tsx\n│   ├── (tabs)/\n│   │   ├── index.tsx              # → 编排 pages/home 的内容\n│   │   ├── ai/index.tsx\n│   │   └── profile/index.tsx\n│   └── chat/[id].tsx\n│\n├── pages/                         # 页面业务单元 (每个页面自包含)\n│   ├── home/\n│   │   ├── components/            # 页面私有组件\n│   │   ├── hooks/                 # 页面私有 hooks\n│   │   ├── types/                 # 页面私有类型\n│   │   ├── consts/                # 页面私有常量\n│   │   └── utils/                 # 页面私有工具函数\n│   ├── profile/\n│   │   ├── components/\n│   │   ├── hooks/\n│   │   └── types/\n│   └── chat/\n│       ├── components/\n│       ├── hooks/\n│       └── types/\n│\n├── common/                        # 跨页面共享\n│   ├── components/\n│   │   ├── page-loading/          # 通用加载\n│   │   ├── page-status-view/      # 通用错误/空态 + getPageErrorType()\n│   │   ├── biz/                   # 业务级共享组件\n│   │   └── product-card/          # 可复用卡片 (Slot 组合)\n│   ├── hooks/                     # 通用 hooks (useAuth, useSafeArea)\n│   │   └── index.ts              # Barrel re-export\n│   ├── typings/                   # 共享类型定义\n│   └── consts/                    # 全局常量\n│\n├── services/                      # API client + 页面级数据获取\n│   ├── api-client.ts             # 底层请求封装 (post, postSafe, postDirect)\n│   ├── home.ts                   # 首页数据获取\n│   ├── chat.ts                   # 聊天数据获取\n│   ├── profile.ts                # 个人资料数据获取\n│   └── telegram.ts               # Telegram 认证 & 消息 API\n│\n├── lib/                           # 框架级配置（如认证客户端）\n│   └── auth-client.ts            # Better Auth 客户端 (createAuthClient)，session/Cookie 与后端一致\n│\n├── contexts/                      # Context 定义\n└── utils/                         # 全局工具函数\n```\n\n### 关键原则\n\n```\nMUST:  页面私有代码放 pages/{page}/ 下，不放 common/\nMUST:  跨 2 个以上页面复用的代码提升到 common/\nMUST:  数据获取逻辑放 services/ (按页面分文件)，不内联在组件中\nMUST:  common/hooks/index.ts barrel re-export 所有公共 hooks\nMUST:  页面私有工具函数放 pages/{page}/utils/，一个文件一个主函数\nMUST:  utils/ 文件名 = 主函数名 (kebab-case)，如 calc-column-widths.ts\nMUST:  utils/index.ts barrel re-export 所有工具函数\nMUST:  utils/ 仅含纯函数 — 不含 hooks / 组件 / 副作用\nNEVER: 工具函数内联在组件文件中 — 提取到 utils/\nNEVER: 页面级 hooks/components 目录创建 barrel index.ts — 直接 import 具体文件\nNEVER: 页面 A 直接 import 页面 B 的私有模块\nNEVER: common/ 下的代码 import pages/ 下的代码 (依赖方向: pages → common)\n```\n\n## Component Patterns\n\n### 分类与位置\n\n| 类型           | 位置                       | 职责                   |\n| -------------- | -------------------------- | ---------------------- |\n| Screen         | `app/`                     | 路由入口，编排页面组件 |\n| Page Component | `pages/{page}/components/` | 页面私有 UI            |\n| Biz Shared     | `common/components/biz/`   | 跨页面业务组件         |\n| Base Shared    | `common/components/`       | 通用 UI，零业务        |\n\n### 规则\n\n```\nMUST:  Props 接口命名: 文件内用 Props，跨文件导出用 {ComponentName}Props\nMUST:  显式返回类型: (props: Props): ReactNode => { ... }\nMUST:  页面内组件用页面前缀: Chat 页的组件用 Chat 前缀 (ChatBubble, ChatInput)\nMUST:  条件渲染统一三元: {condition ? <X /> : null}\nMUST:  空状态统一 return null\nMUST:  Slot 组合: 通过 leftArea/title/footer 等 ReactNode props 组合复杂布局\nMUST:  多组件文件 — 主组件 index.tsx + 子组件各自独立文件，放同名文件夹下\nMUST:  子组件文件名 = 组件名 (kebab-case)，如 waiting-indicator.tsx\nALLOW: 极简渲染辅助 (无 hooks、1-3 行 JSX) — 可用箭头函数常量留在同文件\nMUST:  组件文件内的非公用辅助函数使用箭头函数常量 (const fn = (...): T => { ... })，不用 function 声明\nNEVER: function 声明式定义多个组件在同一文件\nNEVER: 超过 150 行的组件 — 拆分,依据具体情况拆分，如果真的要这么多，那就不拆了\nNEVER: Props 透传超过 2 层 — 用 Context\n```\n\n### Slot 组合示例\n\n```typescript\ninterface Props<T> {\n  data: T;\n  leftArea?: ReactNode;\n  title?: ReactNode;\n  subtitle?: ReactNode;\n  operationArea?: ReactNode;\n  onPress?: (data: T) => void;\n}\n\nexport default function CardContainer<T>({ data, leftArea, title, subtitle, operationArea, onPress }: Props<T>): ReactNode {\n  return (\n    <XStack onPress={() => onPress?.(data)}>\n      {leftArea ? <YStack flexShrink={0}>{leftArea}</YStack> : null}\n      <YStack flex={1}>\n        {title ? title : null}\n        {subtitle ? subtitle : null}\n        {operationArea ? operationArea : null}\n      </YStack>\n    </XStack>\n  );\n}\n```\n\n## Hook Taxonomy\n\n### 前置规则: 禁止空壳 re-export\n\n```\nNEVER: 创建只做 re-export 的 hook 文件 (如 export { useX } from ''lib'')\n       → 直接从源库导入，空壳文件是死代码的温床\nONLY:  当你封装了自定义逻辑时，才值得创建 hook 文件\n```\n\n### useCallback / useMemo 使用规则\n\n```\nNEVER: 默认给事件处理函数套 useCallback，给计算结果套 useMemo — 大多数场景没有收益\nONLY:  useCallback: 回调传给 React.memo 子组件，或作为 useEffect/useMemo 的依赖\nONLY:  useMemo: 计算确实昂贵 (大数组遍历、复杂格式化)，或结果作为 useEffect 的依赖需要稳定引用\nMUST:  简单赋值/三元/条件判断直接写，不套 useMemo\nMUST:  组件内部的事件处理函数直接写普通函数，不套 useCallback\n```\n\nHooks 严格分三类，每类有明确的约束：\n\n### ① 数据 Hook (Data Hook)\n\n职责：获取数据 + 管理 loading/error 状态。返回结构化对象。\n\n```\nMUST:  返回命名字段: { isLoading, errorType, data, handleRetry, handleRefresh }\nMUST:  错误映射使用纯函数 getPageErrorType()，不在 hook 中硬编码\nMUST:  最多 1 个 useEffect (初始加载)\nMUST:  返回类型显式定义为 interface\nMUST:  使用 state trigger (fetchKey) + useEffect 重新触发请求，不用 useCallback 包裹请求逻辑\nMUST:  useEffect cleanup 设置 cancelled 标记防止竞态更新\nNEVER: useCallback 包裹网络请求函数 — 请求只在 useEffect 内发起\n```\n\n#### 标准 Data Hook 模式\n\n```typescript\n// 简单模式: 加载 + 重试\nconst [fetchKey, setFetchKey] = useState<number>(0);\n\nuseEffect(() => {\n  let cancelled = false;\n  setIsLoading(true);\n  setErrorType(undefined);\n\n  async function load(): Promise<void> {\n    try {\n      const response = await fetchXxxPage();\n      if (cancelled) return;\n      const mappedError = getPageErrorType(response);\n      if (mappedError) {\n        setErrorType(mappedError);\n        setData(null);\n      } else {\n        setData(response.data ?? null);\n      }\n    } catch {\n      if (cancelled) return;\n      setErrorType(PageErrorType.NETWORK);\n      setData(null);\n    } finally {\n      if (!cancelled) setIsLoading(false);\n    }\n  }\n\n  void load();\n  return () => {\n    cancelled = true;\n  };\n}, [fetchKey]); // + 其他依赖如 session\n\nconst handleRetry = (): void => {\n  setFetchKey((k) => k + 1);\n};\n```\n\n### ② 派生 Hook (Derived Hook)\n\n职责：纯计算/数据转换，零副作用。只用 `useMemo`。\n\n```\nMUST:  只使用 useMemo，不使用 useEffect / useState\nMUST:  纯函数语义: 相同输入永远相同输出\nMUST:  命名体现数据来源: useDataFromQuery, useFormattedPrice\n```\n\n### ③ 副作用 Hook (Effect Hook)\n\n职责：管理单一副作用 (事件监听、定时器、性能埋点)。\n\n```\nMUST:  只有 1 个 useEffect\nMUST:  useRef 保存最新回调 (防止闭包过期)\nMUST:  cleanup 函数清理所有副作用\nMUST:  返回类型为 void (不返回状态)\n```\n\n### 组合\n\n```typescript\n// pages/chat/hooks/useChatPageData.ts — 数据 hook (单一 effect)\n// pages/chat/hooks/useChatPolling.ts — 副作用 hook (单一 effect)\n// 在 Screen 层组合:\nconst pageData = useChatPageData(chatId);\nuseChatPolling(pageData.silentRefresh, pollingInterval);\n```\n\n详见 [STANDARDS.md](STANDARDS.md#hook-architecture) 和 [PATTERNS.md](PATTERNS.md)\n\n## Type Safety\n\n```\nMUST:  所有函数参数 + 返回值显式标注类型\nMUST:  组件返回类型标注 ReactNode\nMUST:  Hook 返回类型定义为 interface (不用内联对象类型)\nMUST:  Context 用判别联合 (discriminated union) 区分场景\nMUST:  error 使用 enum PageErrorType，不用 string\nMUST:  API 响应用 type guard 验证，不用 as T\nMUST:  不等待的 Promise 用 void 标记: void doSomething()\nNEVER: any — 用 unknown + type guard\nNEVER: as T 类型断言\nNEVER: ! 非空断言\n```\n\n### API/IDL 接口类型（蛇形命名）\n\n凡用于描述**接口契约**的类型（HTTP 请求体、响应体、SSE 事件 payload 等），其**字段名必须使用 snake_case**，与后端、第三方 API 的 JSON 契约保持一致，便于跨语言/跨端对齐。\n\n```\nMUST:  请求体/响应体/SSE 事件等 IDL 类型的属性名使用 snake_case (如 conversation_id, header_title)\nMUST:  前端读取 API 响应、组装请求体、解析 SSE 时使用与类型一致的 snake_case 键\nNEVER: 在接口契约类型中使用 camelCase 字段名\n```\n\n仅在前端或后端内部使用的类型（如组件 Props、Hook 返回类型、内部状态）仍按「代码」命名规范使用 camelCase。\n\n### 判别联合 Context 示例\n\n```typescript\ninterface ChatDirectContext {\n  scene: ''direct'';\n  peerId: string;\n  getLogParams: () => DirectLogParams;\n}\n\ninterface ChatGroupContext {\n  scene: ''group'';\n  groupId: string;\n  memberCount: number;\n  getLogParams: () => GroupLogParams;\n}\n\ntype ChatPageContext = ChatDirectContext | ChatGroupContext;\n```\n\n## Error Handling\n\n```\nMUST:  纯函数映射错误: getPageErrorType(response) => PageErrorType | undefined\nMUST:  PageErrorType 使用 enum (DEFAULT, NETWORK, AUTH, EMPTY)\nMUST:  数据 Hook 中调用 getPageErrorType 设置错误状态\nMUST:  所有 async 必须 try/catch 或 .catch()\nMUST:  不等待的 async 调用加 void 前缀: void fetchData()\nNEVER: catch(e) {} 空 catch\nNEVER: silentLoad 无 catch — 静默操作也要 console.error\n```\n\n### 标准错误流\n\n```\nAPI 响应 → getPageErrorType(resp) → PageErrorType | undefined\n                                        ↓\n                              undefined = 成功，继续处理\n                              PageErrorType = 设置错误状态\n                                        ↓\n                              Screen: <PageStatusView errorType={errorType} onRetry={handleRetry} />\n```\n\n## Style System: Tamagui-First\n\n### 核心规则\n\n```\nMUST:  使用 Tamagui 组件 (XStack, YStack, View, Text) 替代 RN 原生组件\nMUST:  布局用 Tamagui props (bg, px, py, gap, flex, borderRadius, mt, mb, pl 等)\nMUST:  颜色只用 theme tokens ($color, $blue9, $gray4, $background)\nMUST:  间距只用 size tokens ($1, $2, $3, $4)\nMUST:  交互用 Tamagui 的 pressStyle + onPress，不用 RN Pressable/TouchableOpacity\nMUST:  非 Tamagui 组件 (如 Ionicons) 的颜色用 useTheme() + theme.xxx.val\nNEVER: 从 ''react-native'' 导入 View / Text — 从 ''tamagui'' 导入\nNEVER: useMemo 构造 style 对象 — 把样式直接写成 Tamagui props\nNEVER: className / Tailwind\nNEVER: 硬编码颜色 (#ffffff, rgba(...))\nALLOW: style prop — 仅 Tamagui 不支持的属性 (borderRadius 部分值、alignItems 等)\n```\n\n### 正确 vs 错误示例\n\n```typescript\n// BAD: RN 组件 + useMemo style 对象\nimport { View, Text, Pressable } from ''react-native'';\nconst styles = useMemo(() => ({\n  container: { padding: 12, backgroundColor: theme.blue2.val, borderRadius: 12 },\n  title: { fontSize: 14, fontWeight: ''600'', color: theme.blue11.val },\n}), [themeName]);\nreturn (\n  <Pressable onPress={handlePress}>\n    <View style={styles.container}>\n      <Text style={styles.title}>标题</Text>\n    </View>\n  </Pressable>\n);\n\n// GOOD: Tamagui 组件 + inline props\nimport { YStack, Text } from ''tamagui'';\nreturn (\n  <YStack\n    bg=\"$blue2\"\n    px=\"$3\"\n    py=\"$2.5\"\n    borderWidth={1}\n    borderColor=\"$blue7\"\n    pressStyle={{ opacity: 0.8 }}\n    onPress={handlePress}\n    style={{ borderRadius: 12 }}\n  >\n    <Text fontSize={14} fontWeight=\"600\" color=\"$blue11\">标题</Text>\n  </YStack>\n);\n```\n\n## Naming Conventions\n\n### 文件\n\n```\n组件:     kebab-case.tsx     (chat-bubble.tsx, page-loading.tsx)\nHook:     camelCase.ts       (useFetchData.ts, usePolling.ts)\nService:  camelCase.ts       (chatService.ts, profileService.ts)\nType:     index.ts (在 types/ 目录下)\n常量:     index.ts (在 consts/ 目录下)\n工具函数: kebab-case.ts      (calc-column-widths.ts, sanitize-streaming-markdown.ts)\n目录:     kebab-case/        (page-status-view/, operation-button/)\nBarrel:   common/hooks/index.ts 和 pages/{page}/utils/index.ts 需要 barrel re-export\n```\n\n### 代码\n\n```\n组件名:      PascalCase + 页面前缀    ChatBubble, ChatInput, ProfileCard\nHook:        use 前缀                useFetchData, usePolling, useAuth\n常量:        UPPER_SNAKE_CASE        TAB_BAR_HEIGHT, POLLING_INTERVAL\nEnum:        PascalCase              PageErrorType, ChatScene\n函数:        camelCase + 动词        fetchChatList, getPageErrorType, handleRetry\n布尔:        is/has/should 前缀      isLoading, hasMedia, shouldRefresh\n回调 Props:  on 前缀                 onPress, onRetry, onBind\n处理函数:    handle 前缀             handleBind, handleRetry\n返回类型:    显式标注                (): ReactNode, (): void, (): Promise<void>\n```\n\n## Import Organization\n\n```typescript\n// 1. React / React Native 核心\nimport { useState, useCallback } from ''react'';\nimport { Alert } from ''react-native'';\n\n// 2. 第三方框架\nimport { useRouter } from ''expo-router'';\nimport { YStack, Text } from ''tamagui'';\n\n// 3. 项目 common/ (shared)\nimport type { ProfilePageData } from ''@/common/typings/profile'';\nimport { useAuth } from ''@/common/hooks'';\nimport PageLoading from ''@/common/components/page-loading'';\nimport { getPageErrorType } from ''@/common/components/page-status-view'';\n\n// 4. 项目 services/ (数据获取)\nimport { fetchProfilePage } from ''@/services/profile'';\n\n// 5. 页面相对路径 (同页面内)\nimport { POLLING_INTERVAL } from ''../consts'';\nimport type { ChatLogParams } from ''../types'';\nimport ChatBubble from ''./chat-bubble'';\n```\n\n```\nMUST:  type-only imports 使用 import type { X }\nMUST:  组间保留空行\nMUST:  同组内按字母排序\nMUST:  common/hooks 用 barrel import: from ''@/common/hooks''\n```\n\n## 认证 (Better Auth)\n\nPiko 统一使用 **Better Auth** 做登录与鉴权。\n\n```\nMUST:  登录、session、OAuth（如 Apple 登录）使用 frontend/lib/auth-client.ts 的 createAuthClient 实例\nMUST:  需要带登录态请求时，用 authClient.getSession() / getCookie() 等注入；若在 fetch 里手动设置 Cookie，使用 credentials: ''omit''（与 Better Auth 文档一致）\nMUST:  鉴权/登录相关逻辑以 Better Auth 文档与项目 PRD（如 docs/PRD-Apple-Login-Better-Auth-Alignment.md）为准\nNEVER: 引入或教学其他认证库（如 Next-Auth）替代 Better Auth\n```\n\n## 依赖管理 (Dependency Management)\n\n```\nNEVER: 通过直接编辑 package.json 添加或删除依赖\nMUST:  使用包管理器官方命令添加/删除依赖（与本项目一致）\n       例如: pnpm add <pkg> / pnpm add -D <pkg>、pnpm remove <pkg>\n       或: npm install <pkg>、yarn add <pkg>（以项目根目录 package.json 或文档为准）\nMUST:  添加依赖前确认当前项目使用的包管理器（看 lockfile: pnpm-lock.yaml / package-lock.json / yarn.lock）\n```\n\n无论何时需要新增或移除依赖，都必须通过终端执行官方命令，不得手改 `package.json`。\n\n## Enforcement\n\n写代码时自动检查:\n\n1. 页面私有代码是否放在 pages/{page}/ 下？\n2. 组件是否超过 150 行？→ 拆分,依据具体情况拆分，如果真的要这么多，那就不拆了\n3. Hook 是否属于明确的分类 (数据/派生/副作用)？\n4. Hook 是否有多个 useEffect？→ 拆分\n5. 返回类型是否显式标注？→ 补充 ReactNode / void\n6. 是否有 any/as/! ？→ type guard\n7. error 是否用 enum？→ 不用 string\n8. 不等待的 Promise 是否加了 void？\n9. 样式是否用 Tamagui token？→ 不用 className/硬编码\n10. import 是否按规范分组？\n11. 新增/删除依赖是否通过包管理器命令？→ 禁止直接编辑 package.json\n12. 登录/鉴权相关是否使用 Better Auth（auth-client、credentials: ''omit'' 当手动设 Cookie）？→ 见「认证 (Better Auth)」节\n\n## References\n\n- [STANDARDS.md](STANDARDS.md) — 详细编码标准 + 完整代码实现\n- [PATTERNS.md](PATTERNS.md) — 正确模式 vs 反模式对照\n- [REVIEW-CHECKLIST.md](REVIEW-CHECKLIST.md) — PR 审查清单\n"},"lastSynced":"2026-03-04T14:59:54.275Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing strict code standards and autonomous page components.","zh":"非常适合需要严格代码标准和自治页面组件的前端代理。","ja":"厳格なコード規範と自治ページコンポーネントを必要とするフロントエンドエージェントに最適。","ko":"엄격한 코드 표준과 자율적인 페이지 컴포넌트가 필요한 프론트엔드 에이전트에게 완벽합니다.","es":"Perfecto para Agentes Frontend que necesitan estrictos estándares de código y componentes de página autónomos.","fr":"Parfait pour les agents Frontend nécessitant des normes de code strictes et des composants de page autonomes.","de":"Perfekt für Frontend-Agents, die strenge Codestandards und autonome Seitenelemente benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de padrões de código estritos e componentes de página autônomos.","ru":"Идеально для агентов Frontend, требующих строгих стандартов кода и автономных компонентов страниц.","ar":"مثالي لعميل الواجهة الأمامية الذي يحتاج إلى معايير صارمة للكود ومكونات صفحة مستقلة."},"recommendation":{"en":"Empowers agents to enforce code as documentation principles, utilizing type systems as contracts and promoting composition over complexity, all while ensuring explicit return types and promise handling through await or void, leveraging Telegram and OpenClaw interactions.","zh":"赋予代理执行代码即文档原则的能力，利用类型系统作为契约，提倡组合而非复杂性，同时确保显式返回类型和通过await或void处理promise，利用Telegram和OpenClaw交互。","ja":"エージェントにコード即文書の原則を実施する能力を与え、タイプシステムを契約として利用し、複雑さよりも組み合わせを提唱し、同時に明示的な戻り値の型とawaitまたはvoidによるPromiseの処理を保証し、TelegramおよびOpenClawの相互作用を利用する。","ko":"에이전트가 코드를 문서로서의 원칙을 시행할 수 있도록하며, 유형 시스템을 계약으로 사용하고, 복잡성보다는 구성과 명시적 반환 유형 및 await 또는 void를 통한 프로미스 처리를 보장하며, Telegram 및 OpenClaw 상호 작용을 활용합니다.","es":"Habilita a los agentes a aplicar los principios de código como documentación, utilizando sistemas de tipos como contratos y promoviendo la composición sobre la complejidad, asegurando al mismo tiempo tipos de retorno explícitos y manejo de promesas a través de await o void, aprovechando las interacciones de Telegram y OpenClaw.","fr":"Permet aux agents d''appliquer les principes de code comme documentation, en utilisant les systèmes de types comme contrats et en promouvant la composition plutôt que la complexité, en garantissant en même temps des types de retour explicites et une gestion de promesses via await ou void, en exploitant les interactions de Telegram et OpenClaw.","de":"Ermächtigt die Agenten, die Prinzipien von Code als Dokumentation anzuwenden, indem sie Typsysteme als Verträge verwenden und die Zusammensetzung über die Komplexität fördern, während sie gleichzeitig explizite Rückgabetypen und Promessenverwaltung durch await oder void sicherstellen, indem sie die Interaktionen von Telegram und OpenClaw nutzen.","pt":"Habilita os agentes a impor o código como princípios de documentação, utilizando sistemas de tipo como contratos e promovendo a composição sobre a complexidade, garantindo tipos de retorno explícitos e tratamento de promessas por meio de await ou void, aproveitando interações do Telegram e OpenClaw.","ru":"Наделяет агентов возможностью обеспечивать соблюдение кода как принципов документации, используя системы типов как контракты и продвигая композицию над сложностью, обеспечивая явные типы возвращаемых значений и обработку обещаний через await или void, используя взаимодействия Telegram и OpenClaw.","ar":"يمنح الوكلاء القدرة على فرض الشفرة كمبادئ توثيق ، باستخدام أنظمة النوع كعقود وتعزيز التكوين على التعقيد ، مع ضمان أنواع الإرجاع الصريحة ومعالجة الوعد من خلال الإنتظار أو الفارغ ، واستغلال التفاعلات بين Telegram و OpenClaw."},"useCases":{"en":["Enforcing code standards for autonomous page components","Automating collection of payment information and accounting data","Generating interactive bots for Telegram using OpenClaw","Implementing single responsibility principles in functions and components"],"zh":["执行自治页面组件的代码标准","自动收集支付信息和会计数据","使用OpenClaw生成Telegram的交互式机器人","在函数和组件中实施单一责任原则"],"ja":["自治ページコンポーネントのコード規範の適用","支払い情報および会計データの自動収集","OpenClawを使用したTelegramのインタラクティブボットの生成","関数およびコンポーネントにおける単一責任の原則の実施"],"ko":["자율적인 페이지 컴포넌트에 대한 코드 표준 강제","결제 정보 및 회계 데이터의 자동 수집","OpenClaw를 사용하여 Telegram의 대화형 봇 생성","함수 및 컴포넌트에서 단일 책임 원칙 구현"],"es":["Aplicar estándares de código para componentes de página autónomos","Automatizar la recopilación de información de pago y datos contables","Generar bots interactivos para Telegram utilizando OpenClaw","Implementar principios de responsabilidad única en funciones y componentes"],"fr":["Appliquer des normes de code pour les composants de page autonomes","Automatiser la collecte d''informations de paiement et de données comptables","Générer des bots interactifs pour Telegram en utilisant OpenClaw","Implémenter des principes de responsabilité unique dans les fonctions et les composants"],"de":["Codestandards für autonome Seitenelemente durchsetzen","Automatisieren der Erfassung von Zahlungsinformationen und Buchhaltungsdaten","Erstellen interaktiver Bots für Telegram mit OpenClaw","Implementieren von Prinzipien der eindeutigen Verantwortung in Funktionen und Komponenten"],"pt":["Impor padrões de código para componentes de página autônomos","Automatizar a coleta de informações de pagamento e dados contábeis","Gerar bots interativos para o Telegram usando o OpenClaw","Implementar princípios de responsabilidade única em funções e componentes"],"ru":["Обеспечить соблюдение стандартов кода для автономных компонентов страниц","Автоматизировать сбор информации о платежах и бухгалтерских данных","Генерировать интерактивных ботов для Telegram с помощью OpenClaw","Реализовывать принципы единой ответственности в функциях и компонентах"],"ar":["فرض معايير الشفرة على مكونات الصفحة المستقلة","توفير جمع المعلومات الخاصة بالدفع والبيانات المحاسبية","إنتاج بوتات تفاعلية لبرنامج Telegram باستخدام OpenClaw","تنفيذ مبادئ المسؤولية الواحدة في الوظائف والمكونات"]},"limitations":{"en":["Requires adherence to strict coding standards","Telegram and OpenClaw integration necessary for full functionality","Explicit type annotations and promise handling required"],"zh":["需要遵守严格的编码标准","需要Telegram和OpenClaw集成以实现全部功能","需要显式类型注释和Promise处理"],"ja":["厳格なコード規範への従順が必要","完全な機能を実現するためにTelegramおよびOpenClawの統合が必要","明示的な型注釈およびPromise処理が必要"],"ko":["엄격한 코딩 표준을 따르는 것이 필요","전체 기능을 구현하기 위해 Telegram 및 OpenClaw 통합이 필요","명시적 유형 주석 및 프로미스 처리가 필요"],"es":["Requiere adherencia a estrictos estándares de codificación","La integración de Telegram y OpenClaw es necesaria para la funcionalidad completa","Se requieren anotaciones de tipo explícitas y manejo de promesas"],"fr":["Nécessite l''adérence à des normes de codage strictes","L''intégration de Telegram et OpenClaw est nécessaire pour une fonctionnalité complète","Des annotations de type explicites et une gestion de promesses sont requises"],"de":["Erfordert die Einhaltung strenger Codierstandards","Die Integration von Telegram und OpenClaw ist für die volle Funktionalität erforderlich","Explizite Typenannotationen und Promessenverwaltung sind erforderlich"],"pt":["Exige adesão a padrões de codificação estritos","Integração do Telegram e OpenClaw necessária para funcionalidade completa","Anotações de tipo explícitas e tratamento de promessas são necessários"],"ru":["Требует соблюдения строгих стандартов кодирования","Интеграция с Telegram и OpenClaw необходима для полной функциональности","Явные аннотации типов и обработка обещаний обязательны"],"ar":["يتطلب الالتزام بمعايير الترميز الصارمة","التكامل مع Telegram و OpenClaw ضروري للوظائف الكاملة","التعليقات التوضيحية للنوع الصريح ومعالجة الوعد مطلوبة"]},"version":3},"contentHash":"d14dd2a1b3e189914858737a4c1470c306217631be2314906fdec15977baab18","qualityScore":49}');
