INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cjjohansen/drone-web/event-storming', 'event-storming', 'cjjohansen', 'drone-web', 'community', 'event-storming cjjohansen drone-web community Event Storming是用于创建无人机电子商务网站的ADDR设计过程的一部分，帮助开发者设计和优化系统 イベントストーミングは、ドローンECサイトを作成するADDR設計プロセスの1つであり、開発者がシステムを設計および最適化するのに役立ちます 이벤트 스토밍은 드론 전자상거래 사이트를 생성하는 ADDR 디자인 프로세스의 일부로 개발자가 시스템을 설계 및 최적화하는 데 도움이 됩니다 Event-storming es una técnica para diseñar sitios web de ecommerce de drones utilizando el proceso ADDR Design L''event-storming est une technique pour concevoir des sites ecommerce de drones en utilisant le processus de conception ADDR Event-Storming ist eine Technik, um Drohnen-Ecommerce-Websites mithilfe des ADDR-Design-Prozesses zu entwerfen Desenvolva um site de ecommerce de drones com o processo de design ADDR e tecnologias de inteligência artificial Разработайте сайт электронной коммерции для дронов с помощью процесса дизайна ADDR и технологий ИИ قم ببناء موقع إلكتروني للتجارة الإلكترونية للطائرات بدون طيار باستخدام عملية التصميم ADDR وتكنولوجيا الذكاء الاصطناعي drone ecommerce website using ADDR Design process 如何使用Event Storming 什么是ADDR设计过程 Event Storming替代方案 Event Storming vs 设计模式 Event Storming安装 Event Storming设置指南 无人机电子商务网站开发 drone ecommerce website using ADDR Design process');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('karanchawla/vvm/vvm', 'community', 'karanchawla', 'vvm', 'karanchawla/vvm', 'vvm', 0, 0, 49, '2026-03-04T13:07:01.947Z', '2026-03-04T15:11:14.890Z', '545df9404a3f930fd2f2422674fc2db4c8fc5e2f70d0b7f200f5cfd47f335e0b', '{"id":"karanchawla/vvm/vvm","name":"vvm","description":{"zh":"Vibe虚拟机（vvm）是一种AI智能开发工具，用于构建和部署AI模型。","ja":"Vibe Virtual Machine（vvm）は、AIエージェント開発ツールです。","ko":"Vibe 가상머신(vvm)은 AI 에이전트 개발을 위한 도구입니다.","es":"La Máquina Virtual Vibe es una plataforma de código abierto que permite a los desarrolladores crear y ejecutar Agentes de IA de manera eficiente","fr":"La Machine Virtuelle Vibe est une plate-forme open source qui permet aux développeurs de créer et d''exécuter des Agents IA de manière efficace","de":"Die Vibe Virtual Machine ist eine Open-Source-Plattform, die es Entwicklern ermöglicht, AI-Agents effizient zu erstellen und auszuführen","pt":"A VVM é uma máquina virtual de vibração que permite aos desenvolvedores criar aplicações eficientes. Ela fornece uma plataforma para executar código de forma rápida e segura.","ru":"VVM - это виртуальная машина вибрации, которая позволяет разработчикам создавать эффективные приложения. Она предоставляет платформу для запуска кода в быстром и безопасном режиме.","ar":"VVM هي آلة افتراضية للاهتزاز تسمح للمطورين بإنشاء تطبيقات فعالة. توفر منصة لتشغيل الكود بسرعة وأمان.","en":"vibe virtual machine"},"seo":{"title":{"zh":"Vibe 虚拟机（vvm）- AI智能开发工具","ja":"Vibe Virtual Machine（vvm）- AIエージェントのための開発ツール","ko":"Vibe 가상머신(vvm) - AI 에이전트 개발 도구","es":"Máquina Virtual Vibe: Herramientas de Agentes de IA","fr":"Machine Virtuelle Vibe: Outils d''Agents IA","de":"Vibe Virtual Machine: AI Agent Tools","pt":"Ferramentas de IA: VVM - Máquina Virtual Vibe","ru":"ИИ Агенты: VVM - Виртуальная Машина Vibe","ar":"أدوات الذكاء الاصطناعي: VVM - آلة افتراضية للاهتزاز","en":"vvm"},"description":{"zh":"Vibe虚拟机（vvm）是一种AI智能开发工具，用于构建和部署AI模型。","ja":"Vibe Virtual Machine（vvm）は、AIエージェント開発ツールです。","ko":"Vibe 가상머신(vvm)은 AI 에이전트 개발을 위한 도구입니다.","es":"La Máquina Virtual Vibe es una plataforma de código abierto que permite a los desarrolladores crear y ejecutar Agentes de IA de manera eficiente","fr":"La Machine Virtuelle Vibe est une plate-forme open source qui permet aux développeurs de créer et d''exécuter des Agents IA de manière efficace","de":"Die Vibe Virtual Machine ist eine Open-Source-Plattform, die es Entwicklern ermöglicht, AI-Agents effizient zu erstellen und auszuführen","pt":"A VVM é uma máquina virtual de vibração que permite aos desenvolvedores criar aplicações eficientes. Ela fornece uma plataforma para executar código de forma...","ru":"VVM - это виртуальная машина вибрации, которая позволяет разработчикам создавать эффективные приложения. Она предоставляет платформу для запуска кода в быстр...","ar":"VVM هي آلة افتراضية للاهتزاز تسمح للمطورين بإنشاء تطبيقات فعالة. توفر منصة لتشغيل الكود بسرعة وأمان.","en":"vibe virtual machine"},"definition":{"en":"vibe virtual machine"},"features":{"zh":["支持多种AI框架","高性能计算能力","易于使用的开发接口","支持分布式部署","实时监控和调试"],"ja":["複数のAIフレームワークをサポート","高性能コンピューティング能力","使いやすい開発インターフェース","分散デプロイをサポート","リアルタイムモニタリングとデバッグ"],"ko":["여러 가지 AI 프레임워크 지원","고성능 컴퓨팅 능력","사용하기 쉬운 개발 인터페이스","분산 배포 지원","실시간 모니터링 및 디버깅"],"es":["Ejecución eficiente de Agentes de IA","Compatibilidad con múltiples plataformas","Soporte para lenguajes de programación como Python y Node.js","Interfaz de línea de comandos (CLI) para una fácil configuración","Integración con herramientas de desarrollo populares como React"],"fr":["Exécution efficace des Agents IA","Compatibilité avec plusieurs plateformes","Prise en charge de langages de programmation tels que Python et Node.js","Interface de ligne de commande (CLI) pour une configuration facile","Intégration avec des outils de développement populaires comme React"],"de":["Effiziente Ausführung von AI-Agents","Kompatibilität mit mehreren Plattformen","Unterstützung für Programmiersprachen wie Python und Node.js","Kommandozeilen-Schnittstelle (CLI) für eine einfache Konfiguration","Integration mit beliebten Entwicklungstools wie React"],"pt":["Execução de código rápido e eficiente","Plataforma segura para desenvolvedores","Compatibilidade com linguagens de programação populares","Fácil integração com outras ferramentas de desenvolvimento","Otimização de desempenho para aplicações críticas"],"ru":["Быстрое и эффективное выполнение кода","Безопасная платформа для разработчиков","Совместимость с популярными языками программирования","Легкая интеграция с другими инструментами разработки","Оптимизация производительности для критических приложений"],"ar":["تنفيذ الكود السريع والفعال","منصة آمنة للمطورين","توافق مع لغات البرمجة الشائعة","تكامل سهل مع أدوات التطوير الأخرى","تحسين الأداء لتطبيقات حرجة"]},"keywords":{"zh":["vvm是什么","Vibe虚拟机教程","AI开发工具","vvm安装","vvm设置指南","vvm替代品","vvm vs 其他AI工具"],"ja":["vvmとは","Vibe Virtual Machineの使い方","AIエージェント開発ツール","vvmインストール","vvm設定ガイド","vvmの代替","vvm vs 他のAIツール"],"ko":["vvm이란","Vibe 가상머신 사용법","AI 에이전트 개발 도구","vvm 설치","vvm 설정 가이드","vvm 대안","vvm vs 다른 AI 도구"],"es":["cómo usar la Máquina Virtual Vibe","qué es un Agente de IA","alternativas a la Máquina Virtual Vibe","Máquina Virtual Vibe vs otros Agentes de IA","instalación de la Máquina Virtual Vibe","guía de configuración de la Máquina Virtual Vibe"],"fr":["comment utiliser la Machine Virtuelle Vibe","qu''est-ce qu''un Agent IA","alternatives à la Machine Virtuelle Vibe","Machine Virtuelle Vibe vs autres Agents IA","installation de la Machine Virtuelle Vibe","guide de configuration de la Machine Virtuelle Vibe"],"de":["wie man die Vibe Virtual Machine verwendet","was ist ein AI-Agent","Alternativen zur Vibe Virtual Machine","Vibe Virtual Machine vs andere AI-Agents","Installation der Vibe Virtual Machine","Konfigurationsanleitung für die Vibe Virtual Machine"],"pt":["como usar VVM","o que é VVM","VVM vs máquinas virtuais","instalar VVM","guia de configuração VVM","desenvolvimento de aplicações com VVM","otimização de desempenho com VVM","segurança em VVM"],"ru":["как использовать VVM","что такое VVM","VVM vs виртуальные машины","установить VVM","руководство по настройке VVM","разработка приложений с VVM","оптимизация производительности с VVM","безопасность в VVM"],"ar":["كيفية استخدام VVM","ما هي VVM","VVM مقابل الآلات الافتراضية","تثبيت VVM","دليل إعداد VVM","تطوير التطبيقات مع VVM","تحسين الأداء مع VVM","أمان في VVM"]}},"owner":"karanchawla","repo":"vvm","repoPath":"karanchawla/vvm","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.947Z","topics":[],"category":"community","skillMd":{"name":"vvm","description":"|","bodyPreview":"# VVM Skill\n\nVVM (Vibe Virtual Machine) is a language for writing agentic programs where the LLM acts as the runtime.\n\n---\n\n## When to Activate\n\nActivate this skill when:\n\n1. User runs `/vvm-boot`, `/vvm-compile`, `/vvm-run`, or `/vvm-generate`\n2. User opens or references a `.vvm` file\n3. User asks about VVM syntax, semantics, or patterns\n4. User wants to create an AI-powered workflow\n\n---\n\n## Documentation Files\n\n| File              | Role                      | When to Read","body":"# VVM Skill\n\nVVM (Vibe Virtual Machine) is a language for writing agentic programs where the LLM acts as the runtime.\n\n---\n\n## When to Activate\n\nActivate this skill when:\n\n1. User runs `/vvm-boot`, `/vvm-compile`, `/vvm-run`, or `/vvm-generate`\n2. User opens or references a `.vvm` file\n3. User asks about VVM syntax, semantics, or patterns\n4. User wants to create an AI-powered workflow\n\n---\n\n## Documentation Files\n\n| File              | Role                      | When to Read                    |\n| ----------------- | ------------------------- | ------------------------------- |\n| `SKILL.md`        | Quick reference, triggers | Always first                    |\n| `vvm.md`          | Execution semantics       | When running programs           |\n| `spec.md`         | Language specification    | For syntax/validation questions |\n| `memory-spec.md`  | Agent memory (portable)   | When using persistent agents    |\n| `patterns.md`     | Design patterns           | When writing programs           |\n| `antipatterns.md` | Anti-patterns             | When reviewing programs         |\n\n---\n\n## Quick Reference\n\n### Agent Definition\n\n```vvm\nagent researcher(\n  model=\"sonnet\",\n  prompt=\"thorough, cite sources\",\n  skills=[\"web-search\"],\n  permissions=perm(network=\"allow\", bash=\"deny\"),\n)\n```\n\n### Agent Call\n\n```vvm\nresult = @researcher `Find papers on {topic}.`(topic)\nresult = @researcher `Summarize.`(topic, retry=3, timeout=\"30s\")\n```\n\n### Agent Memory\n\n```vvm\nagent assistant(model=\"sonnet\", prompt=\"Helpful.\", memory={ scope: \"project\", key: \"user:alice\" })\nreply = @assistant `Continue.`(request)  # default: memory_mode=\"continue\"\ndry = @assistant `Read-only run.`(request, memory_mode=\"dry_run\")\nfresh = @assistant `Stateless run.`(request, memory_mode=\"fresh\")\n```\n\n### Semantic Predicate\n\n```vvm\nready = ?`production ready`(code)\n\nif ?`needs more work`(draft):\n  draft = @writer `Improve.`(draft)\n```\n\n### Pattern Matching\n\n```vvm\nmatch result:\n  case ?`high quality`:\n    publish(result)\n  case error(kind=\"timeout\"):\n    result = @backup `Retry.`(request)\n  case error(_):\n    log_error(result)\n  case _:\n    pass\n```\n\n### Choice\n\n```vvm\nchoose analysis by ?`best approach` as choice:\n  option \"quick\":\n    plan = @planner `Minimal plan.`()\n  option \"thorough\":\n    plan = @planner `Full plan.`()\n```\n\n### Control Flow\n\n```vvm\n# If/elif/else\nif condition:\n  do_something()\nelif other:\n  do_other()\nelse:\n  do_default()\n\n# While loop\nwhile not ?`done`(result):\n  result = @worker `Improve.`(result)\n\n# For loop\nfor item in items:\n  process(item)\n```\n\n### Context Passing\n\n```vvm\n# Implicit input (it)\nwith input data:\n  result = @agent `Process.`()  # uses it == data\n\n# Explicit input\nresult = @agent `Process.`(data)\n```\n\n### Functions\n\n```vvm\ndef analyze(topic):\n  research = @researcher `Find info on {topic}.`(topic)\n  return @analyst `Analyze.`(research)\n\nresult = analyze(\"AI safety\")\n```\n\n### Error Handling\n\n```vvm\n# Error values (match)\nmatch result:\n  case error(_):\n    handle_error(result)\n\n# Raised errors (try/except)\ntry:\n  if ?`invalid`(input):\n    raise \"Invalid input\"\nexcept as err:\n  log(err)\nfinally:\n  cleanup()\n```\n\n### Constraints\n\n```vvm\ndraft = @writer `Write report.`(data)\n\nconstrain draft(attempts=3):\n  require ?`has citations`\n  require ?`no hallucinations`\n```\n\n### Imports/Exports\n\n```vvm\n# Skill imports\nimport \"web-search\" from \"github:anthropic/skills\"\n\n# Module value imports (agents are local)\nfrom \"./lib/research.vvm\" import report\n\n# Callable module import\nfrom \"./lib/research.vvm\" import * as research\nresult = research(topic=\"AI\", depth=\"deep\")\nreport = result.report\n\n# Exports (values only)\nexport result\nexport summary\n```\n\n### Standard Library\n\n```vvm\n# Parallel map\nresults = pmap(items, process)\n\n# Sequential map/filter/reduce\nmapped = map(items, transform)\nfiltered = filter(items, predicate)\ndef add(a, b):\n  return a + b\ntotal = reduce(items, add, init=0)\n\n# Iterative refinement\nfinal = refine(initial, max=5, done=is_ready, step=improve)\n\n# Named fan-in\nctx = pack(research, analysis, topic=topic)\n\n# Range\nfor i in range(10):\n  process(i)\n```\n\n---\n\n## Examples\n\n| #   | Name                   | Concepts                |\n| --- | ---------------------- | ----------------------- |\n| 01  | hello-world            | Minimal program         |\n| 02  | simple-agent-call      | Agent with input        |\n| 03  | semantic-predicate     | `?` predicates          |\n| 04  | match-statement        | Pattern matching        |\n| 05  | if-elif-else           | Conditionals            |\n| 06  | while-loop             | While loops             |\n| 07  | for-loop               | For loops               |\n| 08  | with-input             | Context passing         |\n| 09  | agent-options          | retry, timeout, backoff |\n| 10  | code-council           | .with() derived agents  |\n| 11  | parallel-pmap          | Parallel execution      |\n| 12  | functions              | def and return          |\n| 13  | skill-imports          | Skill imports           |\n| 14  | module-imports         | Module imports          |\n| 15  | error-values           | Error value matching    |\n| 16  | try-except-finally     | Raised errors           |\n| 17  | choose-statement       | AI-selected branching   |\n| 18  | constrain-require      | Quality constraints     |\n| 19  | refine-loop            | Iterative improvement   |\n| 20  | collection-helpers     | map, filter, reduce     |\n| 21  | devils-advocate        | Adversarial debate      |\n| 22  | full-research-pipeline | Complex workflow        |\n| 23  | ralph-wiggum-loop      | Continuous improvement  |\n| 24  | agent-memory-basic     | Memory binding + digest/ledger |\n| 25  | agent-memory-modes     | memory_mode: continue/dry_run/fresh |\n| 26  | agent-memory-multi-tenant | Per-key isolation |\n| 27  | agent-memory-parallel-safe | pmap-safe persistence |\n| 28  | ref-composition        | Ref composition patterns |\n| 29  | ref-loop-accumulation  | Accumulating refs in loops |\n| 30  | materializer-pattern   | Materializing refs |\n| 31  | run-inspector          | Inspecting run state |\n| 32  | ouroboros              | Self-modifying workflow |\n| 33  | wisdom-of-crowds       | Ensemble voting |\n| 34  | hydra                  | Multi-headed agents |\n| 35  | forge                  | Agent factory |\n| 36  | inputs                 | Input declarations |\n| 37  | debate                 | Module composition |\n\n---\n\n## Commands\n\n### /vvm-boot\n\nInitialize VVM for new or returning users. Detects existing files and provides onboarding.\n\n### /vvm-compile <file.vvm>\n\nValidate a VVM program without executing. Reports errors and warnings with line numbers.\n\n### /vvm-run <file.vvm>\n\nExecute a VVM program. You become the VVM runtime and execute statements sequentially, spawning subagents for agent calls.\n\n### /vvm-generate <description>\n\nGenerate a VVM program from a natural language description. Analyzes intent, maps to VVM constructs, applies best practices, and produces well-structured code. Asks clarifying questions if the request is ambiguous.\n\n---\n\n## Key Principles\n\n1. **Minimal syntax** - Familiar indentation-based blocks\n2. **Explicit AI boundary** - Agent calls are syntactically distinct (`@agent`)\n3. **Eager execution** - No lazy evaluation, sequential by default\n4. **Semantic control flow** - Branch on meaning, not just booleans\n5. **Two error channels** - Values (match) vs raised (try/except)\n6. **Explicit parallelism** - Only `pmap` runs concurrently\n"},"lastSynced":"2026-03-04T15:11:14.890Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced AI Agents needing to execute agentic programs with Vibe Virtual Machine runtime","zh":"非常适合需要利用 Vibe Virtual Machine 运行时执行 agentic 程序的高级 AI Agents。","ja":"Vibe Virtual Machine ランタイムを使用してエージェントプログラムを実行する必要がある高度な AI エージェントに最適です。","ko":"Vibe Virtual Machine 런타임으로 에이전트 프로그램을 실행해야 하는 고급 AI 에이전트에 이상적입니다.","es":"Ideal para Agentes de IA Avanzados que necesitan ejecutar programas de agente con tiempo de ejecución de máquina virtual Vibe","fr":"Idéal pour les agents IA avancés ayant besoin d''exécuter des programmes d''agent avec le runtime de la machine virtuelle Vibe","de":"Ideal für erweiterte KI-Agents, die agente-Programme mit der Laufzeitumgebung der Vibe Virtual Machine ausführen müssen","pt":"Ideal para Agentes de IA Avançados que precisam executar programas de agentes com o tempo de execução da Máquina Virtual Vibe","ru":"Идеально для продвинутых агентов ИИ, которым необходимо выполнять агентные программы с помощью среды выполнения виртуальной машины Vibe","ar":"مثالي للوكلاء الذكاء الاصطناعي المتقدم الذين يحتاجون إلى تشغيل برامج الوكيل مع وقت تشغيل آلة افتراضية فيIBE"},"recommendation":{"en":"Empowers agents to compile and run .vvm files, leveraging VVM syntax and semantics for AI-powered workflows, and utilizing protocols like `/vvm-boot`, `/vvm-compile`, `/vvm-run`, or `/vvm-generate`","zh":"赋能 agents 编译和运行 .vvm 文件，利用 VVM 语法和语义实现 AI 驱动的工作流，并使用诸如 `/vvm-boot`、`/vvm-compile`、`/vvm-run` 或 `/vvm-generate` 等协议。","ja":"エージェントが .vvm ファイルをコンパイルおよび実行できるようにし、AI 駆動のワークフローに VVM の構文とセマンティクスを活用し、`/vvm-boot`、`/vvm-compile`、`/vvm-run`、`/vvm-generate` などのプロトコルを利用します。","ko":"에이전트가 .vvm 파일을 컴파일하고 실행할 수 있도록 하여, AI 기반 워크플로우를 위해 VVM 구문 및 의미론을 활용하고, `/vvm-boot`, `/vvm-compile`, `/vvm-run` 또는 `/vvm-generate`와 같은 프로토콜을 사용합니다.","es":"Habilita a los agentes a compilar y ejecutar archivos .vvm, aprovechando la sintaxis y la semántica de VVM para flujos de trabajo impulsados por IA, y utilizando protocolos como `/vvm-boot`, `/vvm-compile`, `/vvm-run` o `/vvm-generate`","fr":"Permet aux agents de compiler et d''exécuter des fichiers .vvm, en exploitant la syntaxe et la sémantique de VVM pour des flux de travail alimentés par l''IA, et en utilisant des protocoles tels que `/vvm-boot`, `/vvm-compile`, `/vvm-run` ou `/vvm-generate`","de":"Ermöglicht es Agenten, .vvm-Dateien zu kompilieren und auszuführen, indem es die VVM-Syntax und -Semantik für von KI angetriebene Workflows nutzt und Protokolle wie `/vvm-boot`, `/vvm-compile`, `/vvm-run` oder `/vvm-generate` verwendet","pt":"Habilita agentes a compilar e executar arquivos .vvm, aproveitando a sintaxe e a semântica do VVM para fluxos de trabalho alimentados por IA, e utilizando protocolos como `/vvm-boot`, `/vvm-compile`, `/vvm-run`, ou `/vvm-generate`","ru":"Предоставляет агентам возможность компилировать и запускать файлы .vvm, используя синтаксис и семантику VVM для рабочих процессов на основе ИИ, и используя протоколы, такие как `/vvm-boot`, `/vvm-compile`, `/vvm-run`, или `/vvm-generate`","ar":"تمكين الوكلاء من компиляلة وتشغيل الملفات .vvm، واستخدام بناء الجملة والدلالات VVM للتدفقات العملية المدعومة بالذكاء الاصطناعي، واستخدام بروتوكولات مثل `/vvm-boot`، `/vvm-compile`، `/vvm-run`، أو `/vvm-generate`"},"useCases":{"en":["Compiling .vvm files for execution","Generating VVM code for custom workflows","Debugging VVM programs with runtime analysis"],"zh":["编译 .vvm 文件以供执行","为自定义工作流生成 VVM 代码","通过运行时分析调试 VVM 程序"],"ja":["実行のための .vvm ファイルのコンパイル","カスタムワークフローのための VVM コードの生成","ランタイム分析による VVM プログラムのデバッグ"],"ko":["실행을 위한 .vvm 파일 컴파일","사용자 정의 워크플로우를 위한 VVM 코드 생성","런타임 분석으로 VVM 프로그램 디버깅"],"es":["Compilación de archivos .vvm para ejecución","Generación de código VVM para flujos de trabajo personalizados","Depuración de programas VVM con análisis de tiempo de ejecución"],"fr":["Compilation de fichiers .vvm pour exécution","Génération de code VVM pour flux de travail personnalisés","Débogage de programmes VVM avec analyse de runtime"],"de":["Kompilierung von .vvm-Dateien für die Ausführung","Generierung von VVM-Code für benutzerdefinierte Workflows","Fehlersuche in VVM-Programmen mit Laufzeitanalyse"],"pt":["Compilando arquivos .vvm para execução","Gerando código VVM para fluxos de trabalho personalizados","Depurando programas VVM com análise de tempo de execução"],"ru":["Компиляция файлов .vvm для выполнения","Генерация кода VVM для пользовательских рабочих процессов","Отладка программ VVM с помощью анализа времени выполнения"],"ar":["تجميع ملفات .vvm للتشغيل","توليد رمز VVM لتدفقات العمل المخصصة","تصحيح أخطاء برامج VVM مع تحليل وقت التشغيل"]},"limitations":{"en":["Requires VVM-compatible runtime environment","Limited to .vvm file format"],"zh":["需要 VVM 兼容的运行时环境","仅限于 .vvm 文件格式"],"ja":["VVM 互換のランタイム環境が必要",".vvm ファイル形式に限定"],"ko":["VVM 호환 런타임 환경 필요",".vvm 파일 형식으로 제한됨"],"es":["Requiere un entorno de tiempo de ejecución compatible con VVM","Limitado al formato de archivo .vvm"],"fr":["Nécessite un environnement d''exécution compatible VVM","Limité au format de fichier .vvm"],"de":["Benötigt eine Laufzeitumgebung, die mit VVM kompatibel ist","Begrenzt auf das .vvm-Dateiformat"],"pt":["Requer ambiente de tempo de execução compatível com o VVM","Limitado ao formato de arquivo .vvm"],"ru":["Требует среды выполнения, совместимой с VVM","Ограничен форматом файла .vvm"],"ar":["يتطلب بيئة وقت تشغيل متوافقة مع VVM","محدود بتنسيق الملف .vvm"]},"version":3},"contentHash":"545df9404a3f930fd2f2422674fc2db4c8fc5e2f70d0b7f200f5cfd47f335e0b","qualityScore":49}');
