INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TechNickAI/openclaw-config/quo', 'quo', 'TechNickAI', 'openclaw-config', 'community', 'quo TechNickAI openclaw-config community Quo API 提供了业务电话系统的自动化和集成能力，支持电话号码、最近的对话等功能 Quo API はビジネス電話システムの自動化と統合能力を提供し、電話番号、最近の会話などをサポート Quo API는 비즈니스 전화 시스템의 자동화와 통합 능력을 제공하며, 전화 번호, 최근 대화 등 기능을 지원 Quo es una configuración de OpenClaw que permite a los desarrolladores acceder a llamadas, textos y contactos de su negocio Quo est une configuration OpenClaw qui permet aux développeurs d''accéder aux appels, textes et contacts de leur entreprise Quo ist eine OpenClaw-Konfiguration, die es Entwicklern ermöglicht, auf Anrufe, Texte und Kontakte ihres Unternehmens zuzugreifen O Quo é uma plataforma de telefonia empresarial que permite gerenciar chamadas, textos e contatos de forma eficiente. Configure o Quo com facilidade usando a API Quo - это платформа деловой телефонии, которая позволяет эффективно управлять звонками, текстами и контактами. Настройте Quo с помощью API Quo هو منصة هاتفية تجارية تتيح إدارة المكالمات والرسائل والاتصالات بفعالية. أعد إعداد Quo بسهولة باستخدام واجهة برمجة التطبيقات Shareable OpenClaw configuration: memory system, skills, and agent instructions Quo API 业务电话系统 自动化 集成 电话号码 最近的对话 会话记录 联系人列表 Shareable OpenClaw configuration: memory system, skills, and agent instructions');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SterlingChin/marvin-template/start', 'community', 'SterlingChin', 'marvin-template', 'SterlingChin/marvin-template', 'start', 0, 0, 48, '2026-03-04T13:07:01.669Z', '2026-03-04T13:22:23.081Z', 'c299ccc89aed3501d3e0595a80df49cffa82595f067d1e2fd676a2c875ca7e65', '{"id":"SterlingChin/marvin-template/start","name":"start","description":{"zh":"MARVIN启动技能可以帮助开发者启动会话、加载上下文和处理日常任务，提高开发效率","ja":"MARVINスタートスキルは、開発者がセッションを開始し、コンテキストを読み込み、日常タスクを効率的に処理できるようにします","ko":"MARVIN 시작 스킬은 개발자가 세션을 시작하고 컨텍스트를 로딩하며 일일 작업을 효율적으로 처리할 수 있도록 도와줍니다","es":"MARVIN es un asistente AI que carga el contexto completo y ofrece una breve descripción diaria para ayudar a los desarrolladores a gestionar su día","fr":"MARVIN est un assistant AI qui charge le contexte complet et offre une brève description quotidienne pour aider les développeurs à gérer leur journée","de":"MARVIN ist ein AI-Assistent, der den vollständigen Kontext lädt und eine tägliche Zusammenfassung bietet, um Entwicklern bei der Verwaltung ihres Tages zu helfen","pt":"MARVIN é um assistente AI que ajuda a conectar aplicativos e gerenciar o dia a dia do desenvolvedor. Inicie a sessão MARVIN com contexto completo e briefing diário","ru":"MARVIN - личный AI-помощник, который помогает подключать приложения и управлять рабочим днём разработчика. Запустите сессию MARVIN с полной загрузкой контекста и ежедневным брифингом","ar":"MARVIN هو مساعد إلكتروني شخصي يساعد على ربط التطبيقات وإدارة يوم المطور. ابدأ جلسة MARVIN مع تحميل السياق الكامل وتقديم الإحاطة اليومية","en":"MARVIN is your personal AI assistant that can help you connect to the apps you need and handle your day."},"seo":{"title":{"zh":"MARVIN启动技能：启动会话和加载上下文","ja":"MARVINスタートスキル：セッションの開始とコンテキストの読み込み","ko":"MARVIN 시작 스킬: 세션 시작 및 컨텍스트 로딩","es":"Inicia sesión con MARVIN","fr":"Démarrer avec MARVIN","de":"Starten Sie mit MARVIN","pt":"Inicie MARVIN: Assistente AI para Desenvolvedores","ru":"Запустите MARVIN: Личный AI-помощник для разработчиков","ar":"ابدأ MARVIN: مساعد إلكتروني شخصي للمطورين","en":"start"},"description":{"zh":"MARVIN启动技能可以帮助开发者启动会话、加载上下文和处理日常任务，提高开发效率","ja":"MARVINスタートスキルは、開発者がセッションを開始し、コンテキストを読み込み、日常タスクを効率的に処理できるようにします","ko":"MARVIN 시작 스킬은 개발자가 세션을 시작하고 컨텍스트를 로딩하며 일일 작업을 효율적으로 처리할 수 있도록 도와줍니다","es":"MARVIN es un asistente AI que carga el contexto completo y ofrece una breve descripción diaria para ayudar a los desarrolladores a gestionar su día","fr":"MARVIN est un assistant AI qui charge le contexte complet et offre une brève description quotidienne pour aider les développeurs à gérer leur journée","de":"MARVIN ist ein AI-Assistent, der den vollständigen Kontext lädt und eine tägliche Zusammenfassung bietet, um Entwicklern bei der Verwaltung ihres Tages zu he...","pt":"MARVIN é um assistente AI que ajuda a conectar aplicativos e gerenciar o dia a dia do desenvolvedor. Inicie a sessão MARVIN com contexto completo e briefing ...","ru":"MARVIN - личный AI-помощник, который помогает подключать приложения и управлять рабочим днём разработчика. Запустите сессию MARVIN с полной загрузкой контекс...","ar":"MARVIN هو مساعد إلكتروني شخصي يساعد على ربط التطبيقات وإدارة يوم المطور. ابدأ جلسة MARVIN مع تحميل السياق الكامل وتقديم الإحاطة اليومية","en":"MARVIN is your personal AI assistant that can help you connect to the apps you need and handle your day."},"definition":{"en":"MARVIN is your personal AI assistant that can help you connect to the apps you need and handle your day."},"features":{"zh":["启动会话","加载上下文","处理日常任务","提高开发效率","支持多语言","易于集成"],"ja":["セッションの開始","コンテキストの読み込み","日常タスクの処理","開発効率の向上","多言語対応","簡単な統合"],"ko":["세션 시작","컨텍스트 로딩","일일 작업 처리","개발 효율성 향상","다중 언어 지원","쉽게 통합"],"es":["Carga de contexto completo","Breve descripción diaria","Conexión a aplicaciones necesarias","Gestión del día","Compatibilidad con Claude Code","Resumen de prioridades y threads abiertos"],"fr":["Chargement du contexte complet","Description quotidienne concise","Connexion aux applications nécessaires","Gestion de la journée","Compatibilité avec Claude Code","Résumé des priorités et des threads ouverts"],"de":["Vollständiger Kontextladung","Tägliche Zusammenfassung","Verbindung zu benötigten Anwendungen","Tagverwaltung","Kompatibilität mit Claude Code","Zusammenfassung von Prioritäten und offenen Threads"],"pt":["Iniciação de sessão MARVIN com contexto completo","Briefing diário para desenvolvedores","Conexão a aplicativos necessários","Gerenciamento do dia a dia do desenvolvedor","Uso de comandos para iniciar a sessão","Compatibilidade com Claude Code"],"ru":["Запуск сессии MARVIN с полной загрузкой контекста","Ежедневный брифинг для разработчиков","Подключение к необходимым приложениям","Управление рабочим днём разработчика","Использование команд для запуска сессии","Совместимость с Claude Code"],"ar":["بدء جلسة MARVIN مع تحميل السياق الكامل","تقديم الإحاطة اليومية للمطورين","ربط التطبيقات الضرورية","إدارة يوم المطور","استخدام الأوامر لبدء الجلسة","التوافق مع Claude Code"]},"keywords":{"zh":["MARVIN启动技能","人工智能助手","开发者工具","会话管理","上下文加载","日常任务处理","开发效率","多语言支持"],"ja":["MARVINスタートスキル","AIアシスタント","開発者ツール","セッション管理","コンテキスト読み込み","日常タスク処理","開発効率","多言語対応"],"ko":["MARVIN 시작 스킬","인공지능 어시스턴트","개발자 도구","세션 관리","컨텍스트 로딩","일일 작업 처리","개발 효율성","다중 언어 지원"],"es":["asistente AI","desarrollo de software","gestión del día","conexión a aplicaciones","Claude Code","prioridades","threads abiertos","resumen diario"],"fr":["assistant AI","développement de logiciels","gestion de la journée","connexion à des applications","Claude Code","priorités","threads ouverts","résumé quotidien"],"de":["AI-Assistent","Software-Entwicklung","Tagverwaltung","Verbindung zu Anwendungen","Claude Code","Prioritäten","offene Threads","tägliche Zusammenfassung"],"pt":["MARVIN","assistente AI","desenvolvedor","produtividade","contexto completo","briefing diário","Claude Code","aplicativos","gerenciamento"],"ru":["MARVIN","личный AI-помощник","разработчик","производительность","полная загрузка контекста","ежедневный брифинг","Claude Code","приложения","управление"],"ar":["MARVIN","مساعد إلكتروني شخصي","مطور","إنتاجية","سياق كامل","إحاطة يومية","Claude Code","تطبيقات","إدارة"]}},"owner":"SterlingChin","repo":"marvin-template","repoPath":"SterlingChin/marvin-template","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.669Z","topics":[],"category":"community","skillMd":{"name":"start","description":"|","bodyPreview":"# Session Start Skill\n\nStart MARVIN session with full context loading and daily briefing.\n\n## When to Use\n\n- When user types `/start`\n- At the start of any Claude Code session in the MARVIN directory\n- When resuming work after a break\n\n## Process\n\n### Step 1: Establish Current Date\n```bash\ndate +%Y-%m-%d\n```\nStore as `TODAY`. Use for all file naming and date references.\n\n### Step 2: Load Context\n\nRead in order:\n1. `state/current.md` — Current priorities, open threads, and state\n2. `sessions/{TOD","body":"# Session Start Skill\n\nStart MARVIN session with full context loading and daily briefing.\n\n## When to Use\n\n- When user types `/start`\n- At the start of any Claude Code session in the MARVIN directory\n- When resuming work after a break\n\n## Process\n\n### Step 1: Establish Current Date\n```bash\ndate +%Y-%m-%d\n```\nStore as `TODAY`. Use for all file naming and date references.\n\n### Step 2: Load Context\n\nRead in order:\n1. `state/current.md` — Current priorities, open threads, and state\n2. `sessions/{TODAY}.md` — If exists, we''re resuming today\n3. If no today file, read `sessions/{YESTERDAY}.md` for continuity\n\n### Step 3: Review Goals\nCheck `state/goals.md` for:\n- Annual goals and progress\n- Monthly targets\n\n### Step 4: Assess Progress\nCheck `content/log.md` for current month:\n- Content shipped vs. goals\n- Days remaining in month\n\n### Step 5: Check Follow-ups\nReview `state/current.md` for any follow-up items:\n- Surface any items with review date ≤ TODAY\n- Remind user of upcoming follow-ups within 3 days\n\n### Step 6: Surface Proactive Alerts\nCompile and present:\n- **Active priorities** from `state/current.md`\n- **Open threads** needing attention\n- Content pacing status (if behind)\n- Any deadlines approaching\n\n### Step 7: Greet User\nPresent a concise briefing:\n- Date and day of week\n- Top 3 priorities\n- Any alerts or nudges\n- Ask how to help today\n\n## Output Format\n\n```\nGood morning! It''s {Day}, {Date}.\n\n**Today''s Focus:**\n1. {Priority 1}\n2. {Priority 2}\n3. {Priority 3}\n\n**Alerts:**\n- {Alert if any}\n\n**Progress ({Month}):**\n- {Goal 1}: X/Y\n- {Goal 2}: X/Y\n\nHow can I help today?\n```\n\n## Notes\n- If this is a resumed session (today''s log exists), acknowledge what was already covered\n- Keep briefing concise — details on request\n\n---\n\n*Skill created: 2026-01-22*\n"},"lastSynced":"2026-03-04T13:22:23.081Z","agentAnalysis":{"suitability":{"en":"Perfect for Personal AI Assistants needing automated daily briefing and context loading capabilities.","zh":"非常适合需要自动化日常简报和上下文加载功能的个人AI助手。","ja":"自動化された日常ブリーフィングとコンテキスト読み込み機能を必要とする個人AIアシスタントに最適です。","ko":"자동화된 일일 브리핑과 컨텍스트 로딩 기능이 필요한 개인 AI 어시스턴트에 적합합니다.","es":"Perfecto para Asistentes de IA Personales que necesitan capacidades de informe diario automatizado y carga de contexto.","fr":"Parfait pour les assistants d''IA personnels ayant besoin de capacités de briefing quotidien automatisé et de chargement de contexte.","de":"Perfekt für persönliche KI-Assistenten, die eine automatisierte tägliche Zusammenfassung und Kontextlade-Funktionen benötigen.","pt":"Perfeito para Assistentes de IA Pessoal que precisam de briefing diário automatizado e capacidades de carregamento de contexto.","ru":"Идеально подходит для личных помощников ИИ, которым необходимы автоматизированные ежедневные брифинги и возможности загрузки контекста.","ar":"مثالي لمساعدي الذكاء الاصطناعي الشخصيين الذين يحتاجون إلى إحاطة يومية آلية وقدرات تحميل السياق."},"recommendation":{"en":"Empowers agents to initiate sessions with full context loading, utilizing bash commands like `date +%Y-%m-%d` for dynamic date references and handling daily briefings through markdown files like `state/current.md`.","zh":"赋予代理以全上下文加载启动会话的能力，利用诸如`date +%Y-%m-%d`的bash命令进行动态日期引用，并通过诸如`state/current.md`的markdown文件处理日常简报。","ja":"エージェントに全コンテキスト読み込みでセッションを起動する機能を付与します。`date +%Y-%m-%d`などのbashコマンドを使用して動的な日付参照を行い、`state/current.md`などのマークダウンファイルを使用して日常ブリーフィングを処理します。","ko":"전체 컨텍스트 로딩으로 세션을 시작할 수 있는 에이전트의 능력을 강화하며, `date +%Y-%m-%d`와 같은 bash 명령을 사용하여 동적 날짜 참조를 수행하고, `state/current.md`와 같은 markdown 파일을 통해 일일 브리핑을 처리합니다.","es":"Permite a los agentes iniciar sesiones con carga de contexto completa, utilizando comandos de bash como `date +%Y-%m-%d` para referencias de fecha dinámicas y manejo de informes diarios a través de archivos markdown como `state/current.md`.","fr":"Permet aux agents d''initier des sessions avec un chargement de contexte complet, en utilisant des commandes bash comme `date +%Y-%m-%d` pour des références de date dynamiques et en gérant les briefings quotidiens via des fichiers markdown comme `state/current.md`.","de":"Ermöglicht es Agenten, Sitzungen mit vollständiger Kontextladefunktion zu starten, indem bash-Befehle wie `date +%Y-%m-%d` für dynamische Datumshinweise verwendet werden und tägliche Berichte über markdown-Dateien wie `state/current.md` gehandhabt werden.","pt":"Habilita os agentes a iniciar sessões com carregamento de contexto completo, utilizando comandos bash como `date +%Y-%m-%d` para referências de data dinâmicas e lidando com briefings diários por meio de arquivos markdown como `state/current.md`.","ru":"Наделяет агентов возможностью инициировать сессии с полной загрузкой контекста, используя команды bash, такие как `date +%Y-%m-%d`, для динамических ссылок на даты и обработки ежедневных брифингов через файлы markdown, такие как `state/current.md`.","ar":"تمكين الوكلاء من بدء الجلسات مع تحميل السياق الكامل، باستخدام أوامر bash مثل `date +%Y-%m-%d` لمراجع تواريخ ديناميكية ومعالجة الإحاطات اليومية من خلال ملفات markdown مثل `state/current.md`."},"useCases":{"en":["Initializing MARVIN sessions with daily briefings","Loading current state and priorities from `state/current.md`","Resuming work after a break with updated context"],"zh":["使用日常简报初始化MARVIN会话","从`state/current.md`加载当前状态和优先级","在休息后使用更新的上下文恢复工作"],"ja":["日常ブリーフィングでMARVINセッションを初期化する","`state/current.md`から現在の状態と優先順位を読み込む","休憩後に更新されたコンテキストで作業を再開する"],"ko":["일일 브리핑으로 MARVIN 세션을 초기화하는 것","`state/current.md`에서 현재 상태와 우선순위를 로딩하는 것","휴식 후에 업데이트된 컨텍스트로 작업을 재개하는 것"],"es":["Inicializar sesiones de MARVIN con informes diarios","Cargar estado actual y prioridades desde `state/current.md`","Reanudar el trabajo después de un descanso con contexto actualizado"],"fr":["Initialiser des sessions MARVIN avec des briefings quotidiens","Charger l''état actuel et les priorités à partir de `state/current.md`","Reprendre le travail après une pause avec un contexte mis à jour"],"de":["Initialisieren von MARVIN-Sitzungen mit täglichen Berichten","Laden des aktuellen Zustands und der Prioritäten aus `state/current.md`","Wiederaufnahme der Arbeit nach einer Pause mit aktualisiertem Kontext"],"pt":["Inicializar sessões MARVIN com briefings diários","Carregar estado atual e prioridades de `state/current.md`","Retomar o trabalho após uma pausa com contexto atualizado"],"ru":["Инициировать сессии MARVIN с ежедневными брифингами","Загрузить текущее состояние и приоритеты из `state/current.md`","Возобновить работу после перерыва с обновленным контекстом"],"ar":["تهيئة جلسات MARVIN بإحاطات يومية","تحميل الحالة الحالية والأولويات من `state/current.md`","استئناف العمل بعد فترة راحة مع سياق محدث"]},"limitations":{"en":["Requires filesystem access for reading and writing files like `state/current.md` and `sessions/{TODAY}.md`","Dependent on bash for date command execution"],"zh":["需要文件系统访问权限以读取和写入诸如`state/current.md`和`sessions/{TODAY}.md`的文件","依赖bash执行日期命令"],"ja":["`state/current.md`や`sessions/{TODAY}.md`などのファイルを読み書きするためにファイルシステムへのアクセスが必要","日付コマンドの実行にbashに依存している"],"ko":["`state/current.md` 및 `sessions/{TODAY}.md`와 같은 파일을 읽고 쓰기 위해 파일 시스템에 액세스해야 함","날짜 명령어 실행에 bash에 의존함"],"es":["Requiere acceso al sistema de archivos para leer y escribir archivos como `state/current.md` y `sessions/{TODAY}.md`","Dependiente de bash para la ejecución de comandos de fecha"],"fr":["Nécessite un accès au système de fichiers pour lire et écrire des fichiers comme `state/current.md` et `sessions/{TODAY}.md`","Dépendant de bash pour l''exécution de commandes de date"],"de":["Benötigt Zugriff auf das Dateisystem zum Lesen und Schreiben von Dateien wie `state/current.md` und `sessions/{TODAY}.md`","Abhängig von bash für die Ausführung von Datumsbefehlen"],"pt":["Requer acesso ao sistema de arquivos para leitura e gravação de arquivos como `state/current.md` e `sessions/{TODAY}.md`","Dependente do bash para execução de comandos de data"],"ru":["Требует доступа к файловой системе для чтения и записи файлов, таких как `state/current.md` и `sessions/{TODAY}.md`","Зависит от bash для выполнения команд даты"],"ar":["يتطلب الوصول إلى نظام الملفات لقراءة وكتابة الملفات مثل `state/current.md` و `sessions/{TODAY}.md`","يعتمد على bash لتنفيذ أوامر التاريخ"]},"version":3},"contentHash":"c299ccc89aed3501d3e0595a80df49cffa82595f067d1e2fd676a2c875ca7e65","qualityScore":48}');
