INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sunholo-data/ailang/Benchmark Manager', 'Benchmark Manager', 'sunholo-data', 'ailang', 'community', 'Benchmark Manager sunholo-data ailang community AI Benchmark Manager - AI AI Benchmark Manager - AI AI Benchmark Manager - AI Benchmark Manager es una herramienta de AI que permite a los desarrolladores medir y analizar el rendimiento de los agentes de IA Benchmark Manager est un outil d''IA qui permet aux développeurs de mesurer et d''analyser les performances des agents d''IA Benchmark Manager ist ein KI-Tool, mit dem Entwickler die Leistung von KI-Agents messen und analysieren können O Gerenciador de Benchmark é uma ferramenta para avaliar o desempenho de Ferramentas de IA, permitindo aos desenvolvedores otimizar suas soluções Менеджер бенчмарков - это инструмент для оценки производительности ИИ Агентов, позволяющий разработчикам оптимизировать свои решения مدير اختبار الأداء هو أداة لتقييم أداء وكلاء الذكاء الاصطناعي، مما يسمح للمطورين بتحسين حلولهم For humans, a language is a tool for expression. For AIs, it''s a substrate for reasoning. AI Benchmark Manager - AI AI Benchmark Manager - AI AI Benchmark Manager - AI AI Benchmark Manager - AI AI Benchmark Manager - AI For humans, a language is a tool for expression. For AIs, it''s a substrate for reasoning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('changoo89/claude-pilot/docs-verify', 'community', 'changoo89', 'claude-pilot', 'changoo89/claude-pilot', 'docs-verify', 0, 0, 48, '2026-03-04T13:07:01.694Z', '2026-03-04T13:35:58.359Z', 'fbcaac30e65b2a7868959a90ae218da03c774998dfaf78b31189df0519c1cafd', '{"id":"changoo89/claude-pilot/docs-verify","name":"docs-verify","description":{"zh":"docs-verify 是一个 AI 智能代理，提供从想法到生产的全流程管理，包含 SPEC-first 规划、TDD 自动化、GPT 委托和上下文工程。","ja":"docs-verify は、アイデアから生産までの一連の流れを管理する AI エージェントです。SPEC 第一の計画、TDD 自動化、GPT 委託、コンテキスト エンジニアリングを含みます。","ko":"docs-verify는 아이디어에서 생산까지의 전체 프로세스를 관리하는 AI 에이전트입니다. SPEC-첫 계획, TDD 자동화, GPT 위임 및 컨텍스트 엔지니어링을 포함합니다.","es":"docs-verify es un motor de flujo de trabajo que combina planificación SPEC-first, automatización TDD, delegación GPT y ingeniería de contexto para desarrolladores","fr":"docs-verify est un moteur de flux de travail qui combine la planification SPEC-first, l''automatisation TDD, la délégation GPT et l''ingénierie de contexte pour les développeurs","de":"docs-verify ist ein Workflow-Motor, der SPEC-first-Planung, TDD-Automatisierung, GPT-Delegation und Kontext-Engineering für Entwickler kombiniert","pt":"O docs-verify é um motor de workflow de código que oferece planejamento SPEC-first, automação TDD e delegação GPT para desenvolvedores","ru":"docs-verify - это движок потока кодирования, который предлагает планирование SPEC-first, автоматизацию TDD и делегирование GPT для разработчиков","ar":"docs-verify هو محرك سير عمل الكود الذي يقدم تخطيط SPEC-first والتحكم التلقائي TDD وت 委هدة GPT للمطورين","en":"🎯 Claude Code workflow engine - SPEC-first planning, TDD automation, GPT delegation, and context engineering. From idea to production, discipline included."},"seo":{"title":{"zh":"AI智能代理 docs-verify -SPEC-first 规划与 TDD 自动化","ja":"AIエージェント docs-verify - SPEC第一の計画と TDD 自動化","ko":"AI 에이전트 doc