INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tatargabor/wt-tools/openspec-explore', 'openspec-explore', 'tatargabor', 'wt-tools', 'community', 'openspec-explore tatargabor wt-tools community ai-agent claude-code cli developer-tools git-worktree mcp pyside6 openspec-explore是一款AI辅助开发工具，帮助开发者管理多项目工作流、长时间运行任务和人机协作 openspec-exploreは、開発者がマルチプロジェクトワークフロー、長時間実行タスク、ヒューマンAIコラボレーションを管理するためのAIエージェントツールです openspec-explore는 개발자가 멀티 프로젝트 워크플ロー, 장기 실행 태스크 및 인간-AI 협력을 관리하는 데 도움이 되는 AI 에이전트 도구입니다 La habilidad openspec-explore ofrece herramientas para gestionar contexto, enfoque y trabajo paralelo en desarrollo asistido por IA La compétence openspec-explore propose des outils pour gérer le contexte, la focalisation et le travail parallèle dans le développement assisté par IA Die Fähigkeit openspec-explore bietet Tools für die Kontext-, Fokus- und Parallelarbeit in der von der KI unterstützten Entwicklung openspec-explore é uma ferramenta de agente de IA para gerenciar contexto e foco em desenvolvimento assistido por IA, projetada para fluxos de trabalho multi-projeto openspec-explore - это инструмент ИИ Агентов для управления контекстом и фокусом в разработке с помощью ИИ, предназначенный для многопроектных рабочих процессов openspec-explore هي أداة الإجابة الذكية لتسهيل التطوير بمساعدة الإجابة الذكية، مصممة للعمل على مشاريع متعددة Tools for managing context, focus, and parallel work in AI-assisted development. Designed for multi-project workflows, long-running tasks, and human-AI collaboration. AI智能体 openspec-explore 开发者工具 CLI Git Worktree PySide6 如何使用openspec-explore openspec-explore安装 openspec-explore设置指南 Tools for managing context, focus, and parallel work in AI-assisted development. Designed for multi-project workflows, long-running tasks, and human-AI collaboration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('automagik-dev/omni/omni-executor', 'community', 'automagik-dev', 'omni', 'automagik-dev/omni', 'omni-executor', 6, 0, 47, '2026-02-26T02:14:51Z', '2026-02-26T13:22:51.763Z', 'c085abf928f0664ab408c52ec5dad68e1d27be7be269bfa1ef434842f08d61f8', '{"id":"automagik-dev/omni/omni-executor","name":"omni-executor","description":{"zh":"omni-executor是一个通用事件驱动的AI智能代理平台，支持跨多个消息平台的通信","ja":"omni-executorは、AIエージェントのためのオムニチャネルプラットフォームです。さまざまなメッセージングプラットフォーム間の通信を可能にします","ko":"omni-executor는 AI 에이전트를 위한 유니버설 이벤트 드리븐 플랫폼으로 여러 메시징 플랫폼 간의 통신을 지원합니다","es":"La plataforma Omni-Executor es una solución universal para la comunicación de agentes de IA a través de cualquier plataforma de mensajería, utilizando eventos y tecnologías como NATS y TypeScript","fr":"La plateforme Omni-Executor est une solution universelle pour la communication des agents IA à travers n''importe quelle plateforme de messagerie, utilisant des événements et des technologies comme NATS et TypeScript","de":"Die Omni-Executor-Plattform ist eine universelle Lösung für die Kommunikation von KI-Agents über jede Messaging-Plattform, unter Verwendung von Ereignissen und Technologien wie NATS und TypeScript","pt":"A plataforma Omni-Executor é uma solução universal e baseada em eventos para agentes de IA se comunicarem através de qualquer plataforma de mensagens.","ru":"Платформа Омни-Executor представляет собой универсальную событийно-ориентированную платформу для коммуникации ИИ Агентов через любую платформу обмена сообщениями.","ar":"تعتبر منصة Omni-Executor حلًا عالميًا وقائمًا على الأحداث للوكلاء الذكية للتواصل عبر أي منصة مراسلة.","en":"Universal event-driven omnichannel platform for AI agents to communicate across any messaging platform"},"seo":{"title":{"zh":"AI智能代理omni-executor：通用事件驱动平台","ja":"AIエージェントomni-executor：オムニチャネルプラットフォーム","ko":"AI 에이전트 omni-executor