INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('prompt-security/clawsec/claw-release', 'claw-release', 'prompt-security', 'clawsec', 'community', 'claw-release prompt-security clawsec community Claw Release是一款为OpenClaw家族代理提供的完整安全套件，提供实时安全建议、自动审计和技能完整性验证 Claw Releaseは、OpenClawファミリーのエージェント向けの完全セキュリティスイートで、リアルタイムのセキュリティ推奨、自動監査、スキル完全性の検証を提供する Claw Release는 OpenClaw 에이전트 가족을 위한 완벽한 보안套件으로, 실시간 보안 권장, 자동 감사, 스킬 무결성 확인을 제공합니다 claw-release es un conjunto de seguridad integral para la familia de agentes de OpenClaw, que protege tus archivos con detección de drif, recomendaciones de seguridad en vivo y auditorías automatizadas claw-release est une suite de sécurité complète pour la famille d''agents OpenClaw, qui protège vos fichiers avec une détection de drift, des recommandations de sécurité en temps réel et des audits automatisés claw-release ist ein umfassendes Sicherheits-Tool-Set für die OpenClaw-Agenten-Familie, das Ihre Dateien mit Drift-Erkennung, Live-Sicherheitsempfehlungen und automatisierten Audits schützt O claw-release é uma suíte de segurança para agentes OpenClaw, oferecendo detecção de drift, recomendações de segurança ao vivo e auditorias automatizadas claw-release - это набор инструментов безопасности для агентов OpenClaw, предлагающий обнаружение дрифта, живые рекомендации по безопасности и автоматические аудиты claw-release هي مجموعة أدوات أمان لعميل OpenClaw ، تقدم الكشف عن الانجراف والتوصيات الأمنية الحية والتدقيق الآلي A complete security skill suite for OpenClaw''s family of agents. Protect your SOUL.md (etc'') with drift detection, live security recommendations, automated audits, and skill integrity verification. All from one installable suite. AI智能代理安全 OpenClaw安全套件 实时安全建议 自动审计工具 技能完整性验证方法 SOUL.md保护 A complete security skill suite for OpenClaw''s family of agents. Protect your SOUL.md (etc'') with drift detection, live security recommendations, automated audits, and skill integrity verification. All from one installable suite.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flutter-it/get_it/flutter-architecture-expert', 'community', 'flutter-it', 'get_it', 'flutter-it/get_it', 'flutter-architecture-expert', 0, 0, 47, '2026-03-04T13:07:01.672Z', '2026-03-04T13:23:15.731Z', '71b05c718fd82432c40093d42f55a3edef1eb7609c6f5d9b036000f9aa519101', '{"id":"flutter-it/get_it/flutter-architecture-expert","name":"flutter-architecture-expert","description":{"zh":"Flutter架构专家提供简单的服务定位器，解耦接口和具体实现","ja":"Flutterアーキテクチャ専門家は、シンプルなサービスロケータを提供して、インターフェースと具体的な実装を解除","ko":"Flutter 아키텍처 전문가는 간단한 서비스 로케이터를 제공하여 인터페이스와 구체적인 구현을 분리","es":"El experto en arquitectura Flutter es un localizador de servicios simple que permite desacoplar la interfaz de una implementación concreta","fr":"L''expert en architecture Flutter est un localisateur de services simple qui permet de découpler l''interface d''une implémentation concrète","de":"Der Expert für Flutter-Architektur ist ein einfacher Service-Locator, der es ermöglicht, die Schnittstelle von einer konkreten Implementierung zu entkoppeln","pt":"O especialista em arquitetura Flutter é uma ferramenta de IA que simplifica a criação de aplicações móveis, permitindo a decoupling da interface da implementação concreta","ru":"Эксперт по архитектуре Flutter - это инструмент ИИ, который упрощает создание мобильных приложений, позволяя декуплировать интерфейс от конкретной реализации","ar":"خبير هندسة Flutter هو أداة ذكاء اصطناعي يسهل إنشاء التطبيقات المحمولة، مما يسمح بفصل الواجهة عن التنفيذ المحدد","en":"Get It - Simple direct Service Locator that allows to decouple the interface from a concrete implementation and to access the concrete implementation from everywhere in your App. Maintainer: @escamoteur"},"seo":{"title":{"zh":"AI智能代理-Flutter架构专家","ja":"AIエージェント：Flutterアーキテクチャ専門家","ko":"AI 에이전트: Flutter 아키텍처 전문가","es":"Herramientas de Inteligencia Artificial: Experto