INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('simnova/sharethrift/apollo-client', 'apollo-client', 'simnova', 'sharethrift', 'community', 'apollo-client simnova sharethrift community Apollo Client是一个应用开发框架，用于构建共享应用和知识共享系统，促进资源共享和协作 Apollo Clientは、共有アプリケーションと知識共有システムを構築するためのアプリケーション開発フレームワークです Apollo Client는 공유 애플리케이션과 지식 공유 시스템을 구축하기 위한 애플리케이션 개발 프레임워크입니다 Apollo Client es una aplicación que facilita el intercambio de conocimientos y recursos en la comunidad de desarrolladores Apollo Client est une application qui facilite le partage de connaissances et de ressources dans la communauté des développeurs Apollo Client ist eine Anwendung, die den Wissens- und Ressourcenaustausch in der Entwicklergemeinschaft erleichtert O Apollo Client é uma aplicação desenvolvida para incentivar o compartilhamento de recursos físicos e conhecimento em desenvolvimento de sistemas ИИ Агент Apollo Client - это приложение, разработанное для поощрения обмена физическими ресурсами и знаниями в разработке систем Apollo Client هو تطبيق تم تطويره لتشجيع التبادل للموارد المادية والمعرفة في تطوير الأنظمة Application developed to help encourage sharing - Both in sharing physical goods by using the public website - as well as sharing knowledge in how the system is developed. Apollo Client安装 Apollo Client教程 共享应用开发 知识共享系统 React开发 Node.js开发 CLI命令 Agent功能 Application developed to help encourage sharing - Both in sharing physical goods by using the public website - as well as sharing knowledge in how the system is developed.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KengoTODA/inspequte/inspequte-rule-spec', 'community', 'KengoTODA', 'inspequte', 'KengoTODA/inspequte', 'inspequte-rule-spec', 0, 0, 47, '2026-03-04T13:07:01.741Z', '2026-03-04T14:06:13.003Z', '091d73c3c9602cabec7e305faa59525c6bcc6b8a5ffd8ca5216c9333b4c698d8', '{"id":"KengoTODA/inspequte/inspequte-rule-spec","name":"inspequte-rule-spec","description":{"zh":"inspequte-rule-spec是一款快速的CLI静态分析工具，专为AI智能工具的JVM类和JAR文件设计","ja":"inspequte-rule-specは、AIエージェントのための高速なCLI静的分析ツールで、JVMクラスとJARファイルの分析をサポートしています","ko":"inspequte-rule-spec는 AI 에이전트를 위한 고속 CLI 정적 분석 도구로, JVM 클래스 및 JAR 파일 분석을 지원합니다","es":"inspequte-rule-spec es una herramienta de análisis de código estático rápida y basada en CLI para archivos de clase y JAR de JVM, diseñada para agentes de codificación","fr":"inspequte-rule-spec est un outil d''analyse de code statique rapide et basé sur CLI pour les fichiers de classe et JAR JVM, conçu pour les agents de codage","de":"inspequte-rule-spec ist ein schnelles, CLI-basiertes Tool für die statische Code-Analyse für JVM-Klassendateien und JAR-Dateien, entwickelt für Codierungsagenten","pt":"Inspequte é uma ferramenta de análise estática rápida e baseada em CLI para arquivos de classe e JAR do JVM, projetada para agentes de codificação.","ru":"Inspequte - быстрый инструмент статического анализа с интерфейсом командной строки для файлов классов и JAR JVM, разработан для кодирования агентов ИИ.","ar":"إنسبكوت هو أداة تحليل ثابت سريع وقائم على واجهة سطر الأوامر للفصول الدراسية والملفات الجار للجافا، مصممة لعمال التشفير","en":"Fast, CLI-first static analysis tool for JVM class and JAR files. Designed for coding agents."},"seo":{"title":{"zh":"inspequte-rule-spec：AI智能工具的静态分析利器","ja":"inspequte-rule-spec：AIエージェントのための静的分析ツール","ko":"inspequte-rule-spec: AI 에이전트를 위한 고속 정적 분석 도구","es":"Herramientas de Análisis de Código para Agentes de IA - i...","fr":"Outils d''Analyse de Code pour Agents d''IA - inspequte-rul...","de":"Code-Analyse-Tools für KI-Agents - inspequte-rule-spec","pt":"Ferramentas de Análise Estática para JVM - Inspequte","ru":"ИИ Агенты: Инструмент Статического Анализа JVM - Inspequte","ar":"أدوات التحليل الثابت للجافا - إنسبكوت","en":"inspequte-rule-spec"},"description":{"zh":"inspequte-rule-spec是一款快速的CLI静态分析工具，专为AI智能工具的JVM类和JAR文件设计","ja":"inspequte-rule-specは、AIエージェントのための高速なCLI静的分析ツールで、JVMクラスとJARファイルの分析をサポートしています","ko":"inspequte-rule-spec는 AI 에이전트를 위한 고속 CLI 정적 분석 도구로, JVM 클래스 및 JAR 파일 분석을 지원합니다","es":"inspequte-rule-spec es una herramienta de análisis de código estático rápida y basada en CLI para archivos de clase y JAR de JVM, diseñada para agentes de co...","fr":"inspequte-rule-spec est un outil d''analyse de code statique rapide et basé sur CLI pour les fichiers de classe et JAR JVM, conçu pour les agents de codage","de":"inspequte-rule-spec ist ein schnelles, CLI-basiertes Tool für die statische Code-Analyse für JVM-Klassendateien und JAR-Dateien, entwickelt für Codierungsage...","pt":"Inspequte é uma ferramenta de análise estática rápida e baseada em CLI para arquivos de classe e JAR do JVM, projetada para agentes de codificação.","ru":"Inspequte - быстрый инструмент статического анализа с интерфейсом командной строки для файлов классов и JAR JVM, разработан для кодирования агентов ИИ.","ar":"إنسبكوت هو أداة تحليل ثابت سريع وقائم على واجهة سطر الأوامر للفصول الدراسية والملفات الجار للجافا، مصممة لعمال التشفير","en":"Fast, CLI-first static analysis tool for JVM class and JAR files. Designed for coding agents."},"definition":{"en":"Fast, CLI-first static analysis tool for JVM class and JAR files. Designed for coding agents."},"features":{"zh":["快速的CLI静态分析","支持JVM类和JAR文件分析","为AI智能工具设计","静态分析功能","支持多种文件格式"],"ja":["高速なCLI静的分析","JVMクラスとJARファイルの分析をサポート","AIエージェントのためのツール","静的分析機能","複数のファイル形式をサポート"],"ko":["고속 CLI 정적 분석","JVM 클래스 및 JAR 파일 분석 지원","AI 에이전트를 위한 도구","정적 분석 기능","다중 파일 형식 지원"],"es":["Análisis de código estático rápido","Basado en CLI para una integración fácil","Diseñado para agentes de codificación","Soporte para archivos de clase y JAR de JVM","Herramienta ligera y eficiente"],"fr":["Analyse de code statique rapide","Basé sur CLI pour une intégration facile","Conçu pour les agents de codage","Prise en charge des fichiers de classe et JAR JVM","Outil léger et efficace"],"de":["Schnelle statische Code-Analyse","Basierend auf CLI für eine einfache Integration","Entwickelt für Codierungsagenten","Unterstützung für JVM-Klassendateien und JAR-Dateien","Leichtes und effizientes Tool"],"pt":["Análise estática rápida","Baseada em CLI","Suporte a arquivos de classe e JAR do JVM","Projetada para agentes de codificação","Fácil de usar e integrar"],"ru":["Быстрый статический анализ","Интерфейс командной строки","Поддержка файлов классов и JAR JVM","Разработан для кодирования агентов ИИ","Легко использовать и интегрировать"],"ar":["تحليل ثابت سريع","واجهة سطر الأوامر","دعم الفصول الدراسية والملفات الجار للجافا","مصممة لعمال التشفير","سهل الاستخدام والتكامل"]},"keywords":{"zh":["inspequte-rule-spec","AI智能工具","静态分析","JVM类","JAR文件","CLI工具","如何使用inspequte-rule-spec","inspequte-rule-spec替代品","inspequte-rule-spec安装"],"ja":["inspequte-rule-spec","AIエージェント","静的分析","JVMクラス","JARファイル","CLIツール","inspequte-rule-specの使い方","inspequte-rule-specの代替","inspequte-rule-specのインストール"],"ko":["inspequte-rule-spec","AI 에이전트","정적 분석","JVM 클래스","JAR 파일","CLI 도구","inspequte-rule-spec 사용법","inspequte-rule-spec 대체","inspequte-rule-spec 설치"],"es":["herramientas de análisis de código","agentes de IA","análisis de código estático","inspequte-rule-spec","cómo usar inspequte-rule-spec","alternativas a inspequte-rule-spec","instalación de inspequte-rule-spec"],"fr":["outils d''analyse de code","agents d''IA","analyse de code statique","inspequte-rule-spec","comment utiliser inspequte-rule-spec","alternatives à inspequte-rule-spec","installation d''inspequte-rule-spec"],"de":["Code-Analyse-Tools","KI-Agents","statische Code-Analyse","inspequte-rule-spec","wie man inspequte-rule-spec verwendet","Alternativen zu inspequte-rule-spec","Installation von inspequte-rule-spec"],"pt":["ferramentas de análise estática","Inspequte","JVM","análise de classe","análise de JAR","como usar Inspequte","o que é Inspequte","alternativas para Inspequte","Inspequte vs outras ferramentas"],"ru":["инструменты статического анализа","Inspequte","JVM","анализ классов","анализ JAR","как использовать Inspequte","что такое Inspequte","альтернативы Inspequte","Inspequte vs другие инструменты"],"ar":["أدوات التحليل الثابت","إنسبكوت","جافا","تحليل الفصول الدراسية","تحليل الملفات الجار","كيفية استخدام إنسبكوت","ما هو إنسبكوت","بديلات إنسبكوت","إنسبكوت مقابل أدوات أخرى"]}},"owner":"KengoTODA","repo":"inspequte","repoPath":"KengoTODA/inspequte","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.741Z","topics":[],"category":"community","skillMd":{"name":"inspequte-rule-spec","description":"Author or refine an inspequte rule spec from a rule idea, optional plan.md, and target rule-id. Use when writing src/rules/<rule-id>/spec.md from a fixed template while avoiding implementation details.","bodyPreview":"# inspequte rule spec\n\n## Inputs\n- Target `rule-id`.\n- Rule idea text.\n- Optional `src/rules/<rule-id>/plan.md`.\n\n## Outputs\n- Create or update `src/rules/<rule-id>/spec.md`.\n- Keep scope contractual; avoid implementation details beyond constraints.\n\n## Fixed Template\nUse this exact section order:\n1. `## Summary`\n2. `## Motivation`\n3. `## What it detects`\n4. `## What it does NOT detect`\n5. `## Examples (TP/TN/Edge)`\n6. `## Output`\n7. `## Performance considerations`\n8. `## Acceptance criteria`\n\n#","body":"# inspequte rule spec\n\n## Inputs\n- Target `rule-id`.\n- Rule idea text.\n- Optional `src/rules/<rule-id>/plan.md`.\n\n## Outputs\n- Create or update `src/rules/<rule-id>/spec.md`.\n- Keep scope contractual; avoid implementation details beyond constraints.\n\n## Fixed Template\nUse this exact section order:\n1. `## Summary`\n2. `## Motivation`\n3. `## What it detects`\n4. `## What it does NOT detect`\n5. `## Examples (TP/TN/Edge)`\n6. `## Output`\n7. `## Performance considerations`\n8. `## Acceptance criteria`\n\n## Minimal Context Loading\n1. Read `src/rules/AGENTS.md`.\n2. Read existing `src/rules/<rule-id>/spec.md` if present.\n3. Read `src/rules/<rule-id>/plan.md` if present.\n4. Read at most one related rule spec for style alignment.\n5. Do not perform repo-wide scans.\n\n## Guardrails\n- Treat `spec.md` as a behavior contract, not a design doc.\n- Do not include Rust APIs, struct names, function names, or algorithm internals.\n- Keep messages user-facing and actionable.\n- In `## Summary`, define intended rule metadata (`id`, `name`, `description`) clearly so implementation can map it directly.\n- State annotation scope explicitly: `@Suppress`-style suppression is unsupported, and only JSpecify annotations are supported for annotation-driven semantics.\n\n## Definition of Done\n- `spec.md` exists under the target rule directory.\n- All template sections are present and non-empty.\n- Examples include true positive, true negative, and edge cases.\n- Implementation-specific details are excluded.\n"},"lastSynced":"2026-03-04T14:06:13.003Z","agentAnalysis":{"suitability":{"en":"Ideal for Coding Agents requiring comprehensive static analysis of JVM class and JAR files.","zh":"适合需要对JVM类和JAR文件进行全面静态分析的编码代理。","ja":"JVMクラスおよびJARファイルの包括的な静的分析を必要とするコーディングエージェントに適しています。","ko":"JVM 클래스 및 JAR 파일의 포괄적인 정적 분석을 요구하는 코딩 에이전트에 적합합니다.","es":"Ideal para Agentes de Codificación que requieren un análisis estático integral de archivos de clase JVM y JAR.","fr":"Idéal pour les Agents de Codage nécessitant une analyse statique complète de fichiers de classe JVM et JAR.","de":"Ideal für Coding-Agents, die eine umfassende statische Analyse von JVM-Klassen- und JAR-Dateien erfordern.","pt":"Ideal para Agentes de Codificação que exigem análise estática abrangente de classes JVM e arquivos JAR.","ru":"Идеально подходит для агентов кодирования, которым требуется всесторонний статический анализ классов JVM и файлов JAR.","ar":"مثالي للوكلاء البرمجيين الذين يتطلبون تحليلًا ثابتًا شاملًا لملفات فئة JVM و JAR."},"recommendation":{"en":"Empowers agents to perform fast and efficient static analysis using CLI-first tools, generating detailed spec.md files for rule specifications, and adhering to a fixed template for consistency, utilizing Markdown files such as plan.md and spec.md.","zh":"赋予代理快速高效地执行静态分析的能力，使用CLI-first工具，生成详细的规则规范文件spec.md，并遵循固定的模板以确保一致性，利用Markdown文件如plan.md和spec.md。","ja":"CLI-firstツールを使用して迅速かつ効率的に静的分析を実行するエージェントを可能にし、詳細なルール仕様ファイルspec.mdを生成し、plan.mdおよびspec.mdなどのMarkdownファイルに従って一貫性を保つ。","ko":"CLI-first 도구를 사용하여 빠르고 효율적인 정적 분석을 수행할 수 있는 에이전트를 가능하게 하며, 자세한 규칙 사양 파일 spec.md를 생성하고, 일관성을 유지하기 위해 plan.md 및 spec.md와 같은 Markdown 파일을 따릅니다.","es":"Permite a los agentes realizar un análisis estático rápido y eficiente utilizando herramientas CLI-first, generando archivos spec.md detallados para especificaciones de reglas y ajustándose a una plantilla fija para la coherencia, utilizando archivos Markdown como plan.md y spec.md.","fr":"Permet aux agents d''effectuer une analyse statique rapide et efficace à l''aide d''outils CLI-first, générant des fichiers spec.md détaillés pour les spécifications de règles et respectant un modèle fixe pour la cohérence, en utilisant des fichiers Markdown tels que plan.md et spec.md.","de":"Ermächtigt Agents, eine schnelle und effiziente statische Analyse mithilfe von CLI-First-Tools durchzuführen, indem detaillierte spec.md-Dateien für Regelspezifikationen generiert und eine feste Vorlage für die Konsistenz befolgt wird, unter Verwendung von Markdown-Dateien wie plan.md und spec.md.","pt":"Habilita os agentes a realizar análise estática rápida e eficiente usando ferramentas CLI-first, gerando arquivos spec.md detalhados para especificações de regras e aderindo a um modelo fixo para consistência, utilizando arquivos Markdown como plan.md e spec.md.","ru":"Наделяет агентов возможностью выполнять быстрый и эффективный статический анализ с помощью инструментов CLI-first, генерируя подробные файлы spec.md для спецификаций правил и соблюдая фиксированный шаблон для согласованности, используя файлы Markdown, такие как plan.md и spec.md.","ar":"تمكّن الوكلاء من أداء تحليل ساكن سريع وفعال باستخدام أدوات CLI-first، وتوليد ملفات spec.md مفصلة لمواصفات القواعد، والالتزام bằng قالب محدد للاتساق، واستخدام ملفات Markdown مثل plan.md و spec.md."},"useCases":{"en":["Analyzing JVM class files for security vulnerabilities","Generating rule specifications for coding standards","Validating JAR files against predefined rules"],"zh":["分析JVM类文件的安全漏洞","为编码标准生成规则规范","验证JAR文件是否符合预定义规则"],"ja":["JVMクラスファイルのセキュリティ脆弱性を分析する","コーディング規約のルール仕様を生成する","JARファイルが事前定義されたルールに準拠していることを検証する"],"ko":["JVM 클래스 파일의 보안 취약점 분석","코딩 표준의 규칙 사양 생성","JAR 파일이 사전 정의된 규칙을 준수하는지 확인"],"es":["Analizar archivos de clase JVM para vulnerabilidades de seguridad","Generar especificaciones de reglas para normas de codificación","Validar archivos JAR contra reglas predefinidas"],"fr":["Analyser les fichiers de classe JVM pour les vulnérabilités de sécurité","Générer des spécifications de règles pour les normes de codage","Valider les fichiers JAR contre des règles prédéfinies"],"de":["Analysieren von JVM-Klassen-Dateien auf Sicherheitslücken","Erstellen von Regelspezifikationen für Codierungsstandards","Überprüfen von JAR-Dateien gegen vordefinierte Regeln"],"pt":["Analisar arquivos de classe JVM para vulnerabilidades de segurança","Gerar especificações de regras para padrões de codificação","Validar arquivos JAR contra regras predefinidas"],"ru":["Анализировать файлы классов JVM на наличие уязвимостей безопасности","Генерировать спецификации правил для стандартов кодирования","Проверять файлы JAR на соответствие предопределенным правилам"],"ar":["تحليل ملفات فئة JVM للثغرات الأمنية","توليد مواصفات القواعد لمعايير البرمجة","التحقق من صحة ملفات JAR مقابل القواعد المحددة مسبقًا"]},"limitations":{"en":["Requires JVM class or JAR files as input","Limited to static analysis, does not support dynamic analysis"],"zh":["需要JVM类或JAR文件作为输入","仅限静态分析，不支持动态分析"],"ja":["JVMクラスまたはJARファイルを入力として必要とする","静的分析のみをサポートし、動的分析はサポートしない"],"ko":["JVM 클래스 또는 JAR 파일을 입력으로 필요로 함","정적 분석만 지원하며, 동적 분석은 지원하지 않음"],"es":["Requiere archivos de clase JVM o JAR como entrada","Limitado a análisis estático, no admite análisis dinámico"],"fr":["Nécessite des fichiers de classe JVM ou JAR comme entrée","Limité à l''analyse statique, ne prend pas en charge l''analyse dynamique"],"de":["Benötigt JVM-Klassen- oder JAR-Dateien als Eingabe","Begrenzt auf statische Analyse, unterstützt keine dynamische Analyse"],"pt":["Exige arquivos de classe JVM ou JAR como entrada","Limitado à análise estática, não suporta análise dinâmica"],"ru":["Требует файлов классов JVM или JAR в качестве входных данных","Ограничен статическим анализом, не поддерживает динамический анализ"],"ar":["يتطلب ملفات فئة JVM أو JAR كمدخلات","محدود بالتحليل الساكن، ولا يدعم التحليل الديناميكي"]},"version":3},"contentHash":"091d73c3c9602cabec7e305faa59525c6bcc6b8a5ffd8ca5216c9333b4c698d8","qualityScore":47}');
