INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Geeksfino/openskills/openskills-skill-authoring', 'openskills-skill-authoring', 'Geeksfino', 'openskills', 'community', 'openskills-skill-authoring Geeksfino openskills community openskills-skill-authoring提供了Rust runtime和TS/Python绑定，用于开发AI智能体技能 openskills-skill-authoringは、AIエージェントのスキル作成を可能にするRust runtimeとTS/Pythonバインディングを提供 openskills-skill-authoring은 AI 에이전트 스킬 개발을 위한 Rust runtime과 TS/Python 바인딩을 제공합니다 openskills-skill-authoring es un entorno de ejecución de Rust con enlaces de TS/Python para habilidades de Claude. Permite a cualquier agente poseer habilidades con divulgación progresiva de metadatos de habilidades openskills-skill-authoring est un environnement d''exécution Rust avec des liens TS/Python pour les compétences de Claude. Il permet à tout agent de posséder des compétences avec divulgation progressive des métadonnées de compétence openskills-skill-authoring ist eine Rust-Laufzeitumgebung mit TS/Python-Bindungen für Claude-Fähigkeiten. Sie ermöglicht es jedem Agenten, Fähigkeiten zu besitzen, mit progressiver Offenlegung von Fähigkeitsmetadaten O openskills-skill-authoring permite que qualquer agente de IA crie habilidades personalizadas com Rust e bindings em TS/Python ИИ Агенты могут создавать индивидуальные навыки с openskills-skill-authoring и Rust, используя TS/Python bindings يسمح openskills-skill-authoring لأي وكيل ذكاء إصطناعي بإنشاء مهارات مخصصة مع Rust وربط TS/Python Rust runtime with TS/Python bindings for Claude Skills with progressive disclosure of skill metadata, full content and scripts/resources. Any agent can now own skills. Currently support Seatbelt and experimentally, WASM, sandboxing AI智能体技能开发 openskills-skill-authoring Rust runtime TS/Python绑定 如何使用openskills-skill-authoring openskills-skill-authoring安装 AI智能体工具 Rust runtime with TS/Python bindings for Claude Skills with progressive disclosure of skill metadata, full content and scripts/resources. Any agent can now own skills. Currently support Seatbelt and experimentally, WASM, sandboxing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cdalsoniii/brightpath-coder/Authorization Matrix', 'community', 'cdalsoniii', 'brightpath-coder', 'cdalsoniii/brightpath-coder', 'Authorization Matrix', 0, 0, 47, '2026-03-04T13:07:01.818Z', '2026-03-04T14:36:57.841Z', '16075f97fb8929b0ba92cfb89062e0dae778d2d084fe64bf3855ccd536a175f1', '{"id":"cdalsoniii/brightpath-coder/Authorization Matrix","name":"Authorization Matrix","description":{"zh":"BrightPath CLI 是一个多 provider AI 代理编排工具，提供智能代理授权矩阵管理功能","ja":"BrightPath CLI は、マルチプロバイダの AI エージェントオーケストレーターであり、AI エージェントの認可マトリックスを管理します","ko":"BrightPath CLI는 멀티 프로바이더 AI 에이전트 오케스트레이터로, AI 에이전트 인증 매트릭스 관리 기능을 제공합니다","es":"BrightPath CLI es un orchestrador de agentes de IA multi-proveedor que simplifica la autorización y la gestión de acceso","fr":"BrightPath CLI est un orchestrateur d''agents IA multi-fournisseurs qui simplifie l''autorisation et la gestion d''accès","de":"BrightPath CLI ist ein Orchestrierer von KI-Agents mit mehreren Anbietern, der die Autorisierung und die Zugriffsverwaltung vereinfacht","pt":"O BrightPath CLI é um orquestrador de agente de IA que gerencia a autorização de matriz de forma eficiente","ru":"BrightPath CLI — это оркестратор ИИ агентов, который управляет матрицей авторизации эффективно","ar":"BrightPath CLI هو جهاز اوركستر لوكيل الذكي الذي يدير مصفوفة التفويض بفعالية","en":"BrightPath CLI — multi-provider AI agent orchestrator"},"seo":{"title":{"zh":"AI智能代理授权矩阵 - BrightPath CLI","ja":"AIエージェントの認可マトリックス - BrightPath CLI","ko":"AI 에이전트 인증 매트릭스 - BrightPath CLI","es":"Matriz de Autorización para Agentes de IA con BrightPath CLI","fr":"Matrice d''autorisation pour les agents IA avec BrightPath...","de":"Autorisierungsmatrix für KI-Agents mit BrightPath CLI","pt":"Autorização de Matriz - Ferramentas de Agente de IA","ru":"Матрица Авторизации - ИИ Агенты","ar":"مصفوفة تفويض - أدوات الوكيل الذ