INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jfarid27/open-eth-terminal/open-eth-terminal-action-generator', 'open-eth-terminal-action-generator', 'jfarid27', 'open-eth-terminal', 'community', 'open-eth-terminal-action-generator jfarid27 open-eth-terminal community open-eth-terminal-action-generator是一款基于CLI的数据聚合工具，适用于需要更高质量研究的以太坊金融市场日常零售交易者 open-eth-terminal-action-generatorは、より高品質な研究が必要なイーサリアム金融市場の日常小売りトレーダー向けのCLIベースのデータアグリゲーションツールです open-eth-terminal-action-generator는 더 높은 품질의 연구가 필요한 이더리움 금융 시장의 일상 소매 거래자를 위한 CLI 기반 데이터 집계 도구입니다 open-eth-terminal-action-generator es una herramienta de agregación de datos en línea de comandos para traders minoristas de Ethereum que buscan investigación de alta calidad en mercados financieros open-eth-terminal-action-generator est un outil d''aggrégation de données en ligne de commande pour les traders de détail Ethereum qui recherchent une recherche de haute qualité sur les marchés financiers open-eth-terminal-action-generator ist ein Datenaggregations-Tool auf Kommandozeilenebene für Ethereum-Privatanleger, die hochwertige Forschung in Finanzmärkten suchen A open-eth-terminal-action-generator é uma ferramenta de agregação de dados em linha de comando para traders retais que desejam pesquisas de alta qualidade em mercados financeiros de Ethereum ИИ Агент open-eth-terminal-action-generator - консольная утилита для сбора данных для розничных трейдеров, которые хотят получить качественные исследования на рынках Ethereum أداة تجميع البيانات open-eth-terminal-action-generator هي أداة سطر أوامر لتجميع البيانات لتجار التجزئة الذين يرغبون في بحث عالي الجودة في الأسواق المالية لإيثريوم A CLI based Data Aggregation tool for everyday retail traders that want higher quality research in Ethereum financial markets. 如何使用open-eth-terminal-action-generator 什么是以太坊金融市场研究 open-eth-terminal-action-generator安装 open-eth-terminal-action-generator设置指南 open-eth-terminal-action-generator替代品 open-eth-terminal-action-generator vs 其他工具 A CLI based Data Aggregation tool for everyday retail traders that want higher quality research in Ethereum financial markets. ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('magicappdev/magicappdev/building-ui', 'community', 'magicappdev', 'magicappdev', 'magicappdev/magicappdev', 'building-ui', 0, 0, 47, '2026-03-04T13:07:01.938Z', '2026-03-04T15:08:44.099Z', '6c480bb7eed58f573cb220652a3ca956a4c08eee8ee6ae0f717a1fe043c10efc', '{"id":"magicappdev/magicappdev/building-ui","name":"building-ui","description":{"zh":"MagicAppDev是一个综合的monorepo-based全栈应用开发平台，灵感来自Expo，利用Turborepo进行高效的monorepo管理","ja":"MagicAppDevは、Expoにインスパイアされたフルスタックアプリ開発プラットフォームで、Turborepoを使用した効率的なmonorepo管理を提供","ko":"MagicAppDev는 Expo에서 영감을 받은 풀스택 앱 개발 플랫폼으로, Turborepo를 사용하여 효율적인 모노리포 관리를 제공합니다","es":"MagicAppDev es una plataforma de desarrollo de aplicaciones de UI inspirada en Expo, que utiliza Turborepo para una gestión eficiente de monorepo","fr":"MagicAppDev est une plateforme de développement d''applications UI inspirée par Expo, qui utilise Turborepo pour une gestion efficace de monorepo","de":"MagicAppDev ist eine Plattform für die Entwicklung von UI-Anwendungen, die von Expo inspiriert ist und Turborepo für ein effizientes Monorepo-Management verwendet","pt":"Plataforma de desenvolvimento de aplicativos fullstack inspirada em Expo, com Turborepo para gestão de monorepo eficiente","ru":"Платформа для быстрого разработки, кастомизации и развертывания приложений на основе ИИ Агентов, использующая Turborepo","ar":"منصة شاملة لإنشاء تطبيقات متعددة المنصات باستخدام Turborepo لإدارة المونو ريبوزиторي الفعالة والتحكم في واجهات المستخدم","en":"A comprehensive monorepo-based fullstack app building platform inspired by Expo, utilizing Turborepo for efficient monorepo management. MagicAppDev enables rapid development, customization, and deployment of apps across web and mobile platforms."},"seo":{"title":{"zh":"AI智能开发工具 MagicAppDev","ja":"AIエージェントを活用したフルスタックアプリ開発 MagicAppDev","ko":"AI 에이전트를 활용한 풀스택 앱 개발 플랫폼 MagicAppDe