INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('troydai/gwt/gwt', 'gwt', 'troydai', 'gwt', 'community', 'gwt troydai gwt community gwt是一个Git工作树管理CLI，帮助开发者更好地管理Git工作树 gwtはGitワークツリー管理CLIであり、開発者がGitワークツリーをより効果的に管理できるようにします gwt는 Git 작업 트리 관리 CLI로서 개발자가 Git 작업 트리를 더 효율적으로 관리하도록 도와줍니다 gwt es una CLI para gestionar git worktree, que permite a los desarrolladores gestionar múltiples ramas de manera eficiente gwt est une CLI pour gérer les git worktree, ce qui permet aux développeurs de gérer plusieurs branches de manière efficace gwt ist eine CLI für die Verwaltung von git worktree, mit der Entwickler mehrere Branches effizient verwalten können O gwt é uma ferramenta de linha de comando para gerenciar worktrees git, ajudando a organizar e gerenciar seus projetos gwt - это инструмент командной строки для управления git worktree, помогающий организовать и управлять вашими проектами gwt هو أداة سطر أوامر لإدارة شجرة العمل جيت، تساعد على تنظيم وإدارة مشاريعك A git worktree management CLI gwt安装 Git工作树管理 gwt使用教程 Git CLI工具 gwt与git差异 gwt替代工具 如何使用gwt gwtsetup指南 gwt入门 A git worktree management CLI');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cesaroeduardo/icon-library-visualization/icon-library', 'community', 'cesaroeduardo', 'icon-library-visualization', 'cesaroeduardo/icon-library-visualization', 'icon-library', 0, 0, 46, '2026-03-02T07:37:53.645Z', '2026-03-02T09:29:13.696Z', '6958ead51703cb1427d06b4423652b7bdc0b78e214bc0c76fa27054da944d5df', '{"id":"cesaroeduardo/icon-library-visualization/icon-library","name":"icon-library","description":{"zh":"个人项目，创建图标库目录，用于开发人员的快速查找和使用","ja":"アイコンライブラリのカタログを作成する個人プロジェクト","ko":"아이콘 라이브러리 카탈로그를 만드는 개인 프로젝트","es":"El proyecto de biblioteca de iconos es una iniciativa personal para crear un catálogo de iconos personalizados utilizando herramientas de IA","fr":"Le projet de catalogue d''icônes est une initiative personnelle pour créer un catalogue d''icônes personnalisés en utilisant des outils d''IA","de":"Das Icon-Bibliotheksprojekt ist eine persönliche Initiative, um ein benutzerdefiniertes Icon-Verzeichnis mit KI-Tools zu erstellen","pt":"A biblioteca de ícones é um projeto pessoal para catálogo de ícones. Ele fornece uma coleção de ícones prontos para uso em projetos de design","ru":"Библиотека иконок - личный проект для каталога иконок. Он предоставляет коллекцию готовых иконок для использования в проектах дизайна","ar":"مكتبة الأيقونات هو مشروع شخصي لفهرس الأيقونات. يوفر مجموعة من الأيقونات الجاهزة للاستخدام في مشاريع التصميم","en":"Personal project for an icon library catalogue."},"seo":{"title":{"zh":"AIエージェント图标库","ja":"AIエージェントのアイコンライブラリ","ko":"AI 에이전트 아이콘 라이브러리","es":"Herramientas de biblioteca de iconos con Agentes de IA","fr":"Outil de catalogue d''icônes avec Outils d''IA","de":"Icon-Bibliothek mit KI-Agents","pt":"Biblioteca de Ícones: Ferramenta de Catálogo de Ícones AI","ru":"ИИ Агенты: Каталог иконок библиотеки","ar":"مكتبة الأيقونات: أداة فهرس الأيقونات الإصطناعية","en":"icon-library"},"description":{"zh":"个人项目，创建图标库目录，用于开发人员的快速查找和使用","ja":"アイコンライブラリのカタログを作成する個人プロジェクト","ko":"아이콘 라이브러리 카탈로그를 만드는 개인 프로젝트","es":"El proyecto de biblioteca de iconos es una iniciativa personal para crear un catálogo de iconos personalizados utilizando herramientas de IA","fr":"Le projet de catalogue d''icônes est une initiative personnelle pour créer un catalogue d''icônes personnalisés en utilisant des outils d''IA","de":"Das Icon-Bibliotheksprojekt ist eine persönliche Initiative, um ein benutzerdefiniertes Icon-Verzeichnis mit KI-Tools zu erstellen","pt":"A biblioteca de ícones é um projeto pessoal para catálogo de ícones. Ele fornece uma coleção de ícones prontos para uso em projetos de design","ru":"Библиотека иконок - личный проект для каталога иконок. Он предоставляет коллекцию готовых иконок для использования в проектах дизайна","ar":"مكتبة الأيقونات هو مشروع شخصي لفهرس الأيقونات. يوفر مجموعة من الأيقونات الجاهزة للاستخدام في مشاريع التصميم","en":"Personal project for an icon library catalogue."},"definition":{"en":"Personal project for an icon library catalogue."},"features":{"zh":["支持多种图标格式","图标快速搜索和查找","开发人员易于使用","支持React、Python、Node.js等开发框架","提供CLI工具用于快速安装和设置"],"ja":["複数のアイコン形式をサポート","アイコンの高速検索と探索","開発者向けの使いやすいインターフェース","React、Python、Node.jsなどの開発フレームワークをサポート","CLIツールを提供して簡単にインストールと設定"],"ko":["여러 아이콘 형식을 지원","아이콘 빠른 검색과 찾기","개발자에게 쉬운 사용","React, Python, Node.js 등의 개발 프레임워크 지원","CLI 도구 제공하여 빠른 설치와 설정"],"es":["Implementación de iconos personalizados","Uso de herramientas de IA para la creación de iconos","Catálogo de iconos personalizados","Compatibilidad con diferentes formatos de iconos","Integración con frameworks de desarrollo como React y Node.js"],"fr":["Implémentation d''icônes personnalisés","Utilisation d''outils d''IA pour la création d''icônes","Catalogue d''icônes personnalisés","Compatibilité avec différents formats d''icônes","Intégration avec des frameworks de développement tels que React et Node.js"],"de":["Implementierung von benutzerdefinierten Icons","Verwendung von KI-Tools für die Erstellung von Icons","Benutzerdefiniertes Icon-Verzeichnis","Kompatibilität mit verschiedenen Icon-Formaten","Integration mit Entwicklungsframeworks wie React und Node.js"],"pt":["Coleção de ícones prontos para uso","Fácil integração com projetos de design","Suporte a múltiplos formatos de arquivo","Atualizações regulares com novos ícones","Documentação detalhada para uso fácil"],"ru":["Коллекция готовых иконок для использования","Легкая интеграция с проектами дизайна","Поддержка нескольких форматов файлов","Регулярные обновления с новыми иконками","Детальная документация для легкого использования"],"ar":["مجموعة من الأيقونات الجاهزة للاستخدام","التكامل السهل مع مشاريع التصميم","دعم صيغ الملفات المتعددة","التحديثات المنتظمة بالأيقونات الجديدة","توثيق مفصل للاستخدام السهل"]},"keywords":{"zh":["如何使用图标库","什么是图标库","图标库替代品","图标库与其他工具的比较","图标库安装","图标库设置指南","React图标库","Python图标库","Node.js图标库"],"ja":["アイコンライブラリを使用する方法","アイコンライブラリとは","アイコンライブラリの代替","アイコンライブラリと他のツールの比較","アイコンライブラリのインストール","アイコンライブラリの設定ガイド","Reactアイコンライブラリ","Pythonアイコンライブラリ","Node.jsアイコンライブラリ"],"ko":["아이콘 라이브러리를 사용하는 방법","아이콘 라이브러리란","아이콘 라이브러리 대체","아이콘 라이브러리와 다른 도구의 비교","아이콘 라이브러리 설치","아이콘 라이브러리 설정 가이드","React 아이콘 라이브러리","Python 아이콘 라이브러리","Node.js 아이콘 라이브러리"],"es":["herramientas de ia para iconos","biblioteca de iconos personalizada","creación de iconos con ia","iconos personalizados para react","guía de instalación de iconos","alternativas a font awesome","icomoon vs font awesome"],"fr":["outils d''ia pour icônes","catalogue d''icônes personnalisé","création d''icônes avec ia","icônes personnalisés pour react","guide d''installation d''icônes","alternatives à font awesome","icomoon vs font awesome"],"de":["ki-tools für icons","benutzerdefinierte icon-bibliothek","erstellung von icons mit ki","benutzerdefinierte icons für react","anleitung zur installation von icons","alternativen zu font awesome","icomoon vs font awesome"],"pt":["como usar biblioteca de ícones","o que é biblioteca de ícones","biblioteca de ícones alternativa","biblioteca de ícones vs font awesome","instalar biblioteca de ícones","guia de configuração da biblioteca de ícones"],"ru":["как использовать библиотеку иконок","что такое библиотека иконок","альтернативная библиотека иконок","библиотека иконок vs font awesome","установка библиотеки иконок","руководство по настройке библиотеки иконок"],"ar":["كيفية استخدام مكتبة الأيقونات","ما هي مكتبة الأيقونات","بديل مكتبة الأيقونات","مكتبة الأيقونات مقابل فونت أوسم","تثبيت مكتبة الأيقونات","دليل إعداد مكتبة الأيقونات"]}},"owner":"cesaroeduardo","repo":"icon-library-visualization","repoPath":"cesaroeduardo/icon-library-visualization","stars":0,"forks":0,"updatedAt":"2026-03-02T07:37:53.645Z","topics":[],"category":"community","skillMd":{"name":"icon-library","description":"|","bodyPreview":"# Icon Library Skill\n\nProvides icons from the Azion Icon Library with context-aware output formats.\n\n## CRITICAL: Icon Font Availability\n\n### `ai-*` Azion Icons - ALWAYS USE SVG\n\nThe Azion icon font (`azionicons.woff2`) is **NOT loaded by default** in most contexts.\n\n**`<i class=\"ai ai-application\"></i>` will NOT render** unless the target project explicitly loads:\n- The `azionicons.woff2` font file\n- The CSS with `@font-face` and class definitions\n\n**For `ai-*` icons: ALWAYS provide inline SVG*","body":"# Icon Library Skill\n\nProvides icons from the Azion Icon Library with context-aware output formats.\n\n## CRITICAL: Icon Font Availability\n\n### `ai-*` Azion Icons - ALWAYS USE SVG\n\nThe Azion icon font (`azionicons.woff2`) is **NOT loaded by default** in most contexts.\n\n**`<i class=\"ai ai-application\"></i>` will NOT render** unless the target project explicitly loads:\n- The `azionicons.woff2` font file\n- The CSS with `@font-face` and class definitions\n\n**For `ai-*` icons: ALWAYS provide inline SVG** from `assets/svg/`.\n\n### `pi-*` PrimeIcons - Font classes usually work\n\nPrimeIcons are loaded automatically in projects using PrimeVue/PrimeReact.\n\n**`<i class=\"pi pi-home\"></i>` works** in most Vue/React projects with PrimeVue.\n\n## Icon Prefixes\n\n- **`ai-*`** - Azion-specific icons → **USE SVG** (font rarely available)\n- **`pi-*`** - PrimeIcons → Font class OK if PrimeVue is loaded, otherwise use SVG\n\n## Integration Approaches\n\n### 1. SVG Approach (Recommended - Always Works)\n\n**Use for:** ALL `ai-*` icons, and `pi-*` when unsure about font availability.\n\n- Read SVG from `assets/svg/{icon-name}.svg`\n- Copy/paste inline or reference as image\n- Works anywhere, no setup required\n- Supports multi-color icons\n\n### 2. Icon Font Approach (Limited Use)\n\n**Use ONLY for `pi-*` icons** in projects with PrimeVue/PrimeReact.\n\n**NEVER use `<i class=\"ai ai-*\">` unless you''ve verified the Azion font is loaded.**\n\n## Setting Up Azion Icon Font (Optional)\n\nIf you want `<i class=\"ai ai-*\">` to work in your project, you need:\n\n### Step 1: Copy font file\nCopy `azionicons.woff2` to your project''s assets folder.\n\n### Step 2: Create CSS file (`azionicons.css`)\n```css\n@font-face {\n  font-family: ''azionicons'';\n  src: url(''./azionicons.woff2'') format(''woff2'');\n}\n\n.ai {\n  font-family: ''azionicons'';\n  speak: none;\n  font-style: normal;\n  font-weight: normal;\n  font-variant: normal;\n  text-transform: none;\n  line-height: 1;\n  display: inline-block;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n/* Icon class definitions */\n.ai.ai-application::before { content: ''\\ea08''; }\n.ai.ai-firewall::before { content: ''\\ea11''; }\n.ai.ai-functions::before { content: ''\\ea22''; }\n.ai.ai-storage::before { content: ''\\ea28''; }\n.ai.ai-sql::before { content: ''\\ea29''; }\n.ai.ai-kv::before { content: ''\\ea30''; }\n.ai.ai-orchestrator::before { content: ''\\ea31''; }\n.ai.ai-certificate-manager::before { content: ''\\ea24''; }\n.ai.ai-network-shield::before { content: ''\\ea25''; }\n/* See icons.scss for complete list */\n```\n\n### Step 3: Import CSS globally\n```js\n// In main.js, App.vue, or _app.tsx\nimport ''./assets/azionicons.css'';\n```\n\n### Step 4: Use icon classes\n```html\n<i class=\"ai ai-application\"></i>\n```\n\n**Note:** The complete `icons.scss` with all icon mappings is available in the icon-library-visualization repository.\n\n## Finding Icons\n\nSearch `references/icons-catalog.json` by keyword:\n```\ngrep -i \"security\\|firewall\" references/icons-catalog.json\n```\n\nEach icon has: `name`, `icon` (class), and `keywords`.\n\n## Output Formats by Context\n\n### 1. Website/App (HTML/Vue/React)\n\n**If project has icon font setup:**\n```html\n<i class=\"ai ai-application\"></i>\n```\n\n**If no icon font (use SVG - recommended):**\n```html\n<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\">\n  <path d=\"...\" fill=\"currentColor\"/>\n</svg>\n```\n\nRead the SVG content from `assets/svg/{icon-name}.svg`.\n\n### 2. Content Marketing (Blog/Social/Email)\n\nAlways use inline SVG (no dependencies):\n```html\n<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\">\n  <path d=\"...\" fill=\"#F3652B\"/>\n</svg>\n```\n\nTo customize color, replace `fill` attribute value.\n\n### 3. Documentation (Markdown/MDX)\n\n**Markdown (image reference):**\n```markdown\n![Application Icon](./path/to/ai-application.svg)\n```\n\n**MDX (inline SVG):**\n```mdx\n<svg width=\"24\" height=\"24\">...</svg>\n```\n\n### 4. CMS/Struct Fields\n\nProvide just the icon name:\n```\nai-application\n```\n\n## Decision Logic\n\n| Icon Type | Context | Output |\n|-----------|---------|--------|\n| `ai-*` | ANY context | **Inline SVG** from `assets/svg/` |\n| `pi-*` | PrimeVue project | `<i class=\"pi pi-{name}\"></i>` |\n| `pi-*` | Other contexts | Inline SVG from `assets/svg/` |\n| Any | CMS/Struct field | Icon name only (e.g., `ai-firewall`) |\n| Any | Markdown docs | SVG image reference or inline |\n\n## Common Icons Quick Reference\n\n### Azion Products\n\n**Note:** Product names have been updated. Use the new names in content:\n\n| Icon Class | Product Name |\n|------------|-------------|\n| `ai-application` | Applications |\n| `ai-firewall` | Firewall |\n| `ai-functions` | Functions |\n| `ai-storage` | Object Storage |\n| `ai-sql` | SQL Database |\n| `ai-kv` | KV Store |\n| `ai-certificate-manager` | Certificate Manager |\n| `ai-orchestrator` | Orchestrator |\n| `ai-network-shield` | Network Shield |\n| `ai-waf-rules` | WAF Rules |\n\n### Frameworks\n- `ai-react` - React\n- `ai-vue` - Vue\n- `ai-nextjs` - Next.js\n- `ai-astro` - Astro\n- `ai-terraform` - Terraform\n\n### UI Elements (pi-*)\n- `pi-home` - Home\n- `pi-search` - Search\n- `pi-user` - User\n- `pi-cog` - Settings\n- `pi-check` - Check/Success\n- `pi-times` - Close/Error\n- `pi-plus` - Add\n- `pi-trash` - Delete\n\n## Retrieving SVG Content\n\nTo get the full SVG markup, read from `assets/svg/{icon-name}.svg`.\n\nExample workflow:\n1. User asks for \"firewall icon for blog post\"\n2. Search catalog: find `ai-firewall`\n3. Read `assets/svg/ai-firewall.svg`\n4. Return inline SVG with appropriate color\n\n## Naming Guidelines\n\n**Important:** Follow these naming conventions in all content:\n\n- Use **AI** (not IA) as the abbreviation for Artificial Intelligence\n- Use **distributed architecture** instead of \"at the edge\" or \"on the edge\"\n- Use the updated product names shown in the Azion Products table above\n\n### Product Name Mapping (Legacy → Current)\n\n| Legacy Name | Current Name |\n|-------------|-------------|\n| Edge Functions | Functions |\n| Edge Cache / Tiered Cache | Cache |\n| Network Layer Protection | Network Shield |\n| Edge SQL | SQL Database |\n| Edge KV | KV Store |\n| Edge Storage | Object Storage |\n| Edge Application | Applications |\n| Edge Orchestrator | Orchestrator |\n| Digital Certificates | Certificate Manager |\n| Edge Firewall | Firewall |\n"},"lastSynced":"2026-03-02T09:29:13.696Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing context-aware icon output formats in SVG","zh":"非常适合需要上下文感知图标输出格式的SVG的UI专注代理","ja":"UIに焦点を当てたエージェントがコンテキスト感覚のアイコン出力形式をSVGで必要とする場合に最適","ko":"UI에 중점을 둔 에이전트가 SVG에서 컨텍스트 인식 아이コン 출력 형식을 필요로 하는 경우에 적합","es":"Perfecto para Agentes centrados en la interfaz de usuario que necesitan formatos de salida de iconos con conciencia de contexto en SVG","fr":"Parfait pour les agents axés sur l''interface utilisateur nécessitant des formats de sortie d''icônes sensibles au contexte en SVG","de":"Perfekt für benutzeroberflächenorientierte Agenten, die kontextbewusste Icon-Ausgabformate in SVG benötigen","pt":"Perfeito para Agentes focados em UI que precisam de formatos de saída de ícones sensíveis ao contexto em SVG","ru":"Идеально подходит для агентов, ориентированных на UI, которым необходимы форматы вывода иконок, осведомленные о контексте, в SVG","ar":"مثالي للوكلاء الذين يركزون على واجهة المستخدم وهم بحاجة إلى تنسيقات مخرجات الأيقونات التي تدرك السياق في SVG"},"recommendation":{"en":"Empowers agents to provide icons from the Azion Icon Library with inline SVG output, ensuring compatibility across various contexts by bypassing the need for explicit font loading, utilizing @font-face and class definitions for seamless integration with protocols like HTML and CSS","zh":"赋予代理从Azion图标库提供图标的能力，具有内联SVG输出，确保在绕过显式字体加载的同时，通过@font-face和类定义与HTML和CSS等协议实现无缝集成","ja":"Azionアイコンライブラリからアイコンを提供するエージェントをエンパワーメントし、インラインSVG出力を使用して、明示的なフォントロードの必要性を回避し、@font-faceとクラス定義を使用してHTMLおよびCSSなどのプロトコルとシームレスに統合","ko":"에이전트가 Azion 아이콘 라이브러리에서 아이콘을 제공할 수 있도록 하고, 인라인 SVG 출력을 사용하여 명시적인 글꼴 로딩의 필요성을 피함으로써 HTML 및 CSS 등과 같은 프로토콜과 무.platform 통합을 위한 @font-face 및 클래스 정의를 사용","es":"Habilita a los agentes a proporcionar iconos de la Biblioteca de Iconos de Azion con salida SVG en línea, garantizando la compatibilidad en varios contextos al omitir la necesidad de carga de fuente explícita, utilizando @font-face y definiciones de clase para una integración sin problemas con protocolos como HTML y CSS","fr":"Permet aux agents de fournir des icônes de la Bibliothèque d''icônes Azion avec une sortie SVG en ligne, garantissant la compatibilité dans différents contextes en contournant la nécessité d''un chargement de police explicite, en utilisant @font-face et des définitions de classe pour une intégration transparente avec des protocoles tels que HTML et CSS","de":"Ermächtigt Agenten, Icons aus der Azion-Icon-Bibliothek mit Inline-SVG-Ausgabe bereitzustellen, wodurch die Kompatibilität in verschiedenen Kontexten durch Umgehung der Notwendigkeit einer expliziten Schriftladung sichergestellt wird, unter Verwendung von @font-face und Klassendefinitionen für eine nahtlose Integration mit Protokollen wie HTML und CSS","pt":"Habilita os agentes a fornecer ícones da Biblioteca de Ícones Azion com saída SVG inline, garantindo compatibilidade em vários contextos, contornando a necessidade de carregamento explícito de fontes, utilizando @font-face e definições de classe para integração transparente com protocolos como HTML e CSS","ru":"Наделяет агентов возможностью предоставлять иконки из Библиотеки иконок Azion с выводом SVG встроенным, обеспечивая совместимость в различных контекстах, обходя необходимость явной загрузки шрифтов, используя @font-face и определения классов для бесшовной интеграции с протоколами, такими как HTML и CSS","ar":"تمكّن الوكلاء من توفير الأيقونات من مكتبة أيقونات Azion مع مخرجات SVG متضمنة، مما يضمن التوافق عبر سياقات متعددة عن طريق تجاوز الحاجة إلى تحميل الخطوط явًا، واستخدام @font-face والتعريفات الدراسية لالتقاط متوافق مع بروتوكولات مثل HTML وCSS"},"useCases":{"en":["Generating icons for web applications using SVG","Providing context-aware icon outputs for UI design","Ensuring cross-context compatibility of Azion icons"],"zh":["使用SVG为Web应用程序生成图标","为UI设计提供上下文感知图标输出","确保Azion图标在不同上下文中的兼容性"],"ja":["SVGを使用してWebアプリケーションのアイコンを生成する","UIデザインのためのコンテキスト感覚アイコン出力を提供する","Azionアイコンのコンテキスト間の互換性を確保する"],"ko":["SVG를 사용하여 웹 애플리케이션의 아이콘을 생성","UI 디자인을 위한 컨텍스트 인식 아이콘 출력을 제공","Azion 아이콘의 컨텍스트 간 호환성을 보장"],"es":["Generación de iconos para aplicaciones web utilizando SVG","Proporcionar salidas de iconos con conciencia de contexto para el diseño de la interfaz de usuario","Garantizar la compatibilidad entre contextos de los iconos de Azion"],"fr":["Génération d''icônes pour les applications web à l''aide de SVG","Fournir des sorties d''icônes sensibles au contexte pour la conception d''interface utilisateur","Assurer la compatibilité entre les contextes des icônes Azion"],"de":["Generierung von Icons für Webanwendungen unter Verwendung von SVG","Bereitstellung von kontextbewussten Icon-Ausgaben für das Benutzeroberflächendesign","Sicherstellung der Kompatibilität zwischen den Kontexten der Azion-Icons"],"pt":["Geração de ícones para aplicações web usando SVG","Fornecimento de saídas de ícones sensíveis ao contexto para design de UI","Garantia de compatibilidade transversal de ícones Azion"],"ru":["Генерация иконок для веб-приложений с использованием SVG","Предоставление контекстно-зависимых выходных данных иконок для дизайна UI","Обеспечение транс-контекстной совместимости иконок Azion"],"ar":["توليد الأيقونات للتطبيقات الوب باستخدام SVG","توفير مخرجات الأيقونات التي تدرك السياق لتصميم واجهة المستخدم","ضمان التوافق عبر السياق للأيقونات Azion"]},"limitations":{"en":["Requires inline SVG for ai-* icons","Azion icon font (azionicons.woff2) not loaded by default","Needs explicit loading of font file and CSS for class definitions"],"zh":["需要内联SVG用于ai-*图标","Azion图标字体（azionicons.woff2）默认未加载","需要显式加载字体文件和CSS用于类定义"],"ja":["ai-*アイコンにインラインSVGが必要","Azionアイコンフォント（azionicons.woff2）がデフォルトでロードされていない","クラス定義のためのフォントファイルとCSSの明示的なロードが必要"],"ko":["ai-* 아이콘에 대한 인라인 SVG가 필요","Azion 아이콘 글꼴(azionicons.woff2)이 기본적으로 로드되지 않음","클래스 정의를 위한 글꼴 파일 및 CSS의 명시적 로딩이 필요"],"es":["Requiere SVG en línea para los iconos ai-*","La fuente de iconos de Azion (azionicons.woff2) no se carga de forma predeterminada","Necesita una carga explícita del archivo de fuente y CSS para las definiciones de clase"],"fr":["Nécessite un SVG en ligne pour les icônes ai-*","La police d''icônes Azion (azionicons.woff2) n''est pas chargée par défaut","Nécessite un chargement explicite du fichier de police et du CSS pour les définitions de classe"],"de":["Benötigt Inline-SVG für ai-*-Icons","Die Azion-Icon-Schrift (azionicons.woff2) wird nicht standardmäßig geladen","Benötigt eine explizite Ladevorgang der Schriftdatei und CSS für Klassendefinitionen"],"pt":["Requer SVG inline para ícones ai-*","A fonte de ícones Azion (azionicons.woff2) não é carregada por padrão","Necessita de carregamento explícito do arquivo de fonte e CSS para definições de classe"],"ru":["Требует встроенного SVG для иконок ai-*","Шрифт иконок Azion (azionicons.woff2) не загружается по умолчанию","Требует явной загрузки файла шрифта и CSS для определений классов"],"ar":["يتطلب SVG متضمّنًا لأيقونات ai-*","خط الأيقونات Azion (azionicons.woff2) غير محمل افتراضيًا","يحتاج إلى تحميل صريح لملف الخط والسي إس إس لتعريفات الفصل"]},"version":3},"contentHash":"6958ead51703cb1427d06b4423652b7bdc0b78e214bc0c76fa27054da944d5df","qualityScore":46}');
