INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aram-devdocs/GoudEngine/integration-testing', 'integration-testing', 'aram-devdocs', 'GoudEngine', 'community', 'integration-testing aram-devdocs GoudEngine community 本AI智能代理技能使用Rust构建OpenGL游戏引擎，并提供C/C# SDK用于集成测试 このAIエージェントスキルは、RustでOpenGLゲームエンジンを構築し、C/C# SDKを使用した統合テストを提供します 이 AI 에이전트 스킬은 러스트로 OpenGL 게임 엔진을 구축하고, C/C# SDK를 사용한 통합 테스트를 제공합니다 El motor de juego OpenGL construido con Rust y SDK compilado para C/C# permite una integración perfecta para desarrolladores Le moteur de jeu OpenGL construit avec Rust et SDK compilé pour C/C# permet une intégration parfaite pour les développeurs Der OpenGL-Spiel-Engine, der mit Rust und SDK für C/C# erstellt wurde, ermöglicht eine perfekte Integration für Entwickler O motor de jogo OpenGL em Rust oferece recursos avançados de integração de testes para garantir a estabilidade do jogo. Игровой движок на Rust с интеграционным тестированием обеспечивает стабильность и качество игры. محرك الألعاب OpenGL في الرست يقدم ميزات متقدمة لدمج الاختبار لضمان استقرار اللعبة. OpenGL Game Engine built using Rust with SDK compiled for C/C# 如何使用Rust构建OpenGL游戏引擎 什么是集成测试 AI智能代理的集成测试 Rust游戏引擎 C/C# SDK OpenGL游戏引擎 AI智能代理工具 OpenGL Game Engine built using Rust with SDK compiled for C/C#');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('monkey1sai/openai-cli/caching-cdn-strategy-planner', 'community', 'monkey1sai', 'openai-cli', 'monkey1sai/openai-cli', 'caching-cdn-strategy-planner', 1, 0, 46, '2026-02-18T16:04:17Z', '2026-02-26T08:44:34.229Z', '84f4615c15dce2978cbe598b6228dabc8989898e7e02193dfbca1477000c8a42', '{"id":"monkey1sai/openai-cli/caching-cdn-strategy-planner","name":"caching-cdn-strategy-planner","description":{"zh":"缓存CDN策略规划工具，使用Gemini CLI、Codex CLI和Claude CLI实现快速部署","ja":"キャッシングCDN戦略計画ツール、Gemini CLI、Codex CLI、Claude CLIを使用して迅速にデプロイ","ko":"캐싱 CDN 전략 계획 도구, Gemini CLI, Codex CLI 및 Claude CLI를 사용하여 빠르게 배포","es":"El planificador de estrategias de caché y CDN utiliza gemini cli, codex cli y claude cli para optimizar el rendimiento en entornos de desarrollo en Windows","fr":"Le planificateur de stratégies de cache et de CDN utilise gemini cli, codex cli et claude cli pour optimiser les performances dans les environnements de développement Windows","de":"Der Strategieplaner für Caching und CDN verwendet gemini cli, codex cli und claude cli, um die Leistung in Windows-Entwicklungsumgebungen zu optimieren","pt":"O planejador de estratégia de cache e CDN é uma ferramenta de agente de IA que ajuda a otimizar o desempenho da aplicação. Com ele, você pode configurar o Gemini CLI, Codex CLI e Claude CLI para melhorar a experiência do usuário","ru":"Планировщик стратегии кэширования и CDN - это инструмент ИИ Агентов, который помогает оптимизировать производительность приложения. С его помощью вы можете настроить Gemini CLI, Codex CLI и Claude CLI для улучшения пользовательского опыта","ar":"مخطط استراتيجية ذاكرة التخزين المؤقت وشبكة التوزيع هو أداة وكلاء الذكاء الاصطناعي التي تساعد على تحسين أداء التطبيق. باستخدامها، يمكنك تكوين Gemini CLI و Codex CLI و Claude CLI لتحسين تجربة المستخدم","en":"gemini cli, codex cli, claude cli 個人環境設定(windo