INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vectorize-io/hindsight/hindsight-docs', 'hindsight-docs', 'vectorize-io', 'hindsight', 'community', 'hindsight-docs vectorize-io hindsight community hindsight-docs是AI智能代理的学习内存，用于开发高效的AI应用 hindsight-docsはAIエージェントの学習型メモリで、開発効率の高いAIアプリケーションを実現 hindsight-docs는 AI 에이전트의 학습형 메모리로 개발 효율성을 높이는 데 사용 Hindsight es una memoria de agente que aprende y se adapta. Aprende a utilizar esta herramienta para mejorar tus proyectos Hindsight est une mémoire d''agent qui apprend et s''adapte. Apprenez à utiliser cet outil pour améliorer vos projets Hindsight ist ein Gedächtnis des Agents, das lernt und sich anpasst. Lernen Sie, dieses Tool zu nutzen, um Ihre Projekte zu verbessern Hindsight-docs é uma ferramenta de IA que permite que agentes aprendam e melhorem sua memória. Aprenda mais sobre como usar essa tecnologia. Hindsight-docs - это инструмент ИИ, который позволяет агентам учиться и улучшать свою память. Узнайте больше о том, как использовать эту технологию. Hindsight-docs هي أداة ذكاء اصطناعي تتيح للوكلاء التعلم وتحسين ذاكرتهم. تعلم المزيد حول كيفية استخدام هذه التكنولوجيا. Hindsight: Agent Memory That Learns AI智能代理 hindsight-docs教程 AI工具安装 React与AI集成 Python AI开发 CLI工具使用 AI应用开发 hindsight-docs alternative hindsight-docs vs 其他AI工具 Hindsight: Agent Memory That Learns');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('superdoc-dev/superdoc/editing-docx', 'community', 'superdoc-dev', 'superdoc', 'superdoc-dev/superdoc', 'editing-docx', 0, 0, 46, '2026-03-04T13:07:01.673Z', '2026-03-04T13:23:17.356Z', '064d2f803fe586f5da792b8424fdf9c0bb0bc0f131bb6fb7d90653e3b756b320', '{"id":"superdoc-dev/superdoc/editing-docx","name":"editing-docx","description":{"zh":"SuperDoc是现代文档编辑工具，使用AI智能技术编辑DOCX文档","ja":"SuperDocはモダンドキュメント編集ツールで、AIエージェントを使用してDOCX文書を編集します","ko":"SuperDoc는现代文档편집도구로 AI 에이전트를 사용하여 DOCX 문서를 편집합니다","es":"SuperDoc es una herramienta de edición de documentos moderna que permite a los desarrolladores editar archivos DOCX de manera eficiente","fr":"SuperDoc est un outil d''édition de documents moderne qui permet aux développeurs d''éditer des fichiers DOCX de manière efficace","de":"SuperDoc ist ein modernes Dokumentenbearbeitungstool, das es Entwicklern ermöglicht, DOCX-Dateien effizient zu bearbeiten","pt":"O SuperDoc é uma ferramenta de edição de documentos moderna, permitindo que desenvolvedores criem e editem arquivos DOCX de forma eficiente","ru":"SuperDoc - современный редактор документов, позволяющий разработчикам создавать и редактировать файлы DOCX эффективно","ar":"سوبر دوك هو أداة تحرير مستندات حديثة، تمكن المطورين من إنشاء وتحرير ملفات DOCX بفعالية","en":"🦋️ SuperDoc - modern document editing"},"seo":{"title":{"zh":"编辑DOCX文档 - AI智能文档编辑工具","ja":"DOCX編集 - AIエージェントによるモダンドキュメント編集","ko":"DOCX 편집 - AI 에이전트를 사용한 문서 편집","es":"Herramientas de edición de documentos DOCX con Agentes de IA","fr":"Outils d''édition de documents DOCX avec les Agents IA","de":"DOCX-Dokumentenbearbeitung mit KI-Agents","pt":"Ferramentas de Edição de Documentos - SuperDoc","ru":"ИИ Агенты для Редактирования DOCX - SuperDoc","ar":"أدوات تحرير المستندات - سوبر دوك","en":"editing-docx"},"description":{"zh":"SuperDoc是现代文档编辑工具，使用AI智能技术编辑DOCX文档","ja":"SuperDocはモダンドキュメント編集ツールで、AIエージェントを使用してDOCX文書を編集します","ko":"SuperDoc는现代文档편집도구로 AI 에이전트를 사용하여 DOCX 문서를 편집합니다","es":"SuperDoc es una herramienta de edición de documentos moderna que permite a los desarrolladores editar archivos DOCX de manera eficiente","fr":"SuperDoc est un outil d''édition de documents moderne qui permet aux développeurs d''éditer des fichiers DOCX de manière efficace","de":"SuperDoc ist ein modernes Dokumentenbearbeitungstool, das es Entwicklern ermöglicht, DOCX-Dateien effizient zu bearbeiten","pt":"O SuperDoc é uma ferramenta de edição de documentos moderna, permitindo que desenvolvedores criem e editem arquivos DOCX de forma eficiente","ru":"SuperDoc - современный редактор документов, позволяющий разработчикам создавать и редактировать файлы DOCX эффективно","ar":"سوبر دوك هو أداة تحرير مستندات حديثة، تمكن المطورين من إنشاء وتحرير ملفات DOCX بفعالية","en":"🦋️ SuperDoc - modern document editing"},"definition":{"en":"🦋️ SuperDoc - modern document editing"},"features":{"zh":["支持DOCX文档编辑","使用AI智能技术","现代文档编辑工具","简单易用","高效编辑"],"ja":["DOCX文書編集対応","AIエージェントを使用","モダンドキュメント編集ツール","使いやすい","効率的な編集"],"ko":["DOCX 문서 편집 지원","AI 에이전트 사용","现代文档편집도구","쉬운 사용","효율적인 편집"],"es":["Edición de documentos DOCX","Funcionalidades de edición avanzadas","Integración con herramientas de desarrollo","Compatibilidad con múltiples plataformas","Seguridad y privacidad de los datos"],"fr":["Édition de documents DOCX","Fonctionnalités d''édition avancées","Intégration avec des outils de développement","Compatibilité avec plusieurs plateformes","Sécurité et confidentialité des données"],"de":["Bearbeitung von DOCX-Dokumenten","Erweiterte Bearbeitungsfunktionen","Integration mit Entwicklungstools","Kompatibilität mit mehreren Plattformen","Sicherheit und Datenschutz"],"pt":["Edição de arquivos DOCX","Criação de documentos personalizados","Compatibilidade com diversas plataformas","Integração com outras ferramentas de desenvolvimento","Suporte a múltiplos formatos de arquivo"],"ru":["Редактирование файлов DOCX","Создание персонализированных документов","Совместимость с различными платформами","Интеграция с другими инструментами разработки","Поддержка нескольких форматов файлов"],"ar":["تحرير ملفات DOCX","إنشاء مستندات مخصصة","التكامل مع منصات متعددة","دمج مع أدوات تطوير أخرى","دعم صيغ ملفات متعددة"]},"keywords":{"zh":["如何使用SuperDoc","什么是DOCX编辑","SuperDoc替代品","DOCX编辑工具","安装SuperDoc","SuperDoc设置指南","DOCX编辑软件"],"ja":["SuperDocの使い方","DOCX編集とは","SuperDocの代替","DOCX編集ツール","SuperDocのインストール","SuperDocの設定ガイド","DOCX編集ソフトウェア"],"ko":["SuperDoc 사용법","DOCX 편집이란","SuperDoc 대체품","DOCX 편집도구","SuperDoc 설치","SuperDoc 설정 가이드","DOCX 편집 소프트웨어"],"es":["herramientas de edición de documentos","agentes de IA para la edición de documentos","cómo usar SuperDoc","alternativas a SuperDoc","SuperDoc vs otros editores de documentos","instalación de SuperDoc","guía de configuración de SuperDoc"],"fr":["outils d''édition de documents","agents IA pour l''édition de documents","comment utiliser SuperDoc","alternatives à SuperDoc","SuperDoc vs autres éditeurs de documents","installation de SuperDoc","guide de configuration de SuperDoc"],"de":["Dokumentenbearbeitungstools","KI-Agents für die Dokumentenbearbeitung","wie man SuperDoc verwendet","Alternativen zu SuperDoc","SuperDoc vs andere Dokumentenbearbeitungstools","Installation von SuperDoc","Konfigurationsanleitung für SuperDoc"],"pt":["ferramentas de edição de documentos","como usar SuperDoc","o que é SuperDoc","SuperDoc vs Microsoft Word","instalar SuperDoc","guia de configuração do SuperDoc","desenvolvimento de documentos","edição de arquivos DOCX","ferramentas de desenvolvimento de documentos"],"ru":["инструменты редактирования документов","как использовать SuperDoc","что такое SuperDoc","SuperDoc vs Microsoft Word","установить SuperDoc","руководство по настройке SuperDoc","разработка документов","редактирование файлов DOCX","инструменты разработки документов"],"ar":["أدوات تحرير المستندات","كيفية استخدام سوبر دوك","ما هو سوبر دوك","سوبر دوك مقابل مايكروسوفت وورد","تثبيت سوبر دوك","دليل إعداد سوبر دوك","تطوير المستندات","تحرير ملفات DOCX","أدوات تطوير المستندات"]}},"owner":"superdoc-dev","repo":"superdoc","repoPath":"superdoc-dev/superdoc","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.673Z","topics":[],"category":"community","skillMd":{"name":"editing-docx","description":"Searches, replaces, and reads text in Word documents. Use when the user asks to edit, search, or extract text from .docx files.","bodyPreview":"# SuperDoc CLI\n\nEdit Word documents from the command line. Use instead of python-docx.\n\n## Commands\n\n| Command | Description |\n|---------|-------------|\n| `npx @superdoc-dev/cli@latest search <pattern> <files...>` | Find text across documents |\n| `npx @superdoc-dev/cli@latest replace-legacy <find> <to> <files...>` | Find and replace text |\n| `npx @superdoc-dev/cli@latest read <file>` | Extract plain text |\n\n## When to Use\n\nUse superdoc when the user asks to:\n- Search text in .docx files\n- Find a","body":"# SuperDoc CLI\n\nEdit Word documents from the command line. Use instead of python-docx.\n\n## Commands\n\n| Command | Description |\n|---------|-------------|\n| `npx @superdoc-dev/cli@latest search <pattern> <files...>` | Find text across documents |\n| `npx @superdoc-dev/cli@latest replace-legacy <find> <to> <files...>` | Find and replace text |\n| `npx @superdoc-dev/cli@latest read <file>` | Extract plain text |\n\n## When to Use\n\nUse superdoc when the user asks to:\n- Search text in .docx files\n- Find and replace text in Word documents\n- Extract text content from .docx files\n- Bulk edit multiple Word documents\n\n## Examples\n\n```bash\n# Search across documents\nnpx @superdoc-dev/cli@latest search \"indemnification\" ./contracts/*.docx\n\n# Find and replace\nnpx @superdoc-dev/cli@latest replace-legacy \"ACME Corp\" \"Globex Inc\" ./merger/*.docx\n\n# Extract text\nnpx @superdoc-dev/cli@latest read ./proposal.docx\n\n# JSON output for scripting\nnpx @superdoc-dev/cli@latest search \"Article 7\" ./**/*.docx --json\n```\n\n## Options\n\n- `--json` — Machine-readable output\n- `--help` — Show help\n"},"lastSynced":"2026-03-04T13:23:17.356Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing advanced .docx editing capabilities.","zh":"非常适合需要高级 .docx 编辑功能的文档分析代理。","ja":"ドキュメント分析エージェントが高度な .docx 編集機能を必要とする場合に最適です。","ko":"고급 .docx 편집 기능이 필요한 문서 분석 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Análisis de Documentos que necesitan capacidades de edición avanzadas de .docx.","fr":"Parfait pour les Agents d''Analyse de Documents ayant besoin de fonctionnalités de modification avancées de .docx.","de":"Perfekt für Dokumentenanalyse-Agenten, die erweiterte .docx-Bearbeitungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que precisam de capacidades de edição avançadas de .docx.","ru":"Идеально подходит для Агентов Анализа Документов, которым необходимы продвинутые возможности редактирования .docx.","ar":"مثالي لعمليات تحليل الوثائق التي تحتاج إلى إمكانيات تحرير متقدمة لملفات .docx."},"recommendation":{"en":"Empowers agents to search, replace, and extract text from Word documents using the SuperDoc CLI, leveraging commands like search, replace-legacy, and read for efficient document processing.","zh":"通过 SuperDoc CLI 启用代理搜索、替换和从 Word 文档中提取文本，利用 search、replace-legacy 和 read 命令实现高效的文档处理。","ja":"SuperDoc CLI を使用してエージェントが Word 文書からテキストを検索、置換、抽出できるようにし、search、replace-legacy、read などのコマンドを使用して効率的な文書処理を行えるようにします。","ko":"SuperDoc CLI를 사용하여 에이전트가 워드 문서에서 텍스트를 검색,替换,추출 할 수있게 하며 search, replace-legacy, read 등의 명령을 사용하여 효율적인 문서 처리를 가능하게 합니다.","es":"Habilita a los agentes a buscar, reemplazar y extraer texto de documentos de Word utilizando la CLI de SuperDoc, aprovechando comandos como search, replace-legacy y read para un procesamiento de documentos eficiente.","fr":"Permet aux agents de rechercher, remplacer et extraire du texte à partir de documents Word en utilisant la CLI SuperDoc, en exploitant des commandes comme search, replace-legacy et read pour un traitement de documents efficace.","de":"Ermächtigt die Agenten, mit der SuperDoc-CLI zu suchen, zu ersetzen und Text aus Word-Dokumenten zu extrahieren, indem Befehle wie search, replace-legacy und read für ein effizientes Dokumentenverarbeitung genutzt werden.","pt":"Habilita os agentes a buscar, substituir e extrair texto de documentos do Word usando o SuperDoc CLI, aproveitando comandos como search, replace-legacy e read para processamento eficiente de documentos.","ru":"Наделяет агентов возможностью искать, заменять и извлекать текст из документов Word с помощью SuperDoc CLI, используя команды như search, replace-legacy и read для эффективной обработки документов.","ar":"تمكن الوكلاء من البحث والاستبدال والاستخراج النص من مستندات الوورد باستخدام SuperDoc CLI، مستفيدا من أوامر مثل search و replace-legacy و read من أجل معالجة المستندات بشكل فعال."},"useCases":{"en":["Searching text across multiple .docx files","Replacing legacy text in documents","Extracting plain text from .docx files for further analysis"],"zh":["跨多个 .docx 文件搜索文本","在文档中替换旧文本","从 .docx 文件中提取纯文本以进行进一步分析"],"ja":["複数の .docx ファイル内のテキストを検索する","文書内のレガシーテキストを置換する",".docx ファイルからプレーンテキストを抽出してさらに分析する"],"ko":["여러个 .docx 파일에서 텍스트를 검색한다","문서에서 레거시 텍스트를 대체한다",".docx 파일에서 평문 텍스트를 추출하여 추가 분석을 수행한다"],"es":["Buscar texto en varios archivos .docx","Reemplazar texto heredado en documentos","Extraer texto plano de archivos .docx para un análisis posterior"],"fr":["Rechercher du texte dans plusieurs fichiers .docx","Remplacer du texte hérité dans les documents","Extraire du texte brut à partir de fichiers .docx pour une analyse ultérieure"],"de":["Text in mehreren .docx-Dateien suchen","Veralteten Text in Dokumenten ersetzen","Klartext aus .docx-Dateien extrahieren für eine weitere Analyse"],"pt":["Pesquisar texto em vários arquivos .docx","Substituir texto legado em documentos","Extrair texto simples de arquivos .docx para análise adicional"],"ru":["Поиск текста в нескольких файлах .docx","Замена устаревшего текста в документах","Извлечение простого текста из файлов .docx для дальнейшего анализа"],"ar":["البحث عن النص عبر عدة ملفات .docx","استبدال النص التراثي في المستندات","استخراج النص العادي من ملفات .docx لتحليل إضافي"]},"limitations":{"en":["Requires Node.js environment for npx commands","Limited to .docx file format"],"zh":["需要 Node.js 环境来运行 npx 命令","仅限 .docx 文件格式"],"ja":["npx コマンドを実行するには Node.js 環境が必要",".docx ファイル形式のみに限定される"],"ko":["npx 명령을 실행하려면 Node.js 환경이 필요하다",".docx 파일 형식만으로 제한된다"],"es":["Requiere un entorno de Node.js para comandos npx","Limitado al formato de archivo .docx"],"fr":["Nécessite un environnement Node.js pour les commandes npx","Limité au format de fichier .docx"],"de":["Benötigt eine Node.js-Umgebung für npx-Befehle","Begrenzt auf das Dateiformat .docx"],"pt":["Requer ambiente Node.js para comandos npx","Limitado ao formato de arquivo .docx"],"ru":["Требуется среда Node.js для команд npx","Ограничен форматом файла .docx"],"ar":["يتطلب بيئة Node.js للأوامر npx","محدود بنسيق ملف .docx"]},"version":3},"contentHash":"064d2f803fe586f5da792b8424fdf9c0bb0bc0f131bb6fb7d90653e3b756b320","qualityScore":46}');
