INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('superdoc-dev/superdoc/editing-docx', 'editing-docx', 'superdoc-dev', 'superdoc', 'community', 'editing-docx superdoc-dev superdoc community SuperDoc是现代文档编辑工具，使用AI智能技术编辑DOCX文档 SuperDocはモダンドキュメント編集ツールで、AIエージェントを使用してDOCX文書を編集します SuperDoc는现代文档편집도구로 AI 에이전트를 사용하여 DOCX 문서를 편집합니다 SuperDoc es una herramienta de edición de documentos moderna que permite a los desarrolladores editar archivos DOCX de manera eficiente SuperDoc est un outil d''édition de documents moderne qui permet aux développeurs d''éditer des fichiers DOCX de manière efficace SuperDoc ist ein modernes Dokumentenbearbeitungstool, das es Entwicklern ermöglicht, DOCX-Dateien effizient zu bearbeiten O SuperDoc é uma ferramenta de edição de documentos moderna, permitindo que desenvolvedores criem e editem arquivos DOCX de forma eficiente SuperDoc - современный редактор документов, позволяющий разработчикам создавать и редактировать файлы DOCX эффективно سوبر دوك هو أداة تحرير مستندات حديثة، تمكن المطورين من إنشاء وتحرير ملفات DOCX بفعالية 🦋️ SuperDoc - modern document editing 如何使用SuperDoc 什么是DOCX编辑 SuperDoc替代品 DOCX编辑工具 安装SuperDoc SuperDoc设置指南 DOCX编辑软件 🦋️ SuperDoc - modern document editing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jvidalv/100cims/api', 'community', 'jvidalv', '100cims', 'jvidalv/100cims', 'api', 0, 0, 46, '2026-03-04T13:07:01.680Z', '2026-03-04T13:24:29.781Z', 'f319902131b628a0730dc935ed7c13dfd26368eea6db96797b3c3df6df534878', '{"id":"jvidalv/100cims/api","name":"api","description":{"zh":"使用AI智能工具构建React Native山峰追踪应用，加入徒步挑战，追踪您的山峰登顶记录","ja":"AIエージェントを使用してReact Nativeの山登り追跡アプリを作成し、ハイキングチャレンジに参加、山頂到達記録を追跡","ko":"AI 에이전트를 사용하여 리액트 네이티브 산 정상 추적 애플리케이션을 구축하고 하이킹 챌린지에 참여하여 산 정상 등정 기록을追跡","es":"La API para aplicaciones móviles React Native te permite trackear tus cumbres y unirte a desafíos de senderismo de manera eficiente.","fr":"L''outil API pour applications mobiles React Native vous permet de suivre vos sommets et de rejoindre des défis de randonnée de manière efficace.","de":"Das API-Tool für React Native Mobile Apps ermöglicht es Ihnen, Ihre Berggipfel zu tracken und sich Herausforderungen im Wandern anzuschließen, effizient und einfach.","pt":"A API é uma ferramenta poderosa para desenvolvedores que desejam criar aplicativos móveis de rastreamento de montanhas e desafios de caminhada com React Native","ru":"ИИ Агенты и API - это мощный инструмент для разработчиков, которые хотят создать мобильные приложения для отслеживания горных вершин и походных challengов с помощью React Native","ar":"أدوات الذكاء الاصطناعي و API هي أداة قوية لمطوري التطبيقات الذين يرغبون في إنشاء تطبيقات موبايل لتعقب جبال والتحديات المتنقلة باستخدام React Native","en":"React Native mobile app. Track your mountain summits and join hiking challenges"},"seo":{"title":{"zh":"AI智能工具：React Native山峰追踪API","ja":"AIエージェント：React Nativeで山登りチャレンジを追跡する","ko":"AI 에이전트: 리액트 네이티브 산 정상 추적 API","es":"Herramientas de API para aplicaciones móviles React Native","fr":"Outils API pour applications mobiles React Native","de":"API-Tools für React Native Mobile Apps",