INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DW225/ree-board/signal-state-management', 'signal-state-management', 'DW225', 'ree-board', 'community', 'signal-state-management DW225 ree-board community 信号状态管理是一种使用Turso、Next.js和Supabase Auth的Retro板构建方法 シグナルステート管理は、Turso、Next.js、Supabase Authを使用したレトロボードの構築方法です 신호 상태 관리는 Turso, Next.js 및 Supabase Auth를 사용하여 레트로 보드를 구축하는 방법입니다 Construye una tabla de retroceso con Turso, Next.js y Supabase Auth para gestionar estados de señal de manera efectiva Créez un tableau de rétrocession avec Turso, Next.js et Supabase Auth pour gérer les états de signal de manière efficace Erstellen Sie eine Retro-Board mit Turso, Next.js und Supabase Auth für eine effiziente Signal-Zustandsverwaltung Construa um quadro de retrocesso com Turso, Next.js e Supabase Auth para gerenciar estados de sinal de forma eficaz Постройте ретро-доску с помощью Turso, Next.js и Supabase Auth для управления состоянием сигнала ابني لوحة إعادة التشغيل باستخدام Turso و Next.js و Supabase Auth لإدارة حالة الإشارة بفعالية Retro board build using Turso, Next.js and Supabase Auth 信号状态管理 AI智能工具 Turso Next.js Supabase Auth Retro板构建 如何使用Turso 什么是信号状态管理 Turso安装 Next.js教程 Retro board build using Turso, Next.js and Supabase Auth');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HomericIntelligence/ProjectOdyssey/agent-hierarchy-diagram', 'community', 'HomericIntelligence', 'ProjectOdyssey', 'HomericIntelligence/ProjectOdyssey', 'agent-hierarchy-diagram', 0, 0, 46, '2026-03-04T13:07:01.694Z', '2026-03-04T13:35:36.855Z', '40ead33fdaaf23863321346e9051385741925658f1282b970ca915ed3db20cf0', '{"id":"HomericIntelligence/ProjectOdyssey/agent-hierarchy-diagram","name":"agent-hierarchy-diagram","description":{"zh":"Agent-Hierarchy-Diagram是一个使用Mojo编写的AI智能代理层次图表训练框架，提供了强大的AI代理开发能力","ja":"Agent-Hierarchy-DiagramはMojoで書かれたAIエージェント階層図のトレーニングフレームワークであり、強力なAIエージェント開発能力を提供","ko":"Agent-Hierarchy-Diagram은 Mojo로 작성된 AI 에이전트 계층 다이어그램 트레이닝 프레임워크로, 강력한 AI 에이전트 개발 능력을 제공","es":"El marco de entrenamiento para agentes de IA está escrito en Mojo, permitiendo a los desarrolladores crear soluciones personalizadas","fr":"Le cadre de formation pour les agents d''IA est écrit en Mojo, permettant aux développeurs de créer des solutions personnalisées","de":"Das Trainingsframework für KI-Agents ist in Mojo geschrieben, ermöglicht es Entwicklern, maßgeschneiderte Lösungen zu erstellen","pt":"O agent-hierarchy-diagram é um framework de treinamento escrito em Mojo para agentes de inteligência artificial, permitindo a criação de diagramas de hierarquia complexos","ru":"Иерархическая диаграмма агента-hierarchy-diagram - это фреймворк обучения, написанный на Mojo для ИИ Агентов, позволяющий создавать сложные иерархические диаграммы","ar":"الرسم البياني للترتيب الهرمي للوكيل هو إطار عمل لتدريب الوكلاء الذكاء الاصطناعي مكتوب بلغة Mojo ، مما يسمح بإنشاء رسومات هرمية معقدة","en":"Training framework written in Mojo"},"seo":{"title":{"zh":"AI智能代理层次图表 - Agent-Hierarchy-Diagram","ja":"AIエージェント階層図 - Agent-Hierarchy-Diagram","ko":"AI 에이전트 계층 다이어그램 - Agent-Hierarchy-Diagram","es":"Diagrama de jerarquía de agentes de IA","fr":"Schéma de hiérarchie d''agents d''IA","de":"Hierarchie-Diagramm von KI-Agents","pt":"Ferramentas de Agente de Inteligência Artificial: Diagram...","ru":"ИИ Агенты: Иерархическая Диаграмма агента-hierarchy-diagram","ar":"أدوات ذكاء اصطناعي: الرسم البياني للترتيب الهرمي","en":"agent-hierarchy-diagram"},"description":{"zh":"Agent-Hierarchy-Diagram是一个使用Mojo编写的AI智能代理层次图表训练框架，提供了强大的AI代理开发能力","ja":"Agent-Hierarchy-DiagramはMojoで書かれたAIエージェント階層図のトレーニングフレームワークであり、強力なAIエージェント開発能力を提供","ko":"Agent-Hierarchy-Diagram은 Mojo로 작성된 AI 에이전트 계층 다이어그램 트레이닝 프레임워크로, 강력한 AI 에이전트 개발 능력을 제공","es":"El marco de entrenamiento para agentes de IA está escrito en Mojo, permitiendo a los desarrolladores crear soluciones personalizadas","fr":"Le cadre de formation pour les agents d''IA est écrit en Mojo, permettant aux développeurs de créer des solutions personnalisées","de":"Das Trainingsframework für KI-Agents ist in Mojo geschrieben, ermöglicht es Entwicklern, maßgeschneiderte Lösungen zu erstellen","pt":"O agent-hierarchy-diagram é um framework de treinamento escrito em Mojo para agentes de inteligência artificial, permitindo a criação de diagramas de hierarq...","ru":"Иерархическая диаграмма агента-hierarchy-diagram - это фреймворк обучения, написанный на Mojo для ИИ Агентов, позволяющий создавать сложные иерархические диа...","ar":"الرسم البياني للترتيب الهرمي للوكيل هو إطار عمل لتدريب الوكلاء الذكاء الاصطناعي مكتوب بلغة Mojo ، مما يسمح بإنشاء رسومات هرمية معقدة","en":"Training framework written in Mojo"},"definition":{"en":"Training framework written in Mojo"},"features":{"zh":["使用Mojo编写","AI智能代理层次图表训练","强大的AI代理开发能力","支持多种AI模型","易于使用和集成"],"ja":["Mojoで書かれた","AIエージェント階層図のトレーニング","強力なAIエージェント開発能力","多種のAIモデルをサポート","使いやすく簡単に統合"],"ko":["Mojo로 작성","AI 에이전트 계층 다이어그램 트레이닝","강력한 AI 에이전트 개발 능력","다양한 AI 모델 지원","사용하기 쉽고 통합하기 쉬움"],"es":["Marco de entrenamiento personalizable","Escrito en Mojo para mayor flexibilidad","Permite la creación de soluciones de agentes de IA avanzadas","Integración con herramientas de desarrollo de IA","Documentación y soporte técnico"],"fr":["Cadre de formation personnalisable","Écrit en Mojo pour une plus grande flexibilité","Permet la création de solutions d''agents d''IA avancées","Intégration avec des outils de développement d''IA","Documentation et support technique"],"de":["Anpassbares Trainingsframework","In Mojo geschrieben für größere Flexibilität","Ermöglicht die Erstellung von fortschrittlichen KI-Agents-Lösungen","Integration mit KI-Entwicklungstools","Dokumentation und technischer Support"],"pt":["Framework de treinamento escrito em Mojo","Criação de diagramas de hierarquia complexos","Suporte a agentes de inteligência artificial","Integração com outras ferramentas de desenvolvimento","Flexibilidade e personalização"],"ru":["Фреймворк обучения, написанный на Mojo","Создание сложных иерархических диаграмм","Поддержка ИИ Агентов","Интеграция с другими инструментами разработки","Гибкость и настройка"],"ar":["إطار العمل لتدريب الوكلاء مكتوب بلغة Mojo","إنشاء رسومات هرمية معقدة","دعم الوكلاء الذكاء الاصطناعي","التكامل مع أدوات التطوير الأخرى","المرونة والتخصيص"]},"keywords":{"zh":["AI智能代理","Agent-Hierarchy-Diagram","Mojo编写","AI代理开发","AI模型训练","如何使用Agent-Hierarchy-Diagram","Agent-Hierarchy-Diagram安装","AI智能代理工具"],"ja":["AIエージェント","Agent-Hierarchy-Diagram","Mojoで書かれた","AIエージェント開発","AIモデルトレーニング","Agent-Hierarchy-Diagramの使い方","Agent-Hierarchy-Diagramのインストール","AIエージェントツール"],"ko":["AI 에이전트","Agent-Hierarchy-Diagram","Mojo로 작성","AI 에이전트 개발","AI 모델 트레이닝","Agent-Hierarchy-Diagram 사용 방법","Agent-Hierarchy-Diagram 설치","AI 에이전트 툴"],"es":["cómo usar agentes de IA","qué es un agente de IA","diagrama de jerarquía de agentes de IA","alternativas a los agentes de IA","agentes de IA vs herramientas de IA","instalación de agentes de IA","guía de configuración de agentes de IA"],"fr":["comment utiliser les agents d''IA","qu''est-ce qu''un agent d''IA","schéma de hiérarchie d''agents d''IA","alternatives aux agents d''IA","agents d''IA vs outils d''IA","installation d''agents d''IA","guide de configuration d''agents d''IA"],"de":["wie man KI-Agents verwendet","was ist ein KI-Agents","Hierarchie-Diagramm von KI-Agents","Alternativen zu KI-Agents","KI-Agents vs KI-Tools","Installation von KI-Agents","Konfigurationsanleitung für KI-Agents"],"pt":["como usar agent-hierarchy-diagram","o que é agente de inteligência artificial","ferramentas de inteligência artificial","alternativas ao agent-hierarchy-diagram","agent-hierarchy-diagram vs outros frameworks","instalação do agent-hierarchy-diagram","guia de configuração do agent-hierarchy-diagram"],"ru":["как использовать Иерархическую диаграмму агента","что такое ИИ Агент","инструменты искусственного интеллекта","альтернативы Иерархической диаграмме агента","Иерархическая диаграмма агента vs другие фреймворки","установка Иерархической диаграммы агента","руководство по настройке Иерархической диаграммы агента"],"ar":["كيفية استخدام الرسم البياني للترتيب الهرمي للوكيل","ما هو وكيل الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","بديلات الرسم البياني للترتيب الهرمي للوكيل","الرسم البياني للترتيب الهرمي للوكيل مقابل إطارات عمل أخرى","تثبيت الرسم البياني للترتيب الهرمي للوكيل","دليل إعداد الرسم البياني للترتيب الهرمي للوكيل"]}},"owner":"HomericIntelligence","repo":"ProjectOdyssey","repoPath":"HomericIntelligence/ProjectOdyssey","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.694Z","topics":[],"category":"community","skillMd":{"name":"agent-hierarchy-diagram","description":"Generate visual hierarchy diagrams of agent system showing levels and delegation. Use for documentation or onboarding.","bodyPreview":"# Agent Hierarchy Diagram\n\nGenerate visual diagrams showing agent system structure and relationships.\n\n## When to Use\n\n- Documenting agent system for team\n- Understanding delegation structure\n- Onboarding new contributors\n- Visualizing agent relationships for presentations\n\n## Quick Reference\n\n```bash\n# Generate ASCII tree diagram\n./scripts/generate_hierarchy_diagram.sh\n\n# Generate Mermaid diagram\n./scripts/generate_mermaid_diagram.sh > hierarchy.mmd\n\n# Save to documentation\n./scripts/generate_h","body":"# Agent Hierarchy Diagram\n\nGenerate visual diagrams showing agent system structure and relationships.\n\n## When to Use\n\n- Documenting agent system for team\n- Understanding delegation structure\n- Onboarding new contributors\n- Visualizing agent relationships for presentations\n\n## Quick Reference\n\n```bash\n# Generate ASCII tree diagram\n./scripts/generate_hierarchy_diagram.sh\n\n# Generate Mermaid diagram\n./scripts/generate_mermaid_diagram.sh > hierarchy.mmd\n\n# Save to documentation\n./scripts/generate_hierarchy_diagram.sh > agents/hierarchy-visual.txt\n```\n\n## ASCII Tree Format\n\n```text\nChief Architect (L0)\n├── Foundation Orchestrator (L1)\n│   ├── Repository Design (L2)\n│   │   ├── Directory Specialist (L3)\n│   │   │   └── Junior Engineer (L5)\n│   │   └── Config Specialist (L3)\n│   └── Config Design (L2)\n├── Shared Library Orchestrator (L1)\n│   └── Tensor Module Design (L2)\n│       └── Tensor Specialist (L3)\n└── Tooling Orchestrator (L1)\n```\n\n## Mermaid Format\n\n```mermaid\ngraph TD\n    A[Chief Architect L0] --> B[Foundation Orchestrator L1]\n    B --> C[Repository Design L2]\n    C --> D[Directory Specialist L3]\n    D --> E[Junior Engineer L5]\n```\n\n## Use Cases\n\n- Add to `/agents/hierarchy.md` for reference\n- Include in onboarding documentation\n- Create presentation materials\n- Understand delegation chains\n- Communicate structure to stakeholders\n\n## Output Formats\n\n**ASCII**: Human-readable in terminals, copy-pasteable in docs\n\n**Mermaid**: Renders in GitHub markdown, editable in Mermaid editor\n\n**GraphML**: Import into diagram tools (yEd, Graphviz)\n\n## References\n\n- `/agents/hierarchy.md` - Existing hierarchy documentation\n- `agent-test-delegation` - Validate diagram accuracy\n- `.claude/agents/` - Agent configuration source\n"},"lastSynced":"2026-03-04T13:35:36.855Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced system structure visualization capabilities, such as Cursor, Windsurf, and Claude Code, to generate visual diagrams showing agent system structure and relationships.","zh":"非常适合需要高级系统结构可视化能力的AI代理，例如Cursor、Windsurf和Claude Code，用于生成显示代理系统结构和关系的视觉图表。","ja":"高度なシステム構造の視覚化機能を必要とするAIエージェントに最適です。たとえば、Cursor、Windsurf、Claude Codeなどです。これらは、エージェントのシステム構造と関係を示す視覚的な図表を生成するために使用されます。","ko":"고급 시스템 구조 시각화 기능이 필요한 AI 에이전트에 적합합니다. 예를 들어, Cursor, Windsurf 및 Claude Code와 같은 에이전트는 에이전트 시스템 구조 및 관계를 표시하는 시각적 다이어그램을 생성하는 데 사용됩니다.","es":"Perfecto para agentes de IA que necesitan capacidades de visualización de estructura de sistema avanzadas, como Cursor, Windsurf y Claude Code, para generar diagramas visuales que muestren la estructura del sistema del agente y las relaciones.","fr":"Parfait pour les agents IA nécessitant des capacités de visualisation de structure de système avancées, telles que Cursor, Windsurf et Claude Code, pour générer des diagrammes visuels montrant la structure du système de l''agent et les relations.","de":"Perfekt für KI-Agents, die erweiterte Systemstruktur-Visualisierungsfähigkeiten benötigen, wie z.B. Cursor, Windsurf und Claude Code, um visuelle Diagramme zu generieren, die die Systemstruktur des Agents und die Beziehungen zeigen.","pt":"Perfeito para Agentes de IA que precisam de capacidades avançadas de visualização de estrutura de sistema, como Cursor, Windsurf e Claude Code, para gerar diagramas visuais que mostram a estrutura e as relações do sistema do agente.","ru":"Идеально подходит для ИИ-агентов, которым необходимы продвинутые возможности визуализации системной структуры, такие как Cursor, Windsurf и Claude Code, для генерации визуальных диаграмм, показывающих структуру и отношения системы агента.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى قدرات متقدمة في تبيين هيكل النظام، مثل Cursor و Windsurf و Claude Code، لإنشاء رسومات بيانية تظهر هيكل نظام الوكيل وعلاقاته."},"recommendation":{"en":"Empowers agents to generate ASCII tree diagrams and Mermaid diagrams using scripts like generate_hierarchy_diagram.sh and generate_mermaid_diagram.sh, providing a clear understanding of delegation structures and agent relationships for presentations and documentation.","zh":"赋予代理生成ASCII树图和Mermaid图表的能力，使用generate_hierarchy_diagram.sh和generate_mermaid_diagram.sh等脚本，为演示文稿和文档提供明确的委托结构和代理关系理解。","ja":"ASCIIツリーダイアグラムとMermaidダイアグラムを生成するスクリプト（generate_hierarchy_diagram.shとgenerate_mermaid_diagram.shなど）を使用して、エージェントに委任構造とエージェント関係を明確に理解するプレゼンテーションとドキュメントを提供します。","ko":"generate_hierarchy_diagram.sh 및 generate_mermaid_diagram.sh와 같은 스크립트를 사용하여 ASCII 트리 다이어그램 및 Mermaid 다이어그램을 생성하여 프레젠테이션 및 문서에 대한 위임 구조 및 에이전트 관계에 대한 명확한 이해를 제공합니다.","es":"Habilita a los agentes a generar diagramas de árbol ASCII y diagramas Mermaid utilizando scripts como generate_hierarchy_diagram.sh y generate_mermaid_diagram.sh, lo que proporciona una comprensión clara de las estructuras de delegación y las relaciones entre agentes para presentaciones y documentación.","fr":"Permet aux agents de générer des diagrammes d''arbre ASCII et des diagrammes Mermaid à l''aide de scripts tels que generate_hierarchy_diagram.sh et generate_mermaid_diagram.sh, fournissant une compréhension claire des structures de délégation et des relations entre agents pour les présentations et la documentation.","de":"Ermöglicht es Agents, ASCII-Baumdiagramme und Mermaid-Diagramme mithilfe von Skripten wie generate_hierarchy_diagram.sh und generate_mermaid_diagram.sh zu generieren, was eine klare Übersicht über Delegationsstrukturen und Agentenbeziehungen für Präsentationen und Dokumentationen bietet.","pt":"Habilita os agentes a gerar diagramas de árvore ASCII e diagramas Mermaid usando scripts como generate_hierarchy_diagram.sh e generate_mermaid_diagram.sh, fornecendo uma compreensão clara das estruturas de delegação e relações entre agentes para apresentações e documentação.","ru":"Позволяет агентам генерировать диаграммы ASCII-деревьев и диаграммы Mermaid с помощью скриптов, таких как generate_hierarchy_diagram.sh и generate_mermaid_diagram.sh, обеспечивая четкое понимание структур делегирования и отношений между агентами для презентаций и документации.","ar":"يمكّن الوكلاء من إنشاء رسومات شجرة ASCII ورسومات Mermaid باستخدام سكريبتات مثل generate_hierarchy_diagram.sh و generate_mermaid_diagram.sh، مما يوفر فهمًا واضحًا لهياكل التفويض وعلاقات الوكلاء للعروض التقديمية والتوثيق."},"useCases":{"en":["Automating agent system documentation for teams","Generating visualizations of delegation structures for onboarding new contributors","Creating Mermaid diagrams for presentations to illustrate agent relationships"],"zh":["为团队自动化代理系统文档","为新贡献者生成委托结构的视觉化","使用Mermaid图表创建演示文稿以说明代理关系"],"ja":["チームのエージェントシステムドキュメントを自動化する","新しいコントリビューターのための委任構造の視覚化を生成する","エージェント関係を説明するためにプレゼンテーション用のMermaidダイアグラムを作成する"],"ko":["팀의 에이전트 시스템 문서를 자동화하는 데 사용","새 기여자에 대한 위임 구조 시각화를 생성하는 데 사용","에이전트 관계를 설명하기 위한 프레젠테이션용 Mermaid 다이어그램을 생성하는 데 사용"],"es":["Automatizar la documentación del sistema de agentes para equipos","Generar visualizaciones de estructuras de delegación para la incorporación de nuevos contribuyentes","Crear diagramas Mermaid para presentaciones para ilustrar las relaciones entre agentes"],"fr":["Automatiser la documentation du système d''agents pour les équipes","Générer des visualisations de structures de délégation pour l''intégration de nouveaux contributeurs","Créer des diagrammes Mermaid pour les présentations pour illustrer les relations entre agents"],"de":["Automatisierung der Agentensystemdokumentation für Teams","Erzeugen von Visualisierungen von Delegationsstrukturen für die Einarbeitung neuer Mitwirkender","Erstellen von Mermaid-Diagrammen für Präsentationen, um Agentenbeziehungen zu veranschaulichen"],"pt":["Automatizar a documentação do sistema do agente para equipes","Gerar visualizações de estruturas de delegação para integração de novos contribuintes","Criar diagramas Mermaid para apresentações para ilustrar relações entre agentes"],"ru":["Автоматизировать документацию системы агента для команд","Генерировать визуализации структур делегирования для интеграции новых участников","Создавать диаграммы Mermaid для презентаций, чтобы проиллюстрировать отношения между агентами"],"ar":["تأتمتة توثيق نظام الوكيل للفرق","إنشاء رسومات لتركيبات التفويض لتكامل المساهمين الجدد","إنشاء رسومات Mermaid للعروض التقديمية لتظهير علاقات الوكلاء"]},"limitations":{"en":["Requires Mojo training framework","Limited to generating ASCII tree and Mermaid diagrams","Needs execution of scripts like generate_hierarchy_diagram.sh and generate_mermaid_diagram.sh"],"zh":["需要Mojo训练框架","仅限生成ASCII树和Mermaid图表","需要执行generate_hierarchy_diagram.sh和generate_mermaid_diagram.sh等脚本"],"ja":["Mojoトレーニングフレームワークが必要","ASCIIツリーとMermaidダイアグラムの生成のみ","generate_hierarchy_diagram.shとgenerate_mermaid_diagram.shなどのスクリプトの実行が必要"],"ko":["Mojo 훈련 프레임워크가 필요","ASCII 트리 및 Mermaid 다이어그램 생성만 가능","generate_hierarchy_diagram.sh 및 generate_mermaid_diagram.sh와 같은 스크립트의 실행이 필요"],"es":["Requiere el marco de entrenamiento Mojo","Limitado a la generación de diagramas de árbol ASCII y Mermaid","Necesita la ejecución de scripts como generate_hierarchy_diagram.sh y generate_mermaid_diagram.sh"],"fr":["Nécessite le framework de formation Mojo","Limité à la génération de diagrammes d''arbre ASCII et Mermaid","Nécessite l''exécution de scripts tels que generate_hierarchy_diagram.sh et generate_mermaid_diagram.sh"],"de":["Benötigt das Mojo-Trainingsframework","Begrenzt auf die Generierung von ASCII-Baum- und Mermaid-Diagrammen","Benötigt die Ausführung von Skripten wie generate_hierarchy_diagram.sh und generate_mermaid_diagram.sh"],"pt":["Exige o framework de treinamento Mojo","Limitado a gerar diagramas de árvore ASCII e Mermaid","Necessita da execução de scripts como generate_hierarchy_diagram.sh e generate_mermaid_diagram.sh"],"ru":["Требует обучающего фреймворка Mojo","Ограничен генерацией диаграмм ASCII-деревьев и Mermaid","Требует выполнения скриптов, таких как generate_hierarchy_diagram.sh и generate_mermaid_diagram.sh"],"ar":["يتطلب إطار تدريب Mojo","محدود بإنشاء رسومات شجرة ASCII و Mermaid","يحتاج إلى تنفيذ سكريبتات مثل generate_hierarchy_diagram.sh و generate_mermaid_diagram.sh"]},"version":3},"contentHash":"40ead33fdaaf23863321346e9051385741925658f1282b970ca915ed3db20cf0","qualityScore":46}');
