INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dengineproblem/agents-monorepo/ml-api-endpoint', 'ml-api-endpoint', 'dengineproblem', 'agents-monorepo', 'community', 'ml-api-endpoint dengineproblem agents-monorepo community ml-api-endpoint是一种AI智能代理，用于管理和优化广告投放，帮助开发者提高工作效率 ml-api-endpointは、広告の管理と最適化を行うAIエージェントです。開発者の生産性を向上させます ml-api-endpoint는 광고 관리와 최적화를 수행하는 AI 에이전트로, 개발자의 효율성을 향상시킵니다 Nuestro agente de IA para API de publicidad permite una gestión eficiente de campañas publicitarias con Node.js y Python Notre agent IA pour API de publicité permet une gestion efficace des campagnes publicitaires avec Node.js et Python Unser KI-Agent für Werbe-APIs ermöglicht eine effiziente Verwaltung von Werbekampagnen mit Node.js und Python O ml-api-endpoint é uma ferramenta de IA para gerenciamento de anúncios, permitindo uma integração eficaz com APIs de marketing ИИ Агент ml-api-endpoint - это инструмент для управления рекламой, позволяющий эффективно интегрироваться с маркетинговыми API مل-api-endpoint هو أداة ذكاء اصطناعي لإدارة الإعلانات، تمكنك من التكامل الفعال مع واجهات برمجة تطبيقات التسويق Агент для управления рекламой 如何使用ml-api-endpoint 什么是AI智能代理 ml-api-endpoint替代品 ml-api-endpoint vs 其他广告管理工具 ml-api-endpoint安装 ml-api-endpoint设置指南 广告管理API AI广告优化 Агент для управления рекламой');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('adebold/warehouse-network/AgentDB Performance Optimization', 'community', 'adebold', 'warehouse-network', 'adebold/warehouse-network', 'AgentDB Performance Optimization', 0, 0, 46, '2026-03-04T13:07:01.724Z', '2026-03-04T13:54:22.167Z', '48317fef307b038d086b2262ec336c82c6d1d5904d36592e016e1bad7b04cf62', '{"id":"adebold/warehouse-network/AgentDB Performance Optimization","name":"AgentDB Performance Optimization","description":{"zh":"AgentDB性能优化是B2B仓储市场平台的关键组成部分，连接企业与仓储运营商，提高平台效率","ja":"AgentDBパフォーマンス最適化はB2B倉庫マーケットプレイスプラットフォームの重要なコンポーネントであり、企業と倉庫オペレーターを接続し、プラットフォームの効率を向上させる","ko":"AgentDB 성능 최적화는 B2B 창고 시장 플랫폼의 핵심 구성 요소로, 기업과 창고 운영자를 연결하여 플랫폼의 효율성을 높입니다","es":"La optimización de rendimiento de AgentDB es crucial para las plataformas de mercado de almacenes B2B que conectan negocios con operadores de almacenamiento","fr":"L''optimisation des performances d''AgentDB est cruciale pour les plateformes de marché d''entrepôts B2B qui relient les entreprises aux opérateurs de stockage","de":"Die Leistungsoptimierung von AgentDB ist entscheidend für B2B-Lagermarkt-Plattformen, die Unternehmen mit Lagerbetreibern verbinden","pt":"O AgentDB é uma plataforma de marketplace de armazenamento B2B que conecta empresas com operadores de armazenamento, otimizando o desempenho com ferramentas de IA","ru":"AgentDB - это платформа B2B-warehouse, которая соединяет бизнес с операторами хранилищ, оптимизируя производительность с помощью ИИ Агентов","ar":"AgentDB هي منصة سوق التخزين التجاري إلى تجاري التي تربط الشركات بمشغلي التخزين، وتحسن الأداء باستخدام أدوات الذكاء الاصطناعي","en":"B2B warehouse marketplace platform connecting businesses with storage operators"},"seo":{"title":{"zh":"AI智能代理AgentDB性能优化","ja":"AIエージェントAgentDBパフォーマンス最適化","ko":"AI 에이전트 AgentDB 성능 최적화","es":"Optimización de Rendimiento de AgentDB con Herramientas d..