INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Wox-launcher/Wox/wox-update-changelog', 'wox-update-changelog', 'Wox-launcher', 'Wox', 'community', 'wox-update-changelog Wox-launcher Wox community Wox 更新日志是一个简单易用的跨平台启动器，帮助您提高开发效率 Wox Update Changelog は、開発効率を向上させるためのシンプルで使いやすいクロスプラットフォームランチャーです Wox 업데이트 변경 로그는 개발 효율성을 높이는 간단하고 사용하기 쉬운 크로스 플랫폼 런처입니다 wox-update-changelog es un lanzador cross-plataforma que funciona de manera sencilla y efectiva para desarrolladores wox-update-changelog est un lanceur cross-plateforme qui fonctionne de manière simple et efficace pour les développeurs wox-update-changelog ist ein Cross-Plattform-Launcher, der auf einfache und effektive Weise für Entwickler funktioniert O wox-update-changelog é um lançador cross-platform que simplifica a atualização de aplicativos ИИ Агент wox-update-changelog - это кроссплатформенный лаунчер, который упрощает обновление приложений وكس-أبديت-تشانجلوغ هو مشغل متوافق مع منصات متعددة يبسط عملية تحديث التطبيقات A cross-platform launcher that simply works Wox 更新日志 AI 工具 跨平台启动器 如何使用 Wox Wox 安装 Wox 设置指南 Wox 代替品 Wox 与其他工具的比较 A cross-platform launcher that simply works');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('motoya0118/pavlok_CLI_agent/slack', 'community', 'motoya0118', 'pavlok_CLI_agent', 'motoya0118/pavlok_CLI_agent', 'slack', 0, 0, 46, '2026-03-04T13:07:01.737Z', '2026-03-04T14:03:34.833Z', '57b4b1528430f954a703bdd756b5393782d8f642977bee95fc6b645f6583c4ef', '{"id":"motoya0118/pavlok_CLI_agent/slack","name":"slack","description":{"zh":"本文探讨了使用 Slack CLI 代理与 Pavlok 的自伤实践，了解其可能的应用和开发","ja":"Slack CLI エージェントと Pavlok を使用した自傷実験の結果とその開発の可能性について","ko":"Slack CLI 에이전트와 Pavlok 을 사용한 자해 실험의 결과와 그 개발 가능성에 대해 설명합니다","es":"El experimento de autolesión con pavlok en CLI agentes revela nuevas posibilidades para desarrolladores","fr":"L''expérimentation avec pavlok sur les agents CLI révèle de nouvelles possibilités pour les développeurs","de":"Der Selbstversuch mit pavlok auf CLI-Agents enthüllt neue Möglichkeiten für Entwickler","pt":"Experimente o uso de pavlok em um agente CLI no Slack para melhorar a produtividade e a experiência do usuário","ru":"Экспериментируйте с использованием pavlok в агенте CLI в Slack для улучшения производительности и опыта пользователя","ar":"جرب استخدام pavlok في وكلاء CLI في Slack لتحسين الإنتاجية وتجربة المستخدم","en":"CLI agentにpavlokを使用させたらどうなるか自傷実験"},"seo":{"title":{"zh":"AI工具：Slack CLI 代理与 Pavlok 实验","ja":"AIエージェント：Slack CLI エージェントと Pavlok 自傷実験","ko":"AI 에이전트: Slack CLI 에이전트와 Pavlok 자해 실험","es":"Herramientas de AI: Experimento con pavlok en CLI","fr":"Outils d''IA: Expérimentation avec pavlok sur CLI","de":"KI-Tools: Selbstversuch mit pavlok auf CLI","pt":"Ferramentas de IA: Experimento com Pavlok no Slack","ru":"ИИ Агенты: Эксперимент с Pavlok в Slack","ar":"أدوات الذكاء الاصطناعي: تجربة مع Pavlok في Slack","en":"slack"},"description":{"zh":"本文探讨了使用 Slack CLI 代理与 Pavlok 的自伤实践，了解其可能的应用和开发","ja":"Slack CLI エージェントと Pavlok を使用した自傷実験の結果とその開発の可能性について","ko":"Slack CLI 에이전트와 Pavlok 을 사용한 자해 실험의 결과와 그 개발 가능성에 대해 설명합니다","es":"El experimento de autolesión con pavlok en CLI agentes revela nuevas posibilidades para desarrolladores","fr":"L''expérimentation avec pavlok sur les agents CLI révèle de nouvelles possibilités pour les développeurs","de":"Der Selbstversuch mit pavlok auf CLI-Agents enthüllt neue Möglichkeiten für Entwickler","pt":"Experimente o uso de pavlok em um agente CLI no Slack para melhorar a produtividade e a experiência do usuário","ru":"Экспериментируйте с использованием pavlok в агенте CLI в Slack для улучшения производительности и опыта пользователя","ar":"جرب استخدام pavlok في وكلاء CLI في Slack لتحسين الإنتاجية وتجربة المستخدم","en":"CLI agentにpavlokを使用させたらどうなるか自傷実験"},"definition":{"en":"CLI agentにpavlokを使用させたらどうなるか自傷実験"},"features":{"zh":["Slack CLI 代理的自伤实践","Pavlok 与 Slack CLI 代理的集成","AI 工具的开发和应用","命令行接口的使用","Slack 和 Pavlok 的交互"],"ja":["Slack CLI エージェントの自傷実験","Pavlok と Slack CLI エージェントの統合","AI エージェントの開発と応用","コマンドラインインターフェイスの使用","Slack と Pavlok の相互作用"],"ko":["Slack CLI 에이전트의 자해 실험","Pavlok 과 Slack CLI 에이전트의 통합","AI 에이전트의 개발과 응용","명령줄 인터페이스의 사용","Slack 와 Pavlok 의 상호 작용"],"es":["Integración con CLI","Automatización de tareas","Uso de pavlok para experimentación","Desarrollo de herramientas de AI","Implementación de agentes de CLI"],"fr":["Intégration avec CLI","Automatisation de tâches","Utilisation de pavlok pour l''expérimentation","Développement d''outils d''IA","Mise en œuvre d''agents CLI"],"de":["Integration mit CLI","Automatisierung von Aufgaben","Verwendung von pavlok für Experimente","Entwicklung von KI-Tools","Implementierung von CLI-Agents"],"pt":["Integração com o Slack","Uso de pavlok em agente CLI","Melhoria da produtividade","Experiência do usuário personalizada","Suporte a comandos personalizados"],"ru":["Интеграция с Slack","Использование pavlok в агенте CLI","Улучшение производительности","Персонализированный опыт пользователя","Поддержка пользовательских команд"],"ar":["التكامل مع Slack","استخدام pavlok في وكلاء CLI","تحسين الإنتاجية","تجربة المستخدم المخصصة","دعم الأوامر المخصصة"]},"keywords":{"zh":["如何使用 Slack CLI 代理","什么是 Pavlok","AI 工具的开发","Slack CLI 代理替代品","Pavlok 和 Slack CLI 代理的比较","Slack CLI 代理安装指南","AI 工具的应用"],"ja":["Slack CLI エージェントの使用方法","Pavlok とは","AI エージェントの開発","Slack CLI エージェントの代替品","Pavlok と Slack CLI エージェントの比較","Slack CLI エージェントのインストールガイド","AI エージェントの応用"],"ko":["Slack CLI 에이전트 사용법","Pavlok 이란","AI 에이전트 개발","Slack CLI 에이전트 대체품","Pavlok 과 Slack CLI 에이전트의 비교","Slack CLI 에이전트 설치 가이드","AI 에이전트 응용"],"es":["herramientas de AI","pavlok CLI","agentes de CLI","desarrollo de herramientas de AI","automatización de tareas","cómo usar pavlok","alternativas a pavlok","pavlok vs otras herramientas"],"fr":["outils d''IA","pavlok CLI","agents CLI","développement d''outils d''IA","automatisation de tâches","comment utiliser pavlok","alternatives à pavlok","pavlok vs autres outils"],"de":["KI-Tools","pavlok CLI","CLI-Agents","Entwicklung von KI-Tools","Automatisierung von Aufgaben","wie man pavlok verwendet","Alternativen zu pavlok","pavlok vs andere Tools"],"pt":["como usar pavlok no slack","o que é um agente cli","ferramentas de ia para produtividade","slack alternative","pavlok vs outros ferramentas","instalar pavlok no slack","guias de configuração do pavlok"],"ru":["как использовать pavlok в slack","что такое агент cli","инструменты ии для производительности","slack альтернатива","pavlok vs другие инструменты","установить pavlok в slack","руководства по настройке pavlok"],"ar":["كيفية استخدام pavlok في Slack","ما هو وكلاء CLI","أدوات الذكاء الاصطناعي لتحسين الإنتاجية","بديل Slack","pavlok مقابل أدوات أخرى","تثبيت pavlok في Slack","دليل إعداد pavlok"]}},"owner":"motoya0118","repo":"pavlok_CLI_agent","repoPath":"motoya0118/pavlok_CLI_agent","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.737Z","topics":[],"category":"community","skillMd":{"name":"slack","description":"Post a question to Slack and wait for a reply, or post a reply into a thread using scripts/slack.py.","bodyPreview":"# Slack Ask + Thread Reply\n\nUse `scripts/slack.py` to post a question and wait for the first reply, or to post a reply into an existing thread.\n\n## Run\n\n```bash\nuv run scripts/slack.py \"Did you finish the task?\" --interval 2 --follow-up-message \"This counts as another ignore. Please reply in the thread.\"\n```\n\n```bash\nuv run scripts/slack.py --mode reply --thread-ts 1700000000.000000 \"Reply text\"\n```\n\n## Inputs\n\n- `question` is the message text (question in `ask` mode, reply in `reply` mode).\n- `","body":"# Slack Ask + Thread Reply\n\nUse `scripts/slack.py` to post a question and wait for the first reply, or to post a reply into an existing thread.\n\n## Run\n\n```bash\nuv run scripts/slack.py \"Did you finish the task?\" --interval 2 --follow-up-message \"This counts as another ignore. Please reply in the thread.\"\n```\n\n```bash\nuv run scripts/slack.py --mode reply --thread-ts 1700000000.000000 \"Reply text\"\n```\n\n## Inputs\n\n- `question` is the message text (question in `ask` mode, reply in `reply` mode).\n- `--mode` chooses behavior (`ask` default, `reply` posts into a thread).\n- `--no-reply-hint` skips appending \"Reply in thread.\"\n- `--follow-up-message` sets the message to post when a reply is not received within the ignore window.\n  - Required in `ask` mode.\n- `ask` mode:\n  - `--interval` sets polling interval in seconds (default: 2).\n  - `--thread-ts` and `--channel` are not required.\n- `reply` mode:\n  - `--thread-ts` is required.\n  - `--channel` overrides `SLACK_CHANNEL` (accepts name or ID).\n  - `--interval` is not used.\n\n## Outputs\n\nAsk mode prints a single line:\n\n```\n{assistant_question: ..., user_answer: ..., is_answer: true|false, thread_ts: ..., message_ts: ...}\n```\n\nIf no reply arrives before timeout, `user_answer` is `null` and `is_answer` is `false`.\n\nReply mode prints a single line:\n\n```\n{assistant_question: ..., user_answer: null, is_answer: false, thread_ts: ..., message_ts: ...}\n```\n\n## Notes\n\n- Requires `SLACK_BOT_USER_OAUTH_TOKEN`.\n- Optional `SLACK_USER_OAUTH_TOKEN` is used for reading replies; if unset, the bot token is reused.\n- Missing history scopes will cause `missing_scope` errors; add `channels:history`, `groups:history`, `im:history`, and `mpim:history` as needed.\n- The CLI unescapes `\\n`, `\\r`, and `\\t` sequences in `question` before sending.\n- Ask mode timeout is derived from env: `IGNORE_SPAN * REPLY_COUNT_LIMIT`.\n- `ask` mode requires `--follow-up-message`.\n"},"lastSynced":"2026-03-04T14:03:34.833Z","agentAnalysis":{"suitability":{"en":"Perfect for Communication Agents needing seamless Slack integration for asking questions and replying to threads.","zh":"非常适合需要无缝Slack集成的通信代理，以便询问和回复线程。","ja":"Slackとのシームレスな統合が必要なコミュニケーションエージェントに最適です。質問を投稿し、スレッドに返信するために使用します。","ko":"슬랙 통합을 위해 질문을 하고 쓰레드에 응답하는 것을 필요로 하는 커뮤니케이션 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Comunicación que necesitan una integración perfecta con Slack para hacer preguntas y responder a hilos.","fr":"Parfait pour les Agents de Communication nécessitant une intégration transparente avec Slack pour poser des questions et répondre aux threads.","de":"Perfekt für Kommunikationsagenten, die eine nahtlose Slack-Integration für das Stellen von Fragen und das Beantworten von Threads benötigen.","pt":"Perfeito para Agentes de Comunicação que precisam de integração perfeita com o Slack para fazer perguntas e responder a threads.","ru":"Идеально подходит для агентов коммуникации, которым требуется бесшовная интеграция со Slack для задавания вопросов и ответов на темы.","ar":"مثالي للوكلاء الاتصاليين الذين يحتاجون إلى دمج سلاك بدون مشاكل لطرح الأسئلة والرد على Threads."},"recommendation":{"en":"Empowers agents to post questions and wait for replies using scripts like `scripts/slack.py`, leveraging CLI capabilities and handling thread replies with precision, utilizing parameters like `--interval` and `--follow-up-message` for customized interactions.","zh":"赋予代理使用像`scripts/slack.py`这样的脚本发布问题并等待回复的能力，利用CLI功能并精确地处理线程回复，使用诸如`--interval`和`--follow-up-message`的参数进行自定义交互。","ja":"エージェントが`scripts/slack.py`などのスクリプトを使用して質問を投稿し、返信を待つことができるようにします。CLIの機能を利用し、`--interval`や`--follow-up-message`などのパラメータを使用してスレッドの返信を精密に処理し、カスタマイズされた相互作用を行うことができます。","ko":"에이전트가 `scripts/slack.py`와 같은 스크립트를 사용하여 질문을 게시하고 응답을 기다릴 수 있도록 합니다. CLI 기능을 활용하고 `--interval` 및 `--follow-up-message`와 같은 매개 변수를 사용하여 쓰레드 응답을 정밀하게 처리하여 사용자 지정 상호 작용을 ermög합니다.","es":"Habilita a los agentes a publicar preguntas y esperar respuestas utilizando scripts como `scripts/slack.py`, aprovechando las capacidades de CLI y manejando respuestas de hilos con precisión, utilizando parámetros como `--interval` y `--follow-up-message` para interacciones personalizadas.","fr":"Permet aux agents de publier des questions et d''attendre des réponses en utilisant des scripts tels que `scripts/slack.py`, en exploitant les capacités de la CLI et en gérant les réponses de threads avec précision, en utilisant des paramètres tels que `--interval` et `--follow-up-message` pour des interactions personnalisées.","de":"Ermächtigt Agenten, Fragen zu posten und auf Antworten zu warten, indem sie Skripte wie `scripts/slack.py` verwenden, die CLI-Fähigkeiten nutzen und Thread-Antworten mit Präzision handhaben, wobei Parameter wie `--interval` und `--follow-up-message` für individualisierte Interaktionen verwendet werden.","pt":"Habilita os agentes a postar perguntas e aguardar respostas usando scripts como `scripts/slack.py`, aproveitando as capacidades do CLI e lidando com respostas de threads com precisão, utilizando parâmetros como `--interval` e `--follow-up-message` para interações personalizadas.","ru":"Наделяет агентов возможностью публиковать вопросы и ожидать ответов, используя скрипты типа `scripts/slack.py`, используя возможности CLI и обрабатывая ответы на темы с точностью, используя параметры типа `--interval` и `--follow-up-message` для настраиваемого взаимодействия.","ar":"يمكن الوكلاء من نشر الأسئلة وانتظار الردود باستخدام سكريبتات مثل `scripts/slack.py` ، واستخدام قدرات واجهة السطر الأوامر CLI ومعالجة ردود threads بدقة ، واستخدام معاملات مثل `--interval` و `--follow-up-message` للتفاعلات المخصصة."},"useCases":{"en":["Automating question posting on Slack channels","Generating follow-up messages for unanswered threads","Replying to specific threads using `--thread-ts`"],"zh":["在Slack频道上自动发布问题","为未回答的线程生成后续消息","使用`--thread-ts`回复特定的线程"],"ja":["Slackチャンネルで質問を自動投稿する","返信のないスレッドに対して後続メッセージを生成する","`--thread-ts`を使用して特定のスレッドに返信する"],"ko":["슬랙 채널에서 질문을 자동으로 게시하는 것","답변되지 않은 쓰레드에 대한 후속 메시지를 생성하는 것","`--thread-ts`를 사용하여 특정 쓰레드에 응답하는 것"],"es":["Automatizar la publicación de preguntas en canales de Slack","Generar mensajes de seguimiento para hilos sin respuesta","Responder a hilos específicos utilizando `--thread-ts`"],"fr":["Automatiser la publication de questions sur les canaux Slack","Générer des messages de suivi pour les threads sans réponse","Répondre à des threads spécifiques en utilisant `--thread-ts`"],"de":["Automatisieren des Postens von Fragen in Slack-Kanälen","Generieren von Follow-up-Nachrichten für unbeantwortete Threads","Beantworten von bestimmten Threads unter Verwendung von `--thread-ts`"],"pt":["Automatizar a postagem de perguntas em canais do Slack","Gerar mensagens de follow-up para threads sem resposta","Responder a threads específicas usando `--thread-ts`"],"ru":["Автоматизация публикации вопросов в каналах Slack","Генерация сообщений-напоминаний для тем без ответа","Ответ на конкретные темы, используя `--thread-ts`"],"ar":["توفير نشر الأسئلة في قنوات سلاك بشكل أوتوماتيكي","توليد رسائل متابعة للthreads التي لم يتم الرد عليها","الرد على threads محددة باستخدام `--thread-ts`"]},"limitations":{"en":["Requires Slack API access","Limited to text-based interactions","Dependent on `uv` and `scripts/slack.py` for execution"],"zh":["需要Slack API访问","仅限文本交互","依赖于`uv`和`scripts/slack.py`执行"],"ja":["Slack APIへのアクセスが必要","テキストベースの相互作用のみ","`uv`と`scripts/slack.py`に依存して実行される"],"ko":["슬랙 API 액세스가 필요합니다.","텍스트 기반 상호 작용만 가능합니다.","`uv`와 `scripts/slack.py`에 의존하여 실행됩니다."],"es":["Requiere acceso a la API de Slack","Limitado a interacciones basadas en texto","Dependiente de `uv` y `scripts/slack.py` para la ejecución"],"fr":["Nécessite un accès à l''API Slack","Limité aux interactions basées sur le texte","Dépend de `uv` et `scripts/slack.py` pour l''exécution"],"de":["Benötigt Zugriff auf die Slack-API","Begrenzt auf textbasierte Interaktionen","Abhängig von `uv` und `scripts/slack.py` für die Ausführung"],"pt":["Requer acesso à API do Slack","Limitado a interações baseadas em texto","Dependente de `uv` e `scripts/slack.py` para execução"],"ru":["Требуется доступ к API Slack","Ограничен до текстовых взаимодействий","Зависит от `uv` и `scripts/slack.py` для выполнения"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات سلاك API","محدود بالتفاعلات النصية","يعتمد على `uv` و `scripts/slack.py` للتنفيذ"]},"version":3},"contentHash":"57b4b1528430f954a703bdd756b5393782d8f642977bee95fc6b645f6583c4ef","qualityScore":46}');
