INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BetterSEQTA/DesQTA/premium-ui-refinement', 'premium-ui-refinement', 'BetterSEQTA', 'DesQTA', 'community', 'premium-ui-refinement BetterSEQTA DesQTA community premium-ui-refinement是一个将SEQTA网站和BetterSEQTA+界面移植到原生桌面的AI智能工具，提供更流畅的交互体验 premium-ui-refinementは、SEQTAのウェブサイトとBetterSEQTA+インターフェースをネイティブデスクトップに移植するAIエージェントです premium-ui-refinement는 SEQTA 웹사이트와 BetterSEQTA+ 인터페이스를 네이티브 데스크톱으로 이식하는 AI 에이전트입니다 El refinamiento de la interfaz de usuario premium es una tecnología que mejora la experiencia del usuario en aplicaciones de escritorio nativas Le raffinement de l''interface utilisateur premium est une technologie qui améliore l''expérience utilisateur dans les applications de bureau natives Die Verfeinerung der Benutzeroberfläche premium ist eine Technologie, die die Benutzererfahrung in nativen Desktop-Anwendungen verbessert O premium-ui-refinement é uma porta do site SEQTA e interface BetterSEQTA+ para desktop nativo, melhorando a experiência do usuário Премиум-ui-рефайнмент - это портирование сайта SEQTA и интерфейса BetterSEQTA+ на родной рабочий стол, улучшающее опыт пользователя premium-ui-refinement هو نقل موقع SEQTA وواجهة BetterSEQTA+ إلى سطح المكتب الأصلي، مما يحسن تجربة المستخدم A port of the SEQTA website and BetterSEQTA+ interface to native desktop 如何使用premium-ui-refinement 什么是AI智能工具 premium-ui-refinement替代品 premium-ui-refinement安装 SEQTA网站移植 BetterSEQTA+界面优化 A port of the SEQTA website and BetterSEQTA+ interface to native desktop');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('raythurnvoid/experiment--t3-chat/custom-global-events', 'community', 'raythurnvoid', 'experiment--t3-chat', 'raythurnvoid/experiment--t3-chat', 'custom-global-events', 0, 0, 46, '2026-03-04T13:07:01.835Z', '2026-03-04T14:45:05.058Z', '6105e1ccbcf965488032cfc07df80c76ae480aba25674a4ef20454ecdf4cbb7f', '{"id":"raythurnvoid/experiment--t3-chat/custom-global-events","name":"custom-global-events","description":{"zh":"自定义全局事件是AI智能代理的一项功能，用于构建强大的AI工具。通过克隆t3聊天系统，实现自定义事件处理","ja":"カスタムグローバルイベントは、AIエージェントの強力な機能です。t3チャットシステムをクローンして、カスタムイベントハンドリングを実現します","ko":"커스텀 글로벌 이벤트는 AI 에이전트의 강력한 기능입니다. t3 채팅 시스템을 클로닝하여 커스텀 이벤트 처리를 구현합니다","es":"Clonación lenta de t3 chat para diversión, con enfoque en eventos globales personalizados con agentes de IA","fr":"Clonage lent de t3 chat pour le plaisir, avec un focus sur les événements globaux personnalisés avec des outils d''IA","de":"Langsames Klonen von t3-Chat zum Spaß, mit Fokus auf benutzerdefinierte globale Ereignisse mit KI-Agenten","pt":"O Custom-Global-Events é uma habilidade de IA que permite a criação de eventos personalizados para aplicações de chat, como o t3 chat.","ru":"Custom-Global-Events - это навык ИИ, который позволяет создавать индивидуальные события для приложений чата, таких как t3 chat.","ar":"الحدث العامل للجميع هو مهارة ذكاء اصطناعي تتيح إنشاء أحداث مخصصة لتطبيقات الدردشة مثل t3 chat.","en":"Slowly cloning t3 chat for fun"},"seo":{"title":{"zh":"AI智能代理：自定义全局事件","ja":"AIエージェント：カスタムグローバルイベント","ko":"AI 에이전트: 커스텀 글로벌 이벤트","es":"Herramientas de eventos globales personalizadas con Agent...","fr":"Outils d''événements globaux personnalisés avec Outils d''IA","de":"Benutzerdefinierte globale Ereignisse mit KI-Agenten","pt":"Ferramentas de IAs: Custom-Global-Events para Desenvolved...","ru":"ИИ Агенты: Custom-Global-Events для Разработчиков","ar":"أدوات الذكاء الاصطناعي: الحدث العامل للجميع للمطورين","en":"custom-global-events"},"description":{"zh":"自定义全局事件是AI智能代理的一项功能，用于构建强大的AI工具。通过克隆t3聊天系统，实现自定义事件处理","ja":"カスタムグローバルイベントは、AIエージェントの強力な機能です。t3チャットシステムをクローンして、カスタムイベントハンドリングを実現します","ko":"커스텀 글로벌 이벤트는 AI 에이전트의 강력한 기능입니다. t3 채팅 시스템을 클로닝하여 커스텀 이벤트 처리를 구현합니다","es":"Clonación lenta de t3 chat para diversión, con enfoque en eventos globales personalizados con agentes de IA","fr":"Clonage lent de t3 chat pour le plaisir, avec un focus sur les événements globaux personnalisés avec des outils d''IA","de":"Langsames Klonen von t3-Chat zum Spaß, mit Fokus auf benutzerdefinierte globale Ereignisse mit KI-Agenten","pt":"O Custom-Global-Events é uma habilidade de IA que permite a criação de eventos personalizados para aplicações de chat, como o t3 chat.","ru":"Custom-Global-Events - это навык ИИ, который позволяет создавать индивидуальные события для приложений чата, таких как t3 chat.","ar":"الحدث العامل للجميع هو مهارة ذكاء اصطناعي تتيح إنشاء أحداث مخصصة لتطبيقات الدردشة مثل t3 chat.","en":"Slowly cloning t3 chat for fun"},"definition":{"en":"Slowly cloning t3 chat for fun"},"features":{"zh":["自定义全局事件处理","克隆t3聊天系统","强大的AI工具构建","全局事件触发","自定义事件处理函数"],"ja":["カスタムグローバルイベントハンドリング","t3チャットシステムのクローン","強力なAIツールの構築","グローバルイベントのトリガー","カスタムイベントハンドリング関数"],"ko":["커스텀 글로벌 이벤트 처리","t3 채팅 시스템 클로닝","강력한 AI 도구 구축","글로벌 이벤트 트리거","커스텀 이벤트 처리 함수"],"es":["Creación de eventos globales personalizados","Integración con agentes de IA","Mejora de la experiencia del usuario","Compatibilidad con React y Node.js","Fácil instalación y configuración"],"fr":["Création d''événements globaux personnalisés","Intégration avec des outils d''IA","Amélioration de l''expérience utilisateur","Compatibilité avec React et Node.js","Installation et configuration faciles"],"de":["Erstellung benutzerdefinierter globaler Ereignisse","Integration mit KI-Agenten","Verbesserung der Benutzererfahrung","Kompatibilität mit React und Node.js","Einfache Installation und Konfiguration"],"pt":["Criação de eventos personalizados","Integração com aplicações de chat","Funcionalidades de t3 chat","Desenvolvimento de aplicações personalizadas","Uso de habilidades de IA"],"ru":["Создание индивидуальных событий","Интеграция с приложениями чата","Функции t3 chat","Разработка индивидуальных приложений","Использование навыков ИИ"],"ar":["إنشاء أحداث مخصصة","التكامل مع تطبيقات الدردشة","ميزات t3 chat","تطوير تطبيقات مخصصة","استخدام مهارات الذكاء الاصطناعي"]},"keywords":{"zh":["AI智能代理","自定义全局事件","t3聊天系统","AI工具构建","全局事件处理","如何使用AI智能代理","AI智能代理入门","AI智能代理与其他工具比较"],"ja":["AIエージェント","カスタムグローバルイベント","t3チャットシステム","AIツールの構築","グローバルイベントの処理","AIエージェントの使用方法","AIエージェントの入門","AIエージェントと他のツールの比較"],"ko":["AI 에이전트","커스텀 글로벌 이벤트","t3 채팅 시스템","AI 도구 구축","글로벌 이벤트 처리","AI 에이전트 사용 방법","AI 에이전트 입문","AI 에이전트와 다른 도구 비교"],"es":["cómo usar agentes de IA","qué es un agente de IA","alternativas a t3 chat","t3 chat vs competidores","instalación de agentes de IA","guía de configuración de agentes de IA","desarrollo de aplicaciones con agentes de IA"],"fr":["comment utiliser des outils d''IA","qu''est-ce qu''un outil d''IA","alternatives à t3 chat","t3 chat vs concurrents","installation d''outils d''IA","guide de configuration des outils d''IA","développement d''applications avec des outils d''IA"],"de":["wie man KI-Agenten verwendet","was ist ein KI-Agent","Alternativen zu t3-Chat","t3-Chat vs Wettbewerber","Installation von KI-Agenten","Konfigurationsanleitung für KI-Agenten","Entwicklung von Anwendungen mit KI-Agenten"],"pt":["como usar Custom-Global-Events","o que é Custom-Global-Events","alternativas para t3 chat","Custom-Global-Events vs t3 chat","instalar Custom-Global-Events","guias de configuração para Custom-Global-Events","desenvolvimento de aplicações de chat","habilidades de IA para desenvolvedores"],"ru":["как использовать Custom-Global-Events","что такое Custom-Global-Events","альтернативы для t3 chat","Custom-Global-Events vs t3 chat","установить Custom-Global-Events","руководства по настройке для Custom-Global-Events","разработка приложений чата","навыки ИИ для разработчиков"],"ar":["كيفية استخدام الحدث العامل للجميع","ما هو الحدث العامل للجميع","بديلات لتطبيقات الدردشة","الحدث العامل للجميع مقابل t3 chat","تثبيت الحدث العامل للجميع","دليل إعداد الحدث العامل للجميع","تطوير تطبيقات الدردشة","مهارات الذكاء الاصطناعي للمطورين"]}},"owner":"raythurnvoid","repo":"experiment--t3-chat","repoPath":"raythurnvoid/experiment--t3-chat","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.835Z","topics":[],"category":"community","skillMd":{"name":"custom-global-events","description":"Guidelines for creating/using the app’s typed global events system.","bodyPreview":"# Overview\n\nGlobal events are used for cross-component communication without React context dependencies, allowing for simple function calls to trigger events across different parts of the application.\n\n# Global Events Guidelines\n\nGlobal events are used for cross-component communication without React context dependencies, allowing for simple function calls to trigger events across different parts of the application.\n\n# Overview\n\nThe global events system lives at [global-event.tsx](../../../packag","body":"# Overview\n\nGlobal events are used for cross-component communication without React context dependencies, allowing for simple function calls to trigger events across different parts of the application.\n\n# Global Events Guidelines\n\nGlobal events are used for cross-component communication without React context dependencies, allowing for simple function calls to trigger events across different parts of the application.\n\n# Overview\n\nThe global events system lives at [global-event.tsx](../../../packages/app/src/lib/global-event.tsx) and is built on a typed `Event` subclass (`XCustomEvent`).\n\nIt exposes:\n\n- `global_event_Event`: the canonical type map of event keys → `detail` payload types\n- `global_event_dispatch(event, payload)`: dispatch a typed event (works outside React)\n- `global_event_listen(event, handler, options?)`: listen with typed handler (works outside React)\n- `useGlobalEvent(event, handler)`: React hook for subscriptions with stale-closure protection\n\n# Event key naming\n\nEvent keys are string literals using the pattern:\n\n(`module::event_name`), for example `ai_chat::open_canvas`.\n\n# How to add or modify an event\n\nWhen the user requests a new global event, you must:\n\n# Update the event map\n\nAdd the new event key to the `global_event_Event` map in [global-event.tsx](../../../packages/app/src/lib/global-event.tsx).\n\nExample:\n\n```ts\nexport class global_event_Event extends XCustomEvent<{\n\t\"ai_chat::open_canvas\": {\n\t\tpageId: app_convex_Id<\"pages\">;\n\t\tmode: \"diff\" | \"editor\";\n\t\tmodifiedContent?: string;\n\t\tthreadId: string;\n\t};\n\t\"ai_chat::open_canvas_by_path\": {\n\t\tpath: string;\n\t};\n\t\"docs::focus_path\": {\n\t\tpath: string;\n\t};\n}> {}\n```\n\n# Keep all event keys centralized\n\nAll supported global event keys must be declared in that `global_event_Event` type map. Do not introduce ad-hoc stringly-typed events elsewhere.\n\n# Use the exported helpers\n\nPrefer `global_event_dispatch` / `global_event_listen` / `useGlobalEvent` rather than calling `window.dispatchEvent(new CustomEvent(...))` directly.\n\n# Usage patterns\n\n## React components\n\nUse `useGlobalEvent(eventName, handler)` to subscribe. The handler receives a typed event object, and the payload is on `event.detail`.\n\nExample (from [canvas.tsx](../../../packages/app/src/components/canvas/canvas.tsx)):\n\n```ts\nuseGlobalEvent(\"ai_chat::open_canvas\", (e) => {\n\tconst payload = e.detail;\n\t// payload.pageId, payload.mode, payload.modifiedContent, payload.threadId\n});\n```\n\n## Non-React code (or manual lifecycle control)\n\nUse `global_event_listen` directly when you need to wire AbortController, or you are outside React.\n\n```ts\nconst controller = new AbortController();\n\nconst cleanup = global_event_listen(\n\t\"ai_chat::open_canvas_by_path\",\n\t(e) => {\n\t\tconsole.info(\"path:\", e.detail.path);\n\t},\n\t{ signal: controller.signal },\n);\n\n// later:\ncontroller.abort();\ncleanup();\n```\n\n## Dispatching\n\nUse `global_event_dispatch(eventName, payload)` from anywhere client-side.\n\nExample (from [app-ai-chat.tsx](../../../packages/app/src/components/app-ai-chat.tsx)):\n\n```ts\nglobal_event_dispatch(\"ai_chat::open_canvas_by_path\", { path: args.path });\n```\n\n# Handler typing and payload access\n\nHandlers receive the typed event object, not the payload directly:\n\n```ts\nuseGlobalEvent(\"ai_chat::open_canvas\", (e) => {\n\tconst payload = e.detail;\n});\n```\n\n# Files and references\n\n- Core implementation: [global-event.tsx](../../../packages/app/src/lib/global-event.tsx)\n- Typed event base: `XCustomEvent` in [utils.ts](../../../packages/app/src/lib/utils.ts)\n- Hook helper: `useLiveRef` in [utils-hooks.ts](../../../packages/app/src/hooks/utils-hooks.ts)\n- Example consumers: [app-ai-chat.tsx](../../../packages/app/src/components/app-ai-chat.tsx), [canvas.tsx](../../../packages/app/src/components/canvas/canvas.tsx)\n"},"lastSynced":"2026-03-04T14:45:05.058Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient cross-component communication without React context dependencies","zh":"适用于需要跨组件通信且不依赖于 React 上下文的前端代理","ja":"フロントエンドエージェントが React 上下文の依赖関係を持ちずに、異なるコンポーネント間で効率的に通信する必要がある場合に適しています","ko":"React 컨텍스트의존성을 가지지 않고, 다른 컴포넌트 간의 효율적인 통신이 필요한 프론트엔드 에이전트에게 적합합니다","es":"Perfecto para Agentes Frontend que necesitan una comunicación entre componentes eficiente sin dependencias del contexto de React","fr":"Parfait pour les agents Frontend qui ont besoin d''une communication efficace entre les composants sans dépendances du contexte React","de":"Perfekt für Frontend-Agents, die eine effiziente Kommunikation zwischen Komponenten ohne React-Kontext-Abhängigkeiten benötigen","pt":"Perfeito para Agentes Frontend que necessitam de comunicação cruzada de componentes eficiente sem dependências de contexto do React","ru":"Идеально для агентов Frontend, которым требуется эффективное межкомпонентное общение без зависимостей контекста React","ar":"مثالي للوكلاء الأمامي الذين يحتاجون إلى اتصال متقاطع فعال للعناصر دون اعتمادية على سياق React"},"recommendation":{"en":"Empowers agents to trigger events across different parts of the application using simple function calls, leveraging global events and React context-free communication, with implementations in TypeScript files like global-event.tsx","zh":"允许代理触发应用程序的不同部分的事件，使用简单的函数调用，利用全局事件和 React 上下文的自由通信，并在TypeScript文件中实现，如 global-event.tsx","ja":"エージェントがアプリケーションの異なる部分のイベントをトリガーすることを可能にする、シンプルな関数呼び出しを使用して、グローバルイベントと React 上下文の自由な通信を利用し、TypeScriptファイルで実装します。たとえば、 global-event.tsx","ko":"에이전트가 애플리케이션의 다른 부분의 이벤트를 트리거할 수 있도록하는, 간단한 함수 호출을 사용하여, 전역 이벤트와 React 컨텍스트의 자유로운 통신을 활용하고, TypeScript 파일에서 구현합니다. 예를 들어, global-event.tsx","es":"Habilita a los agentes para desencadenar eventos en diferentes partes de la aplicación utilizando llamadas de función simples, aprovechando eventos globales y una comunicación libre de contexto de React, con implementaciones en archivos TypeScript como global-event.tsx","fr":"Permet aux agents de déclencher des événements dans différentes parties de l''application en utilisant des appels de fonction simples, en exploitant les événements globaux et une communication sans contexte React, avec des implémentations dans des fichiers TypeScript comme global-event.tsx","de":"Ermächtigt Agenten, Ereignisse in verschiedenen Teilen der Anwendung auszulösen, indem einfach Funktionen aufgerufen werden, wobei globale Ereignisse und eine React-Kontext-freie Kommunikation genutzt werden, mit Implementierungen in TypeScript-Dateien wie global-event.tsx","pt":"Habilita os agentes a acionar eventos em diferentes partes do aplicativo usando chamadas de função simples, aproveitando eventos globais e comunicação livre de contexto do React, com implementações em arquivos TypeScript como global-event.tsx","ru":"Наделяет агентов возможностью запускать события в разных частях приложения с помощью простых вызовов функций, используя глобальные события и общение без контекста React, с реализациями в файлах TypeScript, таких как global-event.tsx","ar":"يمنح الوكلاء khảية تشغيل الأحداث عبر أجزاء مختلفة من التطبيق باستخدام نداءات دالة بسيطة، واستغلال الأحداث العالمية والاتصال الخالي من سياق React، مع التنفيذ في ملفات TypeScript مثل global-event.tsx"},"useCases":{"en":["Triggering events across components","Implementing cross-component communication without React context","Debugging global event triggers in TypeScript applications"],"zh":["触发组件间的事件","实现不依赖于 React 上下文的跨组件通信","调试TypeScript应用程序中的全局事件触发器"],"ja":["コンポーネント間のイベントをトリガーする","React 上下文の依赖関係を持ちずに、異なるコンポーネント間で通信することを実現する","TypeScriptアプリケーションのグローバルイベントトリガーのデバッグ"],"ko":["컴포넌트 간의 이벤트를 트리거하는","React 컨텍스트의 의존성을 가지지 않고, 다른 컴포넌트 간의 통신을 실현하는","TypeScript 애플리케이션의 전역 이벤트 트리거의 디버깅"],"es":["Desencadenar eventos entre componentes","Implementar la comunicación entre componentes sin contexto de React","Depurar desencadenadores de eventos globales en aplicaciones TypeScript"],"fr":["Déclencher des événements entre les composants","Mettre en œuvre la communication entre les composants sans contexte React","Déboguer les déclencheurs d''événements globaux dans les applications TypeScript"],"de":["Ereignisse zwischen Komponenten auslösen","Implementierung der Kommunikation zwischen Komponenten ohne React-Kontext","Fehlerbehebung bei globalen Ereignis-Triggern in TypeScript-Anwendungen"],"pt":["Acionar eventos entre componentes","Implementar comunicação entre componentes sem contexto do React","Depurar gatilhos de eventos globais em aplicações TypeScript"],"ru":["Запуск событий между компонентами","Реализация межкомпонентного общения без контекста React","Отладка глобальных триггеров событий в приложениях TypeScript"],"ar":["تشغيل الأحداث بين العناصر","تنفيذ اتصال متقاطع للعناصر دون سياق React","تصحيح أخطاء شروط الأحداث العالمية في تطبيقات TypeScript"]},"limitations":{"en":["Requires knowledge of React and TypeScript","Limited to applications using global events for cross-component communication"],"zh":["需要了解 React 和 TypeScript","仅限于使用全局事件进行跨组件通信的应用程序"],"ja":["React とTypeScriptの知識が必要","グローバルイベントを使用して、異なるコンポーネント間で通信するアプリケーションに限られる"],"ko":["React와 TypeScript의 지식을 필요로 한다","전역 이벤트를 사용하여 다른 컴포넌트 간의 통신을 하는 애플리케이션에만 제한된다"],"es":["Requiere conocimiento de React y TypeScript","Limitado a aplicaciones que utilizan eventos globales para la comunicación entre componentes"],"fr":["Nécessite des connaissances en React et TypeScript","Limité aux applications qui utilisent des événements globaux pour la communication entre les composants"],"de":["Benötigt Kenntnisse von React und TypeScript","Begrenzt auf Anwendungen, die globale Ereignisse für die Kommunikation zwischen Komponenten verwenden"],"pt":["Requer conhecimento de React e TypeScript","Limitado a aplicações que usam eventos globais para comunicação entre componentes"],"ru":["Требует знания React и TypeScript","Ограничен для приложений, использующих глобальные события для межкомпонентного общения"],"ar":["يتطلب معرفة React وTypeScript","محدود للتطبيقات التي تستخدم الأحداث العالمية للاتصال بين العناصر"]},"version":3},"contentHash":"6105e1ccbcf965488032cfc07df80c76ae480aba25674a4ef20454ecdf4cbb7f","qualityScore":46}');
